window.SHENLUN={"行政法": [{"c": "旋轉門條款 釋字637", "k": "限制離職公務員選擇職業自由以避免利益衝突/輸送，手段具實質關聯(合憲)。", "law": "公務員服務法、釋字637。", "trap": "A僅須合理關聯、B謂未限制職業自由、D謂違反比例原則，皆錯。"}, {"c": "行政一體之內涵 釋字613", "k": "稱所有行政事務(含地方自治團體)歸『總統』指揮監督→錯，行政一體歸最高行政首長(行政院長)。", "law": "憲法§53、釋字613。", "trap": "A最終歸最高行政首長統籌、B§53維護行政一體、C經行政院對立院負責落實，皆對。"}, {"c": "法院院長之備詢義務", "k": "地方法院院長負行政職務，就涉及法院預算事項有到會備詢之義務。", "law": "立法院備詢、行政職務。", "trap": "A/B/C謂毋庸出席，皆錯。"}, {"c": "行政訴訟之審判權範圍", "k": "終止公務人員配住宿舍關係係私法(使用借貸)。", "law": "公法私法、行政訴訟。", "trap": "A公保養老給付、B健保特約、C採購決標，皆得提行政訴訟。"}, {"c": "行政釋示之適用", "k": "稱變更函釋之適用『採從新從優原則』→錯，並無此原則(不利者不溯及)。", "law": "行政釋示、釋字287。", "trap": "A自法規生效日有適用、B對法官無拘束力、C前函釋非當然錯誤，皆對。"}, {"c": "依法行政", "k": "給付行政於法規未明定時，得選擇以公法或私法行為為之。", "law": "依法行政原則。", "trap": "A非所有行政行為須法律依據、B裁量仍受法拘束、D內部行政非法外空間。"}, {"c": "合目的性監督之審查 釋字553", "k": "合目的性(妥當性)監督，與原處分機關依訴願法§58重新審查原處分是否『妥當』相似。", "law": "釋字553、訴願法§58。", "trap": "A/B/D係合法性審查，非合目的性。"}, {"c": "聯合稽查之管轄", "k": "稱聯合稽查裁罰涉跨機關權限時『一律以市政府為原處分機關』→錯，以各權限機關為原處分機關。", "law": "行政協助、管轄。", "trap": "A得以行政協助方式進行、B不涉管轄移轉、D管轄爭議由市政府決定，皆對。"}, {"c": "行政規則", "k": "稱內容牴觸上級機關命令者『不當然無效』→錯，牴觸法律或上級命令者無效。", "law": "行政程序法§159。", "trap": "A無須法律授權、B不必然登載公報、D牴觸原機關其他函釋不當然違法，皆對。"}, {"c": "行政處分之附款", "k": "稱附款經相對人同意者『即無不當聯結禁止原則之適用』→錯，縱經同意仍受不當聯結禁止拘束。", "law": "行政程序法§93、§94。", "trap": "A附款不以有裁量權為限、C未履行負擔遭廢止無須補償、D附款得以行政契約代替，皆對。"}, {"c": "再次否准＝第二次裁決(處分)", "k": "重新檢視後仍否准之函復係行政處分(第二次裁決)。", "law": "行政處分、第二次裁決。", "trap": "A觀念通知、B行政指導、D行政契約，皆非。"}, {"c": "撤銷後返還給付 §127", "k": "請求返還給付之處分，因人民提起訴願而不得移送行政執行。", "law": "行政程序法§127。", "trap": "A返還義務於撤銷後始生、B須以書面確認返還範圍、C惡意受領縱不存在仍須返還。"}, {"c": "廢止授益處分之信賴補償 §126", "k": "因處分所依據之事實事後變更，致不廢止對公益有危害而廢止者(§123④)，應補償信賴損失。", "law": "行政程序法§123、§126。", "trap": "A未履行負擔、C法規准許廢止、D保留廢止權，廢止時不予信賴補償。"}, {"c": "代替處分之行政契約無效 §142", "k": "不知與契約內容相同之處分有『得撤銷』之違法原因→契約非無效(僅處分有無效原因時契約才無效)。", "law": "行政程序法§142、§141。", "trap": "A未以書面、C雙務給付顯不相當、D違背公序良俗，皆無效。"}, {"c": "行政契約自願接受執行 §148", "k": "準用行政訴訟法，向地方法院行政訴訟庭聲請強制執行。", "law": "行政程序法§148。", "trap": "A強制執行法、B行政執行法、D民事訴訟法，皆非。"}, {"c": "罰鍰之減輕 §18Ⅲ", "k": "600-3,000元減輕者，最高額及最低額同減至二分之一→300-1,500元。", "law": "行政罰法§18第3項。", "trap": "A/B/D之計算有誤。"}, {"c": "一行為不二罰", "k": "以單一意思於電視為藥物廣告，按『刊播次數』分別處罰→單一行為重複處罰，違反一事不二罰。", "law": "行政罰法§24(一事不二罰)。", "trap": "A無照＋酒駕、B沒收押標金＋停權、C漏三稅分別處罰，皆係數行為或不同性質。"}, {"c": "公物／既成道路", "k": "稱既成道路『未經法律行為設定且為私有，非屬公物』→錯，既成道路成立公用地役關係屬公物。", "law": "公物、既成道路。", "trap": "A公物設定廢止為一般處分、B行政用物亦屬公物、D地下水屬國家所有之公物，皆對。"}, {"c": "登記註記之救濟", "k": "註記未改變土地使用管制→非行政處分，應提一般給付訴訟請求註銷。", "law": "行政處分之認定、一般給付訴訟。", "trap": "A/B認係行政處分循訴願撤銷或課予義務、D僅得國賠，皆非。"}, {"c": "拘提與管收 行政執行法", "k": "管收應由執行機關聲請法院裁定。", "law": "行政執行法§17。", "trap": "A遭管收不免除義務、C拘提得請求職務協助、D拘提不得逾24小時(無延長)。"}, {"c": "行政程序之職權調查 §9、§36", "k": "應依職權或申請調查事實證據，對有利不利事項一律注意。", "law": "行政程序法§9、§36。", "trap": "A公同共有送達一人非對全體、C限制住居非均須事先陳述、D經聽證之處分應斟酌(非當然受拘束)。"}, {"c": "閱覽卷宗 vs 政府資訊公開", "k": "兩法就資訊錯誤均有請求更正之規定。", "law": "行政程序法§46、政府資訊公開法。", "trap": "A申請人資格不同、C擬稿準備資訊非『皆應』不予公開、D資訊公開須先訴願(非均得逕提訴訟)。"}, {"c": "否准候選人登記之被告", "k": "實際否准者中央選舉委員會為被告。", "law": "行政訴訟、原處分機關。", "trap": "A縣選委會僅轉知、B縣政府、D行政院，皆非。"}, {"c": "受託團體之訴願管轄", "k": "受委託團體以自己名義作成處分，以委託機關乙為訴願管轄機關。", "law": "訴願法§10。", "trap": "A受託團體、C/D其主管或設立機關，皆非。"}, {"c": "公民訴訟／怠為處分課予義務訴訟", "k": "機關怠於執行，提怠為處分之課予義務訴訟，請求判命作成令限期移除之處分。", "law": "廢棄物清理法§71、行政訴訟法§5。", "trap": "A視為否准提撤銷、C確認、D一般給付，皆非。"}, {"c": "行政訴訟不採之民訴制度", "k": "公示催告(行政訴訟所不採)。", "law": "行政訴訟法。", "trap": "B假處分、C假扣押、D證據保全，行政訴訟均有。"}, {"c": "國家賠償之求償 §3Ⅱ", "k": "就損害原因有應負責任之人(如委外廠商)，輕過失即得求償。", "law": "國家賠償法§2Ⅲ、§3Ⅱ。", "trap": "A公務員、C受託私人、D審判追訴職務之公務員，須故意或重大過失始得求償。"}, {"c": "國家賠償之範圍", "k": "稱國賠範圍『僅限財產上損害不含非財產上損害』→錯，含非財產上損害(慰撫金)。", "law": "國家賠償法§5(準用民法)。", "trap": "A以金錢賠償為原則、B含所受損害及所失利益、D適用與有過失原則，皆對。"}, {"c": "國家賠償 vs 損失補償", "k": "公務員合法行使公權力致特別犧牲→損失補償問題。", "law": "國家賠償、損失補償。", "trap": "A違法行為國賠以故意過失為要件、C退稅為公法不當得利、D賠償後得向有故意重大過失之公務員求償。"}, {"c": "法官得表示不同見解者", "k": "行政函釋(法官得引用，但得依法律表示不同見解)。", "law": "憲法§80、行政函釋。", "trap": "A身障公約、B緊急命令、D大法官憲法解釋，對法官有拘束力。"}, {"c": "信賴保護原則", "k": "稱機關依法修改法規『無須兼顧規範對象信賴利益保護』→錯，應兼顧信賴利益。", "law": "信賴保護、釋字525。", "trap": "A提供不實資料無信賴保護、B有利人民之溯及不違信賴保護、D得訂過渡條款保護信賴，皆對。"}, {"c": "管轄權變動／受託行使公權力", "k": "受託行使公權力者，對外須以受託之私人團體或個人名義行文。", "law": "行政程序法§15、§16。", "trap": "A委任係上級委下級、B委由直轄市行使為委辦(非委託)、D受託得以法規或契約授權(不限處分)。"}, {"c": "免職前之陳述意見 釋字491", "k": "免職處分作成前應通知陳述意見使有答辯機會，並應合法送達。", "law": "釋字491、行政程序法§102。", "trap": "B起訴書記載非一律免通知、C/D免除陳述意見之敘述，皆錯。"}, {"c": "不直接對外發生法規範效力者", "k": "臺北市交通局之審議作業程序(內部行政規則)。", "law": "行政規則 vs 法規命令。", "trap": "A施行法、B改制辦法、D統一裁罰基準及處理細則(裁量基準間接對外)，較具對外效力。"}, {"c": "行政命令之效力 §160", "k": "行政規則自有效下達下級機關或屬官時起生效。", "law": "行政程序法§157、§160。", "trap": "A法規命令發布即生效(非經立院確認)、C無授權剝奪權利者無效、D廢止解釋性規則須刊登公報。"}, {"c": "撤銷 vs 廢止", "k": "停播期間擅自播送(嗣後違規)致吊銷執照→係合法處分之『廢止』。", "law": "行政程序法§117(撤銷)、§122-§125(廢止)。", "trap": "A撤銷(針對原違法)、C轉換、D確認無效，皆非。"}, {"c": "構成要件效力", "k": "都發局不得否認社會局核定之低收入戶身分→構成要件效力。", "law": "行政處分之構成要件效力。", "trap": "A既判力、B形式存續力、D執行力，皆非。"}, {"c": "直接對外發生法律效果者", "k": "一般處分直接對外發生法律效果。", "law": "行政處分。", "trap": "A行政規則、B陳情答覆、C行政指導，不直接對外發生法律效果。"}, {"c": "行政處分無效之事由 §111", "k": "不能得知處分機關者無效(§111①)。", "law": "行政程序法§111。", "trap": "A送達不合法、B未踐行意見陳述、C理由不備，僅得撤銷或得補正，非無效。"}, {"c": "行政契約之認定", "k": "台鐵與旅客之運送契約屬私法。", "law": "行政契約。", "trap": "B聘用契約、C ETC建置營運契約、D委託汽車定期檢驗合約，皆為行政契約。"}, {"c": "裁罰性不利處分", "k": "以偽造證件投標者刊登政府採購公報停權3年→裁罰性不利處分。", "law": "行政罰法§2。", "trap": "A下架回收(管制)、B撤銷未開業證照(非裁罰)、C不予開標(非裁罰)。"}, {"c": "限制通行公告＝一般處分", "k": "橋樑公告限腳踏車及行人通行→行政處分(一般處分)。", "law": "行政程序法§92(一般處分)。", "trap": "A事實行為、B法規命令、D行政規則，皆非。"}, {"c": "公物之利用", "k": "公共用物除通常使用外，亦可能為特別使用。", "law": "公物法理。", "trap": "B公物利用非皆公法關係、C自然河川地得成公物、D公物成立不限法律行為(亦得依事實)。"}, {"c": "程序外接觸 §47", "k": "程序外接觸應作成書面紀錄，載明接觸對象、時間、地點及內容。", "law": "行政程序法§47。", "trap": "A主動對外公開、C不對其他當事人公開、D作成錄音檔，皆非。"}, {"c": "閱覽卷宗與更正 §46", "k": "稱卷宗內容『縱與其自身無關亦可請求更正』→錯，僅得請求更正與其自身相關之記載。", "law": "行政程序法§46。", "trap": "A原則准許例外拒絕、B限當事人及利害關係人、D以維護法律上利益必要者為限，皆對。"}, {"c": "訴願之合法要件", "k": "沒入並銷毀之產品已銷毀完畢→撤銷標的不存在，不得提撤銷訴願。", "law": "訴願法。", "trap": "A公法人得為訴願人、B課稅須先復查不得逕訴願、C原處分機關撤銷後訴願標的消滅。"}, {"c": "行政法院之審判權範圍", "k": "撤銷對公務員之免職處分→向行政法院提起。", "law": "行政訴訟、審判權。", "trap": "A選舉無效(普通法院)、B國賠(普通法院)、C社維法罰鍰(地方法院)，皆非行政法院。"}, {"c": "行政訴訟之強制執行", "k": "許提第三人異議之訴，由普通法院受理。", "law": "行政訴訟法。", "trap": "A/B/C對停止執行、執行名義、債務人異議之訴之敘述有誤。"}, {"c": "執行完畢後之違法確認訴訟", "k": "拆除處分已執行完畢→提違法確認訴訟。", "law": "行政訴訟法§6。", "trap": "A撤銷(標的已消滅)、B課予義務、D一般給付，皆非。"}, {"c": "交通裁決事件之上訴", "k": "稱上訴『須經高等行政法院之許可』→錯，不須許可，但須以違背法令為由。", "law": "行政訴訟法(交通裁決事件)。", "trap": "A上訴於高等行政法院、B非違背法令不得上訴、D二審判決不得再上訴，皆對。"}, {"c": "簡易訴訟程序", "k": "簡易訴訟之起訴得以言詞為之，第一審由地方法院行政訴訟庭管轄。", "law": "行政訴訟法§229以下。", "trap": "B不必然不經言詞辯論、C移送方式有誤、D上訴抗告之限制敘述有誤。"}, {"c": "應經訴願之事件", "k": "不服課稅處分之撤銷訴訟→應經訴願(及復查)。", "law": "訴願先行。", "trap": "A交通裁決逕行起訴、B經聽證之處分免訴願、C確認訴訟不經訴願。"}, {"c": "委任事件之國賠義務機關 §9", "k": "辦理上級委任事件致國賠者，由受委任機關為賠償義務機關。", "law": "國家賠償法§9。", "trap": "A委任機關、C/D上級機關，皆非。"}, {"c": "國家賠償之歸責原則", "k": "公共設施瑕疵之國賠採無過失責任。", "law": "國家賠償法§2、§3。", "trap": "A國賠由普通法院民事審判(爭議性質特殊)、B公務員不法行為採過失責任、D特別犧牲屬補償非賠償。"}, {"c": "國賠之審判權與程序", "k": "稱國賠訴訟審判權『原則上歸地方法院行政訴訟庭』→錯，由普通法院民事庭審判。", "law": "國家賠償法。", "trap": "A應先以書面向賠償義務機關請求、C得於撤銷訴訟合併請求國賠、D協議逾60日不成立得起訴，皆對。"}, {"c": "司法/檢察職務之國賠特別要件 §13", "k": "檢察官(及法官)執行職務，須因此犯職務上之罪經判決有罪確定，始有國賠適用。", "law": "國家賠償法§13。", "trap": "A立委、C監委、D受託私人，不適用§13之特別要件。"}, {"c": "行政院之職權", "k": "稱依緊急命令授權訂之補充規定『無須提交立院追認即得執行』→錯，緊急命令及其補充規定應送立院追認。", "law": "憲法§58、§57、增修§3。", "trap": "A預算案專屬行政院、B覆議權、C人事提名權不容立院剝奪，皆對。"}, {"c": "行政機關訂定之規範", "k": "『桃園市發展低碳城市自治條例』由地方議會(立法機關)制定。", "law": "自治條例 vs 行政命令。", "trap": "B獎勵辦法、C作業準則、D認證要點，皆為行政機關訂定之規範。"}, {"c": "處罰法定原則 §4", "k": "裁罰時過度擴張解釋法定義務構成要件→違反處罰法定原則。", "law": "行政罰法§4(處罰法定)。", "trap": "A比例、B平等、C明確性原則，非本題所指。"}, {"c": "判斷餘地下之程序審查", "k": "學者專家評分過程未給陳述意見機會(評分屬判斷餘地，無須給陳述意見)。", "law": "判斷餘地、行政程序。", "trap": "A出席人數不足、C應迴避未迴避、D漏未斟酌重要事項，皆得撤銷。"}, {"c": "得提行政爭訟之要件(有無請求權)", "k": "廠商投標經認定不符投標資格→得提行政爭訟(政府採購異議申訴)。", "law": "行政訴訟、保護規範理論。", "trap": "A闢建公園、B登錄歷史建築、C加強檢查，人民僅有反射利益，不得爭訟。"}, {"c": "國民年金之訴願管轄", "k": "勞保局為原處分機關，以中央主管機關衛生福利部為訴願機關。", "law": "受託行使公權力、訴願法。", "trap": "A勞動部、B內政部、D以委託機關為原處分機關，皆非。"}, {"c": "委託民間團體與國賠 §4", "k": "提國賠應以委託機關A為被告。", "law": "國家賠償法§4(受委託團體以委託機關為賠償義務機關)。", "trap": "A B非行政助手(係受託行使公權力)、B訴願管轄為委託機關、C行政訴訟以受託團體為被告。"}, {"c": "無效行政處分之確認", "k": "稱處分是否無效之爭議得透過『課予義務訴訟』解決→錯，應提確認行政處分無效訴訟。", "law": "行政程序法§110、§111、確認訴訟。", "trap": "A自始不生效力無須宣告、B不因追認或時間經過治癒、D執行無效下命處分產生國賠責任，皆對。"}, {"c": "解釋性行政規則之生效", "k": "稱解釋性行政規則『自登載公報次日生效、不適用於之前事件』→錯，係闡明法規原意，自『法規生效日』即有適用。", "law": "行政程序法§160、§161。", "trap": "B內部組織行政規則自下達生效、C間接對外效力、D內部組織規則無須登載公報，皆對。"}, {"c": "法定義務之註記 vs 附款", "k": "許可中附記『仍應符合外國人持股限制，違反得廢止』係『法定義務之註記』(重申法定義務)，非附款。", "law": "行政程序法§93(附款)。", "trap": "A負擔、B保留廢止權、C保留事後附加負擔，皆非。"}, {"c": "行政處分之概念", "k": "稱『限制人民權利乃行政處分之概念要素』→錯，行政處分含授益，不以限制權利為要素。", "law": "行政程序法§92。", "trap": "A立法院亦可能作成處分、C得以書面言詞甚至手勢作成、D撤銷處分本身亦為處分，皆對。"}, {"c": "一般處分與訴願期間", "k": "稱對該公告不服『於公告後3年內皆得提起訴願』→錯，訴願期間30日，自公告期滿次日起算。", "law": "行政程序法§100(一般處分)、訴願法§14。", "trap": "A屬一般處分、B公告日生效、C訴願期間自公告期滿次日起算，皆對。"}, {"c": "公法上請求權時效 §131", "k": "返還補助款請求權之消滅時效，自通知廢止補助時起5年。", "law": "行政程序法§131(公法請求權時效5年)。", "trap": "A/B/D起算點或年限有誤。"}, {"c": "行政罰從新從輕 §5", "k": "應適用對受處罰人最有利之5月修訂後規定(3,500-6,000元)。", "law": "行政罰法§5。", "trap": "A行為時、C第二次修訂、D混合上下限，皆非。"}, {"c": "公物之利用與管理", "k": "稱國小防疫禁止校外人進入為『公物警察權之行使』→錯，係公物主體之管理權(提供利用範圍之劃定)。", "law": "公物法理。", "trap": "A公有公共用物不適用取得時效、B管制山區非公共用物、C搭戲台為公物特別使用，皆對。"}, {"c": "事實行為 vs 規制性行為", "k": "警員舉牌引導之指示行為(具規制/指揮性質)。", "law": "行政事實行為。", "trap": "A小心行人、B連續彎路、C速限標誌(警告/標誌)，本題歸為事實行為。⚠️標誌之定性實務有不同見解，可對照詳解。"}, {"c": "公法上金錢給付義務 §2", "k": "健保署通知特約醫院返還虛報醫療費用(係行政契約上請求，不得逕移送行政執行)。", "law": "行政執行法§2。", "trap": "A工程受益費、C代履行費用、D空污費，皆為公法上金錢給付義務。"}, {"c": "金錢給付義務之執行機關", "k": "稅捐稽徵機關(稅捐之執行移送行政執行署，稅捐機關自己不執行)。", "law": "行政執行法。", "trap": "B行政執行署分署、C受囑託之地院民事執行處、D地院行政訴訟庭，皆為執行機關。"}, {"c": "行政契約 vs 申請處分之差異", "k": "稱行政契約『得依約定而撤銷』→錯，契約有終止/調整規定，撤銷係針對處分。", "law": "行政契約、行政處分。", "trap": "A要約承諾 vs 申請、B書面要求之差異、D無效之準用與重大明顯瑕疵，皆對。"}, {"c": "應給陳述意見之情形 §102", "k": "對公務員作一次記二大過專案考績免職(剝奪身分)→應給陳述意見機會。", "law": "行政程序法§102。", "trap": "A否准申請、B已書面通知陳述、C已舉行聽證，無須再給。"}, {"c": "法規違憲後訴願之處理", "k": "所依據法規經宣告違憲自公布日不予適用→訴願機關應撤銷原處分。", "law": "行政罰、違憲失效。", "trap": "B無效、C廢止、D維持原處分，皆非。"}, {"c": "標的消滅之訴訟類型轉換", "k": "履約即將完畢(撤銷標的將消滅)，法院應闡明曉諭原告是否變更為確認違法之訴。", "law": "行政訴訟法(闡明、確認違法之訴)。", "trap": "A仍判撤銷、C情況判決、D追加賠償，皆非最適。"}, {"c": "訴願決定變更後之被告(官方送分)", "k": "要記重點：經訴願程序，駁回時以原處分機關為被告；訴願決定撤銷或變更原處分時，以作成訴願決定之機關為被告。本題涉委任(環保局)與訴願變更之被告認定，故送分。", "law": "行政訴訟法§24(被告之認定)。", "trap": ""}, {"c": "訴訟類型／課予義務訴訟", "k": "行政機關之財產上給付應以行政處分為決定者，原告應提課予義務訴訟。", "law": "行政訴訟法§5、§8。", "trap": "A課予義務訴訟之定義有誤、C一般給付訴訟不經訴願、D撤銷判決非強制執行名義。"}, {"c": "執行通知之聲明異議 §9", "k": "對B函(執行通知)得依行政執行法§9向乙縣政府聲明異議。", "law": "行政執行法§9、行政程序法、訴願法。", "trap": "A/C對A函(已逾訴願/起訴期間)、B對B函提訴願之敘述有誤。"}, {"c": "阻止發布警告／假處分", "k": "阻止主管機關發布警告(預防性不作為)→假處分。", "law": "行政訴訟法(假處分)。", "trap": "A假扣押、C假執行、D停止執行，皆非。"}, {"c": "國家賠償之成立", "k": "機關將空間無償出借私人全權管理經營餐飲，民眾因地板突起摔傷→非國家管理之公共設施。", "law": "國家賠償法§2、§3。", "trap": "A行政助手過失、B書記官誤列分配表、D司機公務車致傷，皆成立國賠。"}, {"c": "土地徵收／收回權為公法請求權", "k": "稱原所有權人之收回權『係私法上請求權』→錯，係公法上請求權。", "law": "憲法§15、土地徵收、釋字。", "trap": "A應踐行最嚴謹程序、B應公告及書面通知、C補償未儘速發給徵收失效，皆對。"}, {"c": "行政院與立法院關係", "k": "稱立院得『決議移請行政院變更政策、行政院得移請覆議』→錯，現制已刪除移請變更政策之機制。", "law": "增修條文§3。", "trap": "A院長由總統直接任命、B NCC主委有備詢義務、C執行緊急命令之要點仍送立院，皆對。"}, {"c": "法院聲請憲法審查之主體 憲訴法", "k": "稱聲請主體為『各級法院院長』→錯，係受理案件之法官/法院。", "law": "憲法訴訟法、釋字371/572。", "trap": "A聲請書記載事項、B須對裁判結果有直接影響、D法官合理確信牴觸憲法，皆對。"}, {"c": "行政之種類", "k": "稱審核社會住宅資格決定是否締約為『行政營利行為』→錯，係給付行政。", "law": "給付行政、私經濟行政。", "trap": "A給付行政得選公法或私法手段、B出售公有財產為私法契約、C登錄歷史建築為公權力行政，皆對。"}, {"c": "公權力行為 vs 私經濟", "k": "台電取消夏日電價方案→私經濟行為。", "law": "公權力行政 vs 私經濟行政。", "trap": "A延長防疫警戒、B停止灌溉、C命車廂配戴口罩，皆為公權力行為。"}, {"c": "行政法之法源", "k": "最高行政法院庭長法官聯席會議決議(大法庭施行後不再有拘束力)。", "law": "行政法法源、大法庭制度。", "trap": "B職權命令、C自治規則、D依授權與外國簽署之協定，皆為法源。"}, {"c": "裁量濫用", "k": "僅考慮『B廠商曾違規廣告』(與A販售菸品予少年無關之考量)即裁處A最高罰→摻雜不相關考量＝裁量濫用。", "law": "行政程序法§10、裁量瑕疵。", "trap": "A適法、B逾越、C不當，皆非。"}, {"c": "指定管轄不得聲明不服 §14", "k": "對共同上級機關之指定管轄決定，不得聲明不服。", "law": "行政程序法§14(指定管轄)。", "trap": "A/B/C提起訴願或訴訟，皆非。"}, {"c": "權限委託之訴願管轄", "k": "屬權限委託，應向委託機關監察院提起訴願。", "law": "行政程序法§15(委託)、訴願法。", "trap": "A中選會、C直轄市政府、D逕提行政訴訟，皆非。"}, {"c": "地方自治與法律之拘束", "k": "縣市都市計畫之擬定審議雖屬自治事項，仍受都市計畫法拘束。", "law": "地方制度法、都市計畫法、釋字738。", "trap": "A/B電子遊戲場距離(地方得另定更嚴格規定)、D都計變更不受拘束，皆錯。"}, {"c": "政務人員之懲戒", "k": "不服懲戒法庭第一審終局判決，得上訴第二審(一級二審)。", "law": "公務員懲戒法。", "trap": "A懲戒須可歸責、B政務人員不適用休職、C審理不當然先停職。"}, {"c": "行政規則之拘束力", "k": "稱下級機關認上級行政規則違法者『得拒絕適用』→錯，下級受拘束不得拒絕適用。", "law": "行政程序法§159(行政規則)。", "trap": "A訂行政規則無須聽證、B得由原發布機關廢止、D法院不受行政規則拘束，皆對。"}, {"c": "違法授益處分之撤銷 §117-§121", "k": "撤銷前未給受看護者(非處分相對人)陳述意見機會，並不違法。", "law": "行政程序法§117(撤銷)、§121(2年除斥)。", "trap": "A應『撤銷』非廢止、B撤銷得溯及非一律自撤銷日失效、C撤銷權自『知有撤銷原因』起2年。"}, {"c": "停止條件之附款", "k": "附『須獲居民同意為生效要件』之停止條件，稱『送達後甲即得開始興建』→錯，條件成就前不生效不得興建。", "law": "行政程序法§93(附款)。", "trap": "A性質為停止條件、B得為附款、D不服得提爭訟，皆對。"}, {"c": "廢止處分前之陳述意見 §102", "k": "作成廢止處分前原則上應給予甲陳述意見機會。", "law": "行政程序法§102、§123、§125。", "trap": "A廢止無2年除斥之框架、C廢止自廢止時(非原因發生時)失效、D廢止合法處分因可歸責於受益人不予補償。"}, {"c": "行政契約之補償 §145", "k": "因第三機關(交通局修路)致甲損失，締約之環保局應補償甲不可預期損失。", "law": "行政程序法§145(締約機關外公權力行使之補償)。", "trap": "A/B/C對請求對象或調整權之敘述有誤。"}, {"c": "行政契約之違約金 §149", "k": "違約金之約定，行政程序法未規定者準用民法相關規定。", "law": "行政程序法§149(準用民法)。", "trap": "A得以契約約定、B非須上級事前同意、D不限金錢給付義務。"}, {"c": "一行為之認定", "k": "10分鐘內在同街區20台機車各夾廣告單→自然一行為，僅構成一個違反廢清法之行為。", "law": "行政罰法、一行為之認定。", "trap": "A按日連續處罰不得一次送達、B一申報單三稅為三行為、C緩起訴後仍得追究行政罰。"}, {"c": "裁罰管轄競合 §31", "k": "由處理在先之機關優先裁罰。", "law": "行政罰法§31(管轄競合由處理在先者管轄)。", "trap": "A/B/D由特定機關優先、協議或上級指定，皆非。"}, {"c": "行政主體(行政法人)", "k": "國家資通安全研究院(行政法人)為行政主體。", "law": "行政主體、行政法人。", "trap": "A中研院、B NCC、C國教院，皆為行政機關而非獨立之行政主體。"}, {"c": "行政事實行為 vs 行政處分", "k": "認定特定土地為公用地役關係既成道路→行政處分(認定/確認)。", "law": "行政事實行為。", "trap": "A斷水斷電(直接強制)、B發布新聞稿、C促請金融機構遵循，皆為事實行為。"}, {"c": "執行概念之範圍", "k": "行政訴訟法上之『停止執行』概念範圍最廣(涵蓋各種處分執行之停止)。", "law": "行政執行、停止執行。", "trap": "A下命處分執行力、B金錢給付義務執行、D行為義務執行，範圍較窄。"}, {"c": "第三人異議之訴", "k": "漁船所有權人甲應向普通法院提起第三人異議之訴。", "law": "行政執行法準用強制執行法、第三人異議之訴。", "trap": "A債務人異議之訴(係義務人)、C/D聲明異議或申請終止執行，皆非排除執行名義之正確途徑。"}, {"c": "聽證程序", "k": "稱『僅於法律明文規定時始負舉行聽證義務』→錯，行政機關亦『得』舉行聽證。", "law": "行政程序法§107。", "trap": "B重大公共設施計畫確定須聽證、C訂法規命令聽證應公告、D不服經聽證之處分得逕提行政訴訟，皆對。"}, {"c": "程序重開之決定為處分 §128", "k": "稱重開程序所為之決定『均非行政處分、不得爭訟』→錯，駁回重開之決定是處分得爭訟。", "law": "行政程序法§128、§129。", "trap": "A兩階段、B以新證據申請且限可受較有利處分、D非相對人或利害關係人不得申請，皆對。"}, {"c": "訴願 vs 司法性質之懲戒覆審", "k": "律師懲戒覆審委員會之覆審屬司法性質(審級救濟)，非訴願。", "law": "訴願法、律師懲戒。", "trap": "A向行政院訴願、B向考試院訴願、D會計師懲戒覆審，皆相當於訴願。"}, {"c": "通常 vs 簡易訴訟程序", "k": "2萬罰鍰『併公布負責人姓名』(含非財產上處分)→應適用通常訴訟程序。", "law": "行政訴訟法§229(簡易程序)。", "trap": "B/C/D屬簡易或特殊程序。"}, {"c": "暫時權利保護／假處分", "k": "請求法院命機關暫先提供紓困貸款(課予義務性質)→假處分。", "law": "行政訴訟法(假處分)。", "trap": "A假扣押(金錢請求保全)、C假執行、D停止執行(撤銷訴訟用)，皆非。"}, {"c": "確認訴訟", "k": "應提撤銷訴訟誤提確認無效之訴且未經訴願者，行政法院應裁定移送訴願管轄機關。", "law": "行政訴訟法§6(確認訴訟)。", "trap": "A確認補充性、B確認無效無2個月期間、C法院非依職權逕行確認違法，皆錯。"}, {"c": "民事審判權／國家賠償", "k": "於機關門口臺階跌傷請求賠償→國家賠償，屬民事法院審判權。", "law": "國家賠償(普通法院民事審判)。", "trap": "A駁回申請(行政)、B返還申請費用(公法)、C請求懲處承辦人員(公法)，皆非民事。"}, {"c": "公共設施國賠之抗辯", "k": "該公共設施設置或管理『並無欠缺』(不可抗力，任何堅固橋墩皆會被沖垮)→得拒絕賠償。", "law": "國家賠償法§3。", "trap": "A被害人死亡其家屬得請求、B橋為公共設施、D公共設施國賠採無過失責任(不以故意過失為要件)。"}, {"c": "外國判決之承認與許可執行", "k": "稱『因債務人於我國無住所，我國法院對許可執行之訴無管轄權』→錯，得以應執行財產所在地定管轄。", "law": "民事訴訟法§402、強制執行法§4-1。", "trap": "A外國判決須經許可執行判決、C許可執行採形式審查不為實質再審查，皆對。"}, {"c": "權利救濟請求權", "k": "憲法並未規定訴願審議委員會之具體組成方式。", "law": "訴願權、訴訟權§16。", "trap": "A訴願先行非不必要限制、B訴願範圍不必與法院相同、C請願未獲處理不得逕提訴願，皆錯。"}, {"c": "立委聲請法規範審查 憲訴法", "k": "緊急命令有違憲疑慮，符法定人數之立委得提出聲請。", "law": "憲法訴訟法(立委聲請)。", "trap": "B須現有總額1/4以上(非1/5)、C少數立委認表決權受侵害得聲請、D 6個月期間，皆錯。"}, {"c": "機關爭議案件", "k": "稱機關爭議『為憲訴法新增、以往並無類此案件』→錯，以往釋字亦處理機關權限爭議。", "law": "憲法訴訟法(機關爭議)。", "trap": "B限國家最高機關間之憲法權限爭議、C應先協商、D 6個月不變期間，皆對。"}, {"c": "行政之監督密度", "k": "稱下級機關事務執行『皆受上級合法性及合目的性監督』→錯，自治事項僅受合法性監督。", "law": "行政之特性、監督。", "trap": "A主動性、B手段多樣性、D得訂法規命令及行政規則，皆對。"}, {"c": "行政規則無須法律授權", "k": "稱『行政機關訂行政規則須有法律授權』→錯，行政規則無須法律授權。", "law": "法律保留、行政規則§159。", "trap": "A單有組織法依據不足、B自治條例得限制居民基本權、D無轉委任授權不得再委任，皆對。"}, {"c": "裁量基準之司法審查", "k": "依裁量基準作成之處分若違反比例原則，訴願機關或法院仍得撤銷。", "law": "裁量基準、比例原則。", "trap": "A/B認應受拘束即無違法、D認裁量基準為法規命令，皆錯。"}, {"c": "中央機關之設置", "k": "稱『經行政院會議及立法院決議得增設裁併各部會』→錯，機關組織以法律定之。", "law": "中央行政機關組織基準法。", "trap": "B四級機關組織得以命令定、C得設臨時機關、D內部單位以處務規程定，皆對。"}, {"c": "管轄權之設定變更", "k": "稱『管轄權移轉未公告不影響效力』→錯，管轄變更須公告始生移轉效力。", "law": "行政程序法§11(管轄法定)。", "trap": "A管轄非依法不得設定變更、C得委託中央執行自治事項、D移轉法規應與設定法規同位階，皆對。"}, {"c": "公務員服務法之適用", "k": "直轄市長、縣市長、鄉鎮市長亦適用公務員服務法。", "law": "公務員服務法、公務人員保障法。", "trap": "A、B、C對公務人員名稱、保障法適用對象、任命程序之敘述有誤。"}, {"c": "公務員懲戒", "k": "政務人員與地方民選首長得受懲戒處分之種類相同。", "law": "公務員懲戒法。", "trap": "A非逕由首長移送、B以言詞辯論為原則(非書面)、C得救濟(非一審終結無上訴)。"}, {"c": "行政機關訂定之法規", "k": "職務命令(上級對下級之個別指示)非法規。", "law": "法規範之種類。", "trap": "A職權命令、B委辦規則、D行政規則，皆為行政機關訂定之法規範。"}, {"c": "補助處分之存續力", "k": "未廢棄補助處分前，該處分仍有存續力，金錢給與仍有法律上原因。", "law": "行政程序法§110(存續力)、§123廢止。", "trap": "B挪用係違反負擔應『廢止』(非撤銷)、C時效非一律5年、D提訴願時是否移送執行有誤。"}, {"c": "附款之認定 §93", "k": "核准遊行但限制路線→係處分『內容(主規制)之一部』，非附款。", "law": "行政程序法§93(附款)。", "trap": "A收攤清理(負擔)、B 1年內出國否則喪失(解除條件)、C回國繳報告(負擔)，皆為附款。"}, {"c": "行政契約之單方調整 §146", "k": "契約內容對公益重大危害時，機關得不經對方同意於必要範圍調整契約。", "law": "行政程序法§146、§147。", "trap": "A書面不以同一文書為必要、B限制權利契約之法律保留敘述有誤、D代替處分之契約仍須經應同意機關同意。"}, {"c": "行政罰之認定", "k": "對借牌投標廠商刊登政府採購公報停權3年→裁罰性不利處分，有行政罰法適用。", "law": "行政罰法§1、§2。", "trap": "A命回復原狀(管制)、B限制出境(保全)、C代履行費用(執行)，非行政罰。"}, {"c": "共同違反行政法義務 §14", "k": "對共同行為人分別處罰，依個別情節審酌罰鍰金額。", "law": "行政罰法§14。", "trap": "A共同實施限故意(不含過失)、C無身分共同行為人『仍處罰』、D無罰鍰總額上限之規定。"}, {"c": "法人之故意過失推定 §7Ⅱ", "k": "受僱人乙之故意過失，『推定』甲公司有故意過失，甲公司仍應受罰。", "law": "行政罰法§7。", "trap": "A行政罰不以故意過失為要件→錯、B無故意過失不罰→與推定規定不符、C『視為』→應為推定。"}, {"c": "公物", "k": "稱公物『一律不得為設定目的外之使用』→錯，得經許可為目的外使用。", "law": "公物法理。", "trap": "A未徵收之既成道路雖私有仍屬公物、C設定公物為行政處分、D亦得依事實成立，皆對。"}, {"c": "行政事實行為", "k": "以暴雨來襲要求露營民眾撤離(下命)→行政處分。", "law": "行政事實行為 vs 行政處分。", "trap": "B發放補貼、C提供錯誤資訊、D錄影蒐證，皆為事實行為。"}, {"c": "直接強制 vs 即時強制", "k": "消防救火將合法停放車輛拖離→即時強制(非直接強制)。", "law": "行政執行法(直接強制/即時強制)。", "trap": "A斷水電、B強制拆除、D沒入後強制移置，皆為直接強制。"}, {"c": "行政處分 vs 觀念通知", "k": "C函(預告拆除大隊將於X日前往拆除)→觀念通知/執行行為之預告。", "law": "行政處分§92、執行行為。", "trap": "A認定違建命補辦、B限期拆除、D命繳拆除費，皆為行政處分。"}, {"c": "行政執行 vs 行政罰", "k": "酒駕當場吊扣駕照→裁罰處分(行政罰)，非行政執行。", "law": "行政執行法。", "trap": "A拘提、C禁奢(限制)、D消防破壞進入(即時強制)，皆適用/準用行政執行法。"}, {"c": "行政程序之迴避 §32", "k": "處理其『曾指導之博士生』之申請→師生關係非§32法定迴避事由。", "law": "行政程序法§32(自行迴避)。", "trap": "A配偶、B前配偶、D曾任律師代理之案件，皆應自行迴避。"}, {"c": "程序重開之函覆 §128", "k": "稱僅重申原處分內容為『重覆處置不得爭訟』→錯，駁回重開申請係新處分得爭訟。", "law": "行政程序法§128(程序重開)。", "trap": "B駁回得爭訟、C認符要件惟原處分正當而駁回得爭訟、D廢止後利害關係人乙得爭訟，皆對。"}, {"c": "相當於訴願之程序", "k": "律師懲戒覆審委員會之覆審決定→相當於終審裁判(司法)。", "law": "訴願先行/相當訴願之程序。", "trap": "A保訓會復審、B採購申訴審議判斷、C犯保覆審覆議，皆相當於訴願。"}, {"c": "暫時權利保護", "k": "稱確認處分無效訴訟『應適用假處分程序』→與制度不符。", "law": "行政訴訟法(停止執行/假處分)。", "trap": "A撤銷罰鍰用停止執行、B課予義務用假處分、C給付訴訟用假處分，皆對。"}, {"c": "審判權移送 §12-2", "k": "稱受移送行政法院亦認無審判權應『聲請司法院解釋』→錯，應向最高法院請求指定。", "law": "行政訴訟法§12-2、法院組織法§7-1。", "trap": "A以裁定移送、C最高法院認定後受移送法院應受理、D不爭執而裁判者上級審不得以無審判權廢棄，皆對。"}, {"c": "收容聲請事件", "k": "稱對收容處分不服『亦得提起撤銷訴訟』→錯，採收容異議等收容聲請程序。", "law": "行政訴訟法(收容聲請事件)。", "trap": "A陸民收容異議屬之、B受收容人所在地之地方行政法院管轄、C得以科技設備審理，皆對。"}, {"c": "徵收補償未給付→徵收失效 釋字110/516", "k": "應提起『確認徵收法律關係不存在訴訟』。", "law": "釋字110、516(補償未於期限給付徵收失效)。", "trap": "A撤銷訴訟、B確認處分違法、C確認處分無效，皆非。"}, {"c": "起訴不合法之命補正", "k": "訴訟代理人之代理權有欠缺者，應先定期命補正。", "law": "行政訴訟法(命補正)。", "trap": "A無審判權、B重複起訴、C無管轄不能移送，皆逕予駁回(不能補正)。"}, {"c": "怠於執行職務國賠 釋字469", "k": "機關對是否執行職務有裁量權時，原則上不因未執行成立國賠，除非裁量收縮至零。", "law": "國家賠償法§2Ⅱ、釋字469。", "trap": "A不以法律明文人民有請求權為必要(釋字469已放寬)、C委託管理仍可成立國賠、D公共設施國賠採無過失責任。"}, {"c": "國賠義務機關", "k": "稱公共設施瑕疵國賠『一律由管理機關承擔』→錯，係設置或管理機關。", "law": "國家賠償法§9。", "trap": "A委託事件由委託機關負責、C上級機關逾20日不確定得以其為義務機關、D裁撤後以原上級機關為義務機關，皆對。"}, {"c": "平等原則／不法平等", "k": "人民無權主張『不法之平等』。", "law": "平等原則、行政自我拘束。", "trap": "A不得主張不法平等、B裁量基準間接對外效力、C行政慣例之自我拘束，皆對。"}, {"c": "制度性保障", "k": "一般行動自由屬§22之基本權，非『制度性保障』。", "law": "制度性保障(學術自由、人身自由、地方自治等)。", "trap": "A學術自由、B人身自由、C地方自治，皆為制度性保障。"}, {"c": "裁判憲法審查 憲訴法", "k": "對適用大法庭裁定見解之不利確定終局裁判，『得』聲請裁判憲法審查。", "law": "憲法訴訟法。", "trap": "A聲請書應記載事項、C具憲法重要性或為貫徹基本權所必要得受理、D 6個月不變期間，皆對。"}, {"c": "地方自治制度性保障之界限", "k": "制度性保障係就『自治事項』，非轄內『所有事物』均享自行立法執行權。", "law": "地方制度、釋字498/550。", "trap": "A資格源自憲法、B不侵核心領域得限制、D自治權受侵害得救濟，皆對。"}, {"c": "行政法法源／自治條例", "k": "自治條例無須特定法律授權，於自治事項仍得就居民權利義務(限制權利)為規範。", "law": "地方制度法§28、§25。", "trap": "B緊急命令位階等同法律(非法規命令)、C大法庭後判例決議不再有拘束力但非不得參考(實際已停止適用)、D習慣法仍為法源。"}, {"c": "誠實信用原則", "k": "已通知限期改善卻於期限屆至前即裁罰→違反誠實信用(信賴保護)。", "law": "行政程序法§8(誠信原則)。", "trap": "A未必違反比例、B非當然無效、C仍屬違法，皆非最適。"}, {"c": "判斷餘地之界限", "k": "性平調查小組之『事實認定』，法院仍得審查，非判斷餘地當然拘束法院。", "law": "判斷餘地(行政法院得審查事項)。", "trap": "A簡答題客觀標準無判斷餘地、C出於不相關考量法院得介入、D涉基本權應提高審查密度，皆對。"}, {"c": "裁量基準之個案正義", "k": "裁量基準不得僵化；個案情形特殊者，得依個案特殊情形為不同裁量。", "law": "行政程序法§10、裁量基準。", "trap": "A仍須遵守、B僅事實拘束力、C僅供參考，皆未掌握個案正義。"}, {"c": "行政法律關係之發生", "k": "政府採購之『履約』階段(採購契約)係私法關係。", "law": "公法/私法之區別。", "trap": "A裁處罰鍰、B授予公權力之契約、D垃圾車執行職務撞傷人(國賠)，皆生行政法律關係。"}, {"c": "獨立機關", "k": "金管會非依法獨立行使職權之獨立機關。", "law": "中央行政機關組織基準法、獨立機關。", "trap": "A中選會、B保訓會、D運安會，均為依法獨立行使職權之(相當)獨立機關。"}, {"c": "管轄變更與案件移交 §18", "k": "管轄變更後，原機關縱存續但已無管轄權，已受理案件應移交新管轄機關。", "law": "行政程序法§11、§18。", "trap": "A、B變更管轄之公告方式、C公告第3日生效，皆對。"}, {"c": "委託辦理之訴願管轄 §16", "k": "受託行使公權力者所為處分，以『原委託機關』為訴願管轄機關。", "law": "行政程序法§16(委託)、訴願法。", "trap": "A行政院、B高教司、C考試中心，皆非。"}, {"c": "給付行政須有預算依據", "k": "給付行政涉金錢給予者，仍須有預算作為依據。", "law": "給付行政、法律保留/預算。", "trap": "A給付行政之定義、B得以公法或私法型態為之、D廢棄處分應考量信賴利益，皆對。"}, {"c": "統一解釋之性質＝行政規則", "k": "上級機關對法規之統一(解釋性)規定，性質為行政規則。", "law": "行政程序法§159(行政規則)。", "trap": "A行政處分、B行政計畫、C行政指導，皆非。"}, {"c": "附負擔＋溯及廢止 §123、§125", "k": "補助處分附加『負擔』(應將設備用於生產)，未履行時得溯及廢止授益處分。", "law": "行政程序法§93(附款)、§123、§125。", "trap": "A撤銷(係違法處分)、B單純廢止、D訴請返還，皆非最妥。"}, {"c": "行政處分之種類", "k": "撤銷建築執照＝消滅原許可之法律效果＝形成處分。", "law": "行政處分(下命/形成/確認)。", "trap": "A免役體位＝確認處分、B歸化核准＝形成處分、C任命公務員＝形成(設定身分)，敘述均錯。"}, {"c": "締約機關外之公權力行使之補償 §145", "k": "有補償適用者，須為『締約機關以外』之機關於契約關係外行使公權力致人民履約顯增負擔。", "law": "行政程序法§145(契約外公權力行使之補償)。", "trap": "A、C、D或屬締約機關體系，非§145所指。"}, {"c": "行政契約之效力 §140", "k": "締結侵害第三人權利之契約，未經第三人書面同意者『不生效力(效力未定)』，非當然無效。", "law": "行政程序法§135-§141。", "trap": "A約定國考錄取之契約無效、B欠缺事務管轄重大明顯瑕疵無效、C未以書面為之無效，皆對。"}, {"c": "行政罰之數行為分別處罰", "k": "違反建築法(變更使用)與商業登記法(未登記)係『兩個』違法行為，應分別裁處。", "law": "行政罰法§24、§25。", "trap": "B/C/D均誤認為單一行為。"}, {"c": "行政罰之過失原則處罰 §7", "k": "行政罰之過失行為『原則上即處罰』，不以有特別規定者為限(此為刑法之規定)。", "law": "行政罰法§7、§14、§8。", "trap": "A不區分正犯教唆幫助、C不知法規不免責但得減免、D以違反行政法上義務為限，皆對。"}, {"c": "公物不得為行政執行標的", "k": "公務所必需之公物不得作為行政執行(強制執行)之標的物。", "law": "公物、行政執行法。", "trap": "A所有權人得為私人、B得依事實行為提供公用、D得為自然山域水域，皆對。"}, {"c": "行政程序之代理 §24", "k": "代理人有二人以上者，『均得單獨代理』，非必須共同代理。", "law": "行政程序法§24。", "trap": "A代理權及於全部程序但撤回須特別授權、C複代理須本人同意、D代理權不因本人死亡而消滅，皆對。"}, {"c": "行政處分 vs 事實行為", "k": "在既成道路鋪柏油＝事實行為(非對外發生法律效果之單方行政行為)。", "law": "行政程序法§92(行政處分)。", "trap": "A手勢指揮交通、B開槍命退離、D通知噴藥(下命)，皆為行政處分。"}, {"c": "寄存送達之生效", "k": "行政程序之寄存送達『自寄存日即生效』；訴願及行政訴訟之寄存送達『自寄存日起經10日』生效。", "law": "行政程序法§74、訴願法、行政訴訟法§73。", "trap": "A/B/C對行政程序與訴願之生效時點敘述有誤。"}, {"c": "行政執行之管收要件", "k": "義務人『自行到場』接受調查者，仍得依法聲請管收(非以拘提為前提)。", "law": "行政執行法§17(管收)。", "trap": "A須先命提供擔保限期履行、B管收事由、D因病或難維持家計應停止管收，皆對。"}, {"c": "行為義務之代履行 §29", "k": "拆除違建(可由他人代為之行為義務)＝代履行，得委託第三人代為並命義務人預繳估計費用。", "law": "行政執行法§27、§29(代履行)。", "trap": "A非全額追償之單一方式、B拆除非須先科怠金、C非向法院聲請(行政機關自行執行)。"}, {"c": "確認訴訟之標的", "k": "確認訴訟之標的限『法律關係』成立與否、行政處分無效或已執行完畢之違法等；不及於『法規命令無效』之確認。", "law": "行政訴訟法§6(確認訴訟)。", "trap": "B會員資格、C公用地役關係、D國籍有無，皆為法律關係之確認。"}, {"c": "教師解聘與管制之救濟 釋字736", "k": "1年不得聘任為教師之管制，係另一不利處分，得以教育部為原處分機關提起訴願。", "law": "釋字736、訴願法。", "trap": "A/B/C對解聘及管制之救濟途徑敘述有誤。"}, {"c": "行政契約調整之訴訟類型", "k": "機關拒絕調整契約(非行政處分)，應提『一般給付訴訟』，請求判命機關為同意調整之意思表示。", "law": "行政程序法§147、行政訴訟法§8(一般給付訴訟)。", "trap": "A課予義務、B確認、D撤銷訴訟，皆非。"}, {"c": "律師強制代理事件 行訴法§49-1", "k": "⚠️高行第一審環境土地通常訴訟、都市計畫審查程序、向最高行政法院提起之事件，皆強制律師代理。", "law": "行政訴訟法§49-1(強制律師代理)。", "trap": "A、B、D皆屬行政訴訟之強制律師代理事件。(C於憲訴法亦原則強制代理，可對照詳解)"}, {"c": "審判權爭議之處理", "k": "受移送之法院亦認無審判權者，應裁定停止訴訟，向『最高法院』請求指定有審判權之管轄法院。", "law": "法院組織法§7-1以下、行政訴訟法§12-2。", "trap": "A不得逕予駁回、B非聲請統一解釋、C不得合意定審判權。"}, {"c": "公法上不當得利之返還方式", "k": "機關因撥款錯誤之事實行為取得不當得利返還請求權，但『不得逕以下命處分』命返還(須循一般給付訴訟，除法律另有明定)。", "law": "公法上不當得利、行政處分之要件。", "trap": "B作成書面處分命返還、C逕移送行政執行、D向普通法院起訴，皆錯。"}, {"c": "損失補償 vs 國家賠償", "k": "依法徵收前已埋設地下設施物妨礙土地所有權＝合法行為造成特別犧牲→損失補償。", "law": "損失補償(合法行為之特別犧牲)。", "trap": "A垃圾車撞傷、B坑洞受傷、C火車出軌受傷，皆為國家賠償(非補償)。"}, {"c": "處分理由之補正 §114", "k": "補正應於『訴願程序終結前』為之，非謂行政訴訟言詞辯論終結前均可。", "law": "行政程序法§114(程序瑕疵之補正)。", "trap": "A甲無請求補正權、B僅原處分機關得補正、D補正不足支持合法性不影響補正效力，皆對。"}, {"c": "聽證程序 §109", "k": "不服經聽證作成之處分，其救濟『免除訴願及其先行程序』(逕行起訴)。", "law": "行政程序法§107-§109。", "trap": "A非經法規明定亦得舉行聽證、B聽證終結後得再為聽證(必要時)、C主持人不以具法制專長為必要。"}, {"c": "徵收外國人財產／窮盡當地救濟", "k": "『窮盡當地救濟』係習慣國際法原則(行使外交保護之要件)。", "law": "國家責任、外交保護。", "trap": "A補償是否適當不得由徵收國片面裁量(此項本身亦為敘述)…B須適時合宜有效、C得明文排除窮盡當地救濟，為對。"}, {"c": "外國判決之承認與執行", "k": "外國確定判決須先經我國法院為『許可執行之判決』，始得為執行名義聲請強制執行，不得逕持外國判決執行。", "law": "民事訴訟法§402、強制執行法§4-1。", "trap": "A無外交承認不影響相互承認、B懲罰性賠償金判決具承認適格，皆對。"}], "刑法": [{"c": "刑法之效力／國民國外犯罪 §7", "k": "要記：竊盜最輕本刑未達3年，國民於國外犯之不適用我國刑法。", "law": "刑法§3-§8、§7(國民於國外犯罪以最輕本刑3年以上為限)。", "trap": "A在臺灣(屬地§3)、C偽造新臺幣(§5保護原則)適用；D國民國外詐欺較複雜，本題以B為答案，可對照詳解。⚠️"}, {"c": "違背義務遺棄罪 §294", "k": "要記：母對嬰兒有法定扶養義務；醫師護士無扶養義務，臨時照顧不解免母之義務。", "law": "刑法§294(對無自救力人違背扶養保護義務而遺棄)。", "trap": "A遺棄罪為危險犯不以實際危險為要件、B應論§294(非§293)、D乙有義務不解免甲之義務。"}, {"c": "明知違法之命令不阻卻 §21、§213", "k": "要記：明知長官命令違法仍照辦者，不得依命令阻卻違法，仍負正犯之責。", "law": "刑法§21Ⅱ但書(明知命令違法不阻卻)、§213、§216。", "trap": "A長官斥責非緊急避難之危難、B明知違法不阻卻、C斥責不足以致無期待可能。"}, {"c": "故意原因自由行為 §19Ⅲ", "k": "要記：『故意自陷』無責任能力後犯罪者，不適用§19減免，仍負故意責任。", "law": "刑法§19第3項(原因自由行為)、客體錯誤。", "trap": "A誤丙宅為乙宅＝等價客體錯誤不影響故意、C故意飲酒自陷＝故意原因自由行為、D客體不一致非因果歷程重大偏離，皆對。"}, {"c": "滿80歲得減輕其刑 §18Ⅲ", "k": "要記：滿80歲者不問身心狀態，一律『得』減輕其刑。", "law": "刑法§18第3項(滿80歲人之行為得減輕其刑)。", "trap": "A 20歲後喪失聽說能力未必為瘖啞人、C持槍繼續犯至成年、D飲酒自陷酩酊(原因自由行為)，均不當然減刑。"}, {"c": "不能未遂之危險判斷 §26", "k": "要記：偶然無子彈而扣板機，一般觀察仍有危險(非重大無知)→屬有處罰之『障礙未遂』，非§26不罰之不能未遂。", "law": "刑法§26(不能發生結果『又無危險』者不罰)。", "trap": "A我國採客觀危險說、B『不罰』指不處罰非減免、D捷運抽菸誤認違法係幻覺犯。"}, {"c": "累積因果關係 §271未遂", "k": "要記：甲、乙各自下不足致死之毒量、無犯意聯絡；死亡係二人劑量累積所致，甲之行為單獨不足致死→不可歸責於甲。", "law": "刑法§271、客觀歸責、累積因果關係。", "trap": "B既遂(不可歸責)、C傷害致死、D不能未遂(有危險係障礙未遂)，皆錯。"}, {"c": "間接正犯／過失致死 §271、§276", "k": "要記：利用不知情之人為工具者＝間接正犯；該被利用人若違反注意義務致死，自負過失致死。", "law": "刑法§271(間接正犯)、§276(過失致死)。", "trap": "A共同正犯、B乙為幫助犯、D乙無罪，皆錯。"}, {"c": "障礙未遂 vs 中止未遂 §27", "k": "要記：因『被害人外出當日無法犯行』而放棄＝障礙未遂(外部障礙)，非己意之中止未遂。", "law": "刑法§27(中止未遂須己意中止)、共同正犯脫離。", "trap": "B乙取回槍已脫離與丙後行為無關、C丙侵入住居與殺人想像競合、D丁負教唆殺人既遂之教唆犯，皆對。"}, {"c": "不罰後行為之要件", "k": "要記：須『未侵害新法益』、行為主體相同；竊盜後毀損贓物為適例。", "law": "不罰(與罰)後行為。", "trap": "A竊盜後毀損贓物為適例、C前罪已充分評價、D前後罪主體須相同，皆對。"}, {"c": "無故取得電磁紀錄無未遂 §359", "k": "要記：§359無故取得他人電磁紀錄罪『不罰未遂』；前後兩次查詢為接續犯一罪。", "law": "刑法§359(無未遂處罰)、§318-1、§132、接續犯。", "trap": "A第二次成立§318-1、B成立§132洩漏國防以外秘密、D接續犯一罪，皆對。"}, {"c": "緩刑限2年以下有期徒刑 §74", "k": "要記：受『2年6月』有期徒刑宣告者超過2年，不得宣告緩刑。", "law": "刑法§74(緩刑要件，受2年以下有期徒刑、拘役或罰金之宣告)。", "trap": "A得命接受精神治療、B緩刑期內犯強盜受5年確定應撤銷、C緩刑效力不及於保安處分，皆對。"}, {"c": "保護管束非拘束人身自由 §92", "k": "要記：保護管束係於社會中由觀護人監督，『非拘束人身自由』之保安處分。", "law": "刑法§92(保護管束)、§86、§90。", "trap": "A強制工作受罪刑法定拘束(釋字528)、B對未滿14歲不成立犯罪者得施感化教育、D保安處分以預防再犯為目的，皆對。"}, {"c": "行賄 vs 收賄 §122、§131", "k": "要記：提供折扣等利益予公務員者係『行賄』。", "law": "刑法§122(行賄／受賄)、§131(圖利)。", "trap": "A丙違法發照成立圖利罪、B乙收受折扣利益成立收賄罪、C甲打折售屋成立行賄罪，皆對。"}, {"c": "妨害公務之共同正犯 §135", "k": "要記：對依法執行職務(強制點交)之法官警察潑廚餘＝施強暴；示意並搬桶供眾人者係共同實行。", "law": "刑法§135、§136、§139。", "trap": "A甲為§136首謀、C丙為§136在場助勢者、D丁撕已執行完畢之封條成立§139，皆與實務認定不符。"}, {"c": "投票受賄於收受期約即既遂 §143", "k": "要記：收受賄賂並許以投票權之一定行使即既遂，不以真正投票為必要；行賄受賄係對向犯。", "law": "刑法§143(投票受賄)、§144(投票行賄)。", "trap": "B電風扇亦為賄賂(甲成立§144)、C對向犯非共同正犯、D事後退回不影響已既遂。"}, {"c": "教唆偽證／頂替與偽證之競合 §168、§164", "k": "要記：證人『具結後』為虛偽陳述＝偽證(吸收頂替)；教唆者成立教唆偽證罪。", "law": "刑法§168(偽證)、§164Ⅱ(頂替)、§29。", "trap": "A甲成立教唆偽證罪、C丙之頂替與偽證想像競合從偽證處斷、D未諭知拒絕證言致具結無效不成立偽證，皆對。"}, {"c": "湮滅自己(相關)證據不罰 §165、§164", "k": "要記：教唆他人湮滅『與自己犯罪有關』之證據者，依『湮滅自己證據不罰』之法理，不成立教唆湮滅證據罪。", "law": "刑法§164(隱避犯人)、§165(湮滅他人刑事證據，自己證據不罰)、§29。", "trap": "A丙以漁船載乙離臺成立隱避犯人罪、B乙湮滅自己證據不罰、C甲不成立隱避犯人之教唆犯，皆對。"}, {"c": "偽證罪以依法具結為要件 §168", "k": "要記：未踐行拒絕證言權告知之具結程序瑕疵→具結無效→不成立偽證；本罪為危險犯，不以判決受影響為必要。", "law": "刑法§168(偽證罪)。", "trap": "A被告無具結義務不成立偽證、C非結果犯、D未具結不成立偽證，皆錯。"}, {"c": "誣告罪（官方送分）", "k": "要記重點：誣告不以被誣告人有責任能力或確受處分為必要(危險犯)；一狀誣告數人為一個誣告行為論一罪。", "law": "刑法§169(誣告)、§171(未指定犯人誣告)。", "trap": ""}, {"c": "不能安全駕駛與過失致傷之競合 §185-3", "k": "要記：⚠️酒駕(§185-3)與其後過失致傷(§284)，實務認係『數罪併罰』，非想像競合。", "law": "刑法§185-3、§284。", "trap": "A濃度值之定性、B輕傷不構成§185-3Ⅱ結果加重犯、C自信酒退不阻卻故意，皆為正確敘述。(競合見解有變動，可對照詳解)"}, {"c": "變造有價證券 §201", "k": "要記：支票係有價證券；變造其發票日期等內容＝變造有價證券。", "law": "刑法§201(偽造變造有價證券)。", "trap": "B定存單非有價證券、C空白支票未具有價證券要件、D當票非§201之有價證券。"}, {"c": "盜刷信用卡成立詐欺 §339", "k": "要記：以他人真卡盜刷＝冒用持卡人對特約商店施詐使交付商品＝詐欺取財。", "law": "刑法§339(詐欺)、§201-1、§210。", "trap": "B§201-1係偽造『卡片』(本案用真卡)、C偽簽係偽造私文書之部分、D簽帳單非有價證券。"}, {"c": "以告發脅迫性交＝強制性交 §221", "k": "要記：以『告發非法居留』之惡害脅迫使人就範＝違反意願之方法。", "law": "刑法§221(強制性交，以脅迫等違反意願方法)。", "trap": "B非乘機(A非不能抗拒狀態)、C無權勢監督關係、D非無罪。"}, {"c": "略誘罪之對象限未成年 §240、§241", "k": "要記：和誘略誘罪保護家庭監督權，對象限『未成年人』；對未成年人以詐術/甜言蜜語誘出脫離家庭者論略誘。", "law": "刑法§240(和誘)、§241(略誘)。", "trap": "A、C、D之被誘人均已成年(不成立和誘略誘)。"}, {"c": "強制猥褻／性交定義 §224、§221、§10Ⅴ", "k": "要記：『假裝不小心』觸碰非以強暴脅迫為之，不該當§224強制猥褻；摩擦生殖器係猥褻非『性交(性器進入)』。", "law": "刑法§224(強制猥褻)、§225、§221、§228、§10第5項。", "trap": "B不成立乘機猥褻、C摩擦生殖器不成立§221強制性交、D不成立§228權勢性交，皆對。"}, {"c": "賭博罪 §266", "k": "要記：與電玩機台對賭(機台後有業者操控)仍屬賭博；賭博財物不以與人面對面為限。", "law": "刑法§266(賭博)、§28。", "trap": "B騎樓(公眾得出入)賭博成立、C對向犯非共同正犯、D同時同地數次賭博為接續犯一罪，皆對。"}, {"c": "放火致他人死亡之歸責", "k": "要記：⚠️消防員依職務進入火場係放火所製造之風險實現(不排除歸責)；自陷風險之救助者(丁僅戴棉口罩)涉被害人自我危害。", "law": "打擊錯誤、客觀歸責、被害人自我危害、§173、§271。", "trap": "B非等價客體錯誤、C/D不能據此排除客觀歸責。(本題歸責論述較細，可對照詳解)"}, {"c": "移至安全處所非遺棄 §293、§294", "k": "要記：對陌生流浪漢無保護義務(非§294)；將其移至『派出所門口(可獲救助之處)』未使其陷於更危險→非遺棄。", "law": "刑法§293、§294(遺棄罪)。", "trap": "A無義務遺棄、B有義務遺棄、D殺人未遂，皆不成立。"}, {"c": "GPS＝無故竊錄 §315-1", "k": "要記：GPS記錄行蹤＝竊『錄』(非竊聽)；無散布意圖者非加重之§315-2。", "law": "刑法§315-1第2款(無故竊錄非公開活動)。", "trap": "A非竊聽(無聲音)、C無散布意圖、D非無罪(配偶亦成立)。"}, {"c": "準強盜須達不能抗拒 §329、§315-1", "k": "要記：準強盜之強暴脅迫須『至使不能抗拒』；握拳言詞威脅而被害人不怕者，未達不能抗拒。", "law": "刑法§321、§329(準強盜，釋字630須達不能抗拒)、§315-1。", "trap": "A侵入住宅竊盜為加重竊盜、B丟棄財物仍屬竊盜既遂、D肉眼偷窺(無工具)不成立§315-1，皆對。"}, {"c": "不法所有意圖之判斷時點 §320", "k": "要記：不法所有意圖之判斷時點為『竊取(取得)行為時』；贈與之動機不影響。", "law": "刑法§320(竊盜，不法所有意圖)。", "trap": "A欲贈送時、C贈送時、D計畫時，均非判斷時點。"}, {"c": "強盜須行為人自施強暴 §328", "k": "要記：利用『他人』所造成之不能抗拒狀態取財者，非強盜(係竊盜/乘機)。", "law": "刑法§328(強盜，須行為人施強暴脅迫至使不能抗拒)。", "trap": "A假槍脅迫、B持刀命交現金、D毆打其子迫A交財(對第三人施強暴亦可)，皆符合強盜構成要件。"}, {"c": "侵占須易持有為所有 §335", "k": "要記：擅自使用所保管之物(開公務車去旅遊)係『使用』，非易持有為所有之侵占。", "law": "刑法§335(侵占，易『持有』為『所有』)。", "trap": "A出售寄展之古董、B花用公司現金、D侵吞代轉賄款，皆為易持有為所有之侵占。"}, {"c": "重利須乘他人急迫 §344", "k": "要記：出借人乙係被甲詐騙(誤以為投資)而貸款，並未『乘甲之急迫』收取重利→欠缺重利罪之主觀要件。", "law": "刑法§344(重利罪，須乘他人急迫輕率無經驗)、§339。", "trap": "A乙係被害人非詐欺行為人、B非為他人處理事務、C未乘他人急迫不成立重利罪。"}, {"c": "罪刑相當原則／大法官解釋", "k": "要記：釋字630將準強盜之強暴脅迫限縮須達『使人難以抗拒』之程度＝合憲(未違罪刑相當)。", "law": "釋字630、551、775、777。", "trap": "A釋字551誣告反坐、B釋字775累犯一律加重、C釋字777肇逃一律1-7年，均經宣告違憲。"}, {"c": "刑後強制治療 釋字799", "k": "要記：強制治療屬保安處分，對修法前曾犯性侵者溯及施以強制治療『尚不違反不溯及既往原則』。", "law": "釋字799、性侵害犯罪防治法§22-1、刑法§91-1。", "trap": "A明確性合格、B比例原則尚未失衡(惟長期治療有違憲疑慮)、C執行趨近刑罰悖離區隔要求，皆對。"}, {"c": "國民國外犯罪限最輕本刑3年以上 §7", "k": "要記：施用毒品罪最輕本刑未達3年，且非§5列舉之國外犯罪→國民於國外施用毒品無我國刑法適用。", "law": "刑法§3-§8、§7(國民於國外犯罪以最輕本刑3年以上者為限)。", "trap": "A我國籍郵輪(領域延伸)、B外國人國外殺我國民(§8/§7殺人達3年)、D海盜罪(§5世界法)，皆適用。"}, {"c": "新舊法比較 §2Ⅰ", "k": "要記：新增§185-3Ⅱ(不能安全駕駛致死)係『§185-3＋§276過失致死』之法律變更，應依§2Ⅰ比較新舊法。", "law": "刑法§2第1項(從舊從輕)、§185-3Ⅱ、§276。", "trap": "A認不能溯及無比較、C認僅§185-3變更、D認非法律變更，皆錯。"}, {"c": "信賴原則之適用 §14", "k": "要記：信賴原則須『自己遵守規則』且『對方違規非可預見/可避免』。", "law": "過失、信賴原則。", "trap": "A早見違規少年有時間閃避卻不閃、B自己超速、C自己跨越雙黃線，皆不得主張。"}, {"c": "不純正不作為犯／保證人地位 §15", "k": "要記：對自己飼養之危險動物有監督義務(保證人地位)，不召回致咬傷他人＝以不作為實現傷害。", "law": "刑法§15(不作為犯)、保證人地位(危險源監督)。", "trap": "A純正不作為犯不以保證人地位為必要、B§15防止義務包含契約、D不純正不作為犯不限既遂。"}, {"c": "誤想防衛(容許構成要件錯誤)", "k": "要記：誤認存在防衛情狀(誤以為乙在傷害丙，實為急救)＝誤想防衛，依實務/通說阻卻故意(或故意罪責)，不成立故意傷害，得論過失傷害。", "law": "誤想防衛(容許構成要件錯誤)、§23。", "trap": "A非包攝錯誤、C/D係『誤想防衛』非誤想避難。"}, {"c": "依有效令狀執行阻卻違法 §21", "k": "要記：司法警察依檢察官開具之『拘票』執行拘提，縱事後發現拘票不符法定事由，執行之警察仍得阻卻違法。", "law": "刑法§21(依法令之行為)。", "trap": "A體罰致橫紋肌溶解逾越懲戒、B執行明顯違法之竊聽命令、D父持籐條打成重傷逾越懲戒，皆不阻卻違法。"}, {"c": "犯罪所得及孳息之沒收 §38-1", "k": "要記：賄款存定存所生之利息屬『犯罪所得之孳息』(§38-1)，非『犯罪所生之物』(§38)。", "law": "刑法§38-1(犯罪所得含其變得之物、財產上利益及孳息)、§38、追徵。", "trap": "A收賄利得沒收、B花酒價額追徵、C賄款變得之鑽戒沒收，皆對。"}, {"c": "客體錯誤 vs 打擊錯誤 §271", "k": "要記：甲本欲殺乙，雖誤認地址(客體錯誤)，但子彈實際擊中『目標乙本人』致死＝對乙殺人既遂(非打擊錯誤之過失致死)。", "law": "刑法§271、客體錯誤、打擊錯誤。", "trap": "B對丙殺人未遂、C對丁殺人未遂、D對犬故意毀損，皆對。"}, {"c": "殺人與損壞屍體數罪併罰 §50", "k": "要記：殺人後『另行起意』焚屍＝兩個行為，侵害法益(生命 vs 對死者敬虔)及構成要件均不同→數罪併罰。", "law": "刑法§50、§271、§247。", "trap": "A一行為想像競合、B不罰後行為、D法條競合，皆錯(係兩個獨立行為與法益)。"}, {"c": "假借職務詐取財物 §339、§134", "k": "要記：警員表明身分要求減價、付部分價金後耍賴拒付＝假借職務之方法詐取財物。", "law": "刑法§339(詐欺)、§134(公務員假借職務加重)、貪污治罪條例。", "trap": "A剋扣罪(係扣留應發給之款)、B圖利罪、C認屬純民事，皆不該當。"}, {"c": "妨害公務須對執行職務者且有認識 §135", "k": "要記：須對『正依法執行職務』之公務員施強暴，且行為人須認識其為執行職務之公務員。", "law": "刑法§135(妨害公務)。", "trap": "A採買文具非執行職務、B送公文途中擦撞糾紛、D便衣未表明致A欠缺認識，皆不成立。"}, {"c": "妨害職務上掌管文書物品 §138", "k": "要記：客體須為公務員『職務上掌管』之文書物品；個人配發之警察制服非職務上掌管之物。", "law": "刑法§138(毀損公務員職務上掌管之文書物品)。", "trap": "A撕警詢筆錄、B撕被扣押之帳簿、C搶撕送達中之傳票，皆為職務上掌管之物，成立本罪。"}, {"c": "虛偽遷徙投票罪 §146Ⅱ", "k": "要記：為使『直系血親(父)』當選而虛遷戶籍投票，基於人倫親情，實務認欠缺可罰違法性而不罰；且本罪於『虛遷並投票』即既遂，不以當選為要件。", "law": "刑法§146第2項(虛偽遷徙投票罪)。", "trap": "A遷籍目的為就學非為投票、C妹婿不類推§167、D不以當選為既遂要件。"}, {"c": "強制／妨害秘密之主體與行為 §304、§315-1", "k": "要記：妨害秘密罪之行為是『竊錄』他人非公開活動；乙係刪除檔案，行為不該當妨害秘密罪。", "law": "刑法§304(強制)、§315-1(妨害秘密／竊錄)。", "trap": "A甲以脅迫強迫乙刪除＝§304強制罪成立(故A錯)；C/D涉乙被脅迫之罪責問題，較不明確，B最正確。"}, {"c": "偽證罪之審判含民刑行政 §168", "k": "要記：本罪之『審判或偵查』不限刑事，含民事、行政訴訟等於執行審判職務之公署作證之情形。", "law": "刑法§168(偽證罪)。", "trap": "A己手犯、B須依法具結(不得具結者具結無效不成立)、D虛偽陳述指與真實相悖足陷偵審錯誤，皆對。"}, {"c": "放火罪之客體 §173、§174、§175", "k": "要記：簡易搭設、可移置之檳榔攤非『住宅或建築物』→放火燒燬之應論§175(放火燒燬住宅等以外之物)。", "law": "刑法§173、§174、§175(放火罪客體)。", "trap": "A現供人使用住宅縱無人在宅仍為§173客體、B『人』指行為人以外之人、C燒燬停駛公車成立§174，皆對。"}, {"c": "過失傾覆火車罪 §183Ⅱ", "k": "要記：過失致載客火車翻覆＝§183Ⅱ過失傾覆現有人所在火車罪(已涵蓋傾覆致生之傷亡)，不另論各個過失致死傷。", "law": "刑法§183(傾覆破壞現有人所在交通工具，Ⅱ過失犯)。", "trap": "A分論數個過失致死傷、B『致死致重傷』係故意傾覆、D論跳機之不作為過失，皆錯。"}, {"c": "不能安全駕駛罪 §185-3", "k": "要記：⚠️酒駕(§185-3)與其後過失致傷(§284)，實務認係『數罪併罰』(公共危險與個人法益不同)，非想像競合。", "law": "刑法§185-3、§284。", "trap": "A酒測未達0.25但有具體事證不能安全駕駛仍成立、C 0.27達標準成立、D 0.4擬制不能安全駕駛縱無異狀仍成立，皆對。(競合見解有變動，可對照詳解)"}, {"c": "偽造契約實價登錄之共犯 §210、§214", "k": "要記：買家若『知情配合』墊高價金供實價登錄，成立(行使)偽造私文書、使公務員登載不實罪之共同正犯。", "law": "刑法§210、§216、§214、§339。", "trap": "A偽造及行使私文書共同正犯、B使公務員登載不實共同正犯、D持偽造契約貸款另成立詐欺，皆對。"}, {"c": "加重強制性交共同正犯 §222Ⅰ④、§28", "k": "要記：參與下藥、抬入房之分擔者，縱性侵前離去，其犯罪貢獻已實現→共同正犯；以FM2藥劑犯之＝加重強制性交。", "law": "刑法§222第1項第4款(以藥劑犯之)、§28、§25。", "trap": "A乙未有效脫離、B共同正犯責任及於全部、C甲對丁係障礙未遂(已著手非不能未遂)。"}, {"c": "強制性交之著手 §221、§302", "k": "要記：強拉上車＝妨害自由(§302)，尚非強制性交之著手；其後『強灌烈酒』(自己製造不能抗拒之違反意願方法)才是強制性交之著手。", "law": "刑法§221、§302。", "trap": "A強拉上車非著手、C自己灌酒係§221非§225乘機、D灌酒係違反意願方法之§221(非§222Ⅰ④藥劑)。"}, {"c": "散布猥褻物品罪 §235／釋字617", "k": "要記：猥褻含『暴力、性虐待』等無藝術價值且令人羞恥厭惡者；於個人網站展示＝散布/公然陳列。", "law": "刑法§235、釋字407、617。", "trap": "B公園露生殖器＝公然猥褻(§234非散布物品)、C寫真集以不透明封套隔絕措施不罰、D教學展示無散布意圖。"}, {"c": "和誘略誘／幼童無同意能力 §240、§241", "k": "要記：5歲幼童『無同意能力』，縱表面同意亦無效，應論略誘(置於實力支配)。", "law": "刑法§240(和誘)、§241(略誘)。", "trap": "A爭撫養權中仍為有監督權之人、B區別須考慮被誘人意思、D以脫離監督權人置於實力支配為要件，皆對。"}, {"c": "對直系尊親屬施強暴 §281、§31", "k": "要記：對直系尊親屬施強暴『未成傷』＝§281；無身分之共犯依§31Ⅰ亦成立§281共同正犯。", "law": "刑法§281(對直系血親尊親屬施強暴未成傷)、§31(身分犯之共犯)。", "trap": "A丙無身分不成立§272(科普通殺人之刑)、B/C對未成傷之罪名定性錯誤。"}, {"c": "遺棄罪均以無自救力人為客體 §293、§294", "k": "要記：§293與§294『均』以『無自救力之人』為行為客體。", "law": "刑法§293、§294。", "trap": "A前者一般犯後者身分犯、B前者限積極作為後者含不作為、D前者不要求保護義務來源後者限法令或契約，皆對。"}, {"c": "強制罪未遂／恐嚇危安 §304、§305", "k": "要記：恐嚇危安須將惡害『通知被害人』；向友人提起附條件之未來惡害(乙再撞我就打死他)，未對乙通知→不成立§305。", "law": "刑法§304(強制)、§305(恐嚇危安)。", "trap": "A認揚言成立§305、C認下跪不成立強制未遂、D認均不成立，皆錯。"}, {"c": "妨害名譽及信用 §309、§310、§312、§313", "k": "要記：抽象謾罵＋公然＝公然侮辱罪。", "law": "刑法§309公然侮辱、§310誹謗、§312侮辱死者、§313妨害信用。", "trap": "B無王姓校長(欠特定被害人)不成立誹謗、C罵死者抽象謾罵成立§312、D公司之信用受妨害仍成立§313。"}, {"c": "業務洩密罪須因業務知悉 §316", "k": "要記：須具列舉身分且『因業務』知悉之秘密；兼課教師閒聊得知學生私事非因醫療業務知悉。", "law": "刑法§316(洩漏業務上知悉之他人秘密)。", "trap": "A護理師、B宗教師、C律師業務佐理人因業務知悉而洩漏，皆成立。"}, {"c": "竊盜之不法所有意圖／使用竊盜 §320", "k": "要記：短暫使用後即還(使用竊盜)欠缺不法所有意圖不成立；取走供另犯罪使用、移置他處者則有不法所有意圖。", "law": "刑法§320(竊盜，須不法所有意圖)。", "trap": "A橡皮擦用5秒、B拖板車用10分還、D雨傘用10分還，皆為不罰之使用竊盜。"}, {"c": "結夥三人須在場實行 §321", "k": "要記：約定行竊而僅二人到場實行者，未達結夥三人。", "law": "刑法§321(結夥三人以上須在場共同實行)。", "trap": "A持螺絲起子卸車牌(攜帶兇器)、C白天侵入住宅(不限夜間)、D於航空器內竊盜，皆構成加重竊盜。"}, {"c": "強盜得利罪 §328Ⅱ、§329", "k": "要記：以強暴脅迫取得『不法利益(免費搭載)』＝強盜得利罪。", "law": "刑法§328第2項(強盜得利)、§329(準強盜須當場)。", "trap": "A『天打雷劈』非人力可支配之惡害、B隔日奪錶非當場(不構成準強盜)、C被害人不害怕基於同情交付(欠因果)。"}, {"c": "強盜與擄人勒贖之區別（官方送分）", "k": "要記重點：擄人勒贖須『以擄人為手段、向第三人(家屬)勒贖』；當場向被害人本人強取財物則為強盜；先強盜後另起意勒贖之競合及§347Ⅴ取贖前釋放減刑等，係本題各選項爭點。", "law": "刑法§328強盜、§347擄人勒贖、§332結合犯。", "trap": ""}, {"c": "妨害電腦使用罪 §358、§359、§360", "k": "要記：§358入侵須『輸入他人帳密、破解保護措施或利用漏洞』。", "law": "刑法§358(入侵電腦)、§359、§360、§354。", "trap": "B未設密碼之電腦直接使用無保護措施可破不成立§358、C砸壞硬體係§354毀損(非§359)、D臉書留言非§360技術性干擾。"}, {"c": "恐嚇公眾安全罪之恐嚇內容 §151", "k": "要記：恐嚇內容限『以加害生命、身體、財產』之事(不含自由、名譽)。", "law": "刑法§151(恐嚇公眾安全)。", "trap": "A對不特定或多數人、B對內容有支配可能而是否實現非所問、C使公眾心生畏懼即足，皆對。"}, {"c": "汽油彈放火罪 §173", "k": "要記：以汽油彈丟入住宅致燃燒燒燬＝放火(汽油彈是放火工具，非§176爆裂物)。", "law": "刑法§173(放火)、§176(準放火限爆裂物)。", "trap": "A非準放火、B丟汽油彈致燃燒即放火、C放火住宅本即公共危險。"}, {"c": "客體錯誤／因果歷程錯誤 §13", "k": "要記：基於殺人計畫『尚未著手』前因駕車過失撞死目標＝過失致死(非殺人既遂)。", "law": "刑法§13、客體錯誤、打擊錯誤、因果歷程錯誤。", "trap": "A係客體錯誤(對丙仍故意既遂)、C打擊錯誤非阻卻罪責、D因果偏離不重要仍殺人既遂。"}, {"c": "容許構成要件錯誤之各說 §16", "k": "要記：『嚴格罪責理論』將其與禁止錯誤同處理→『仍具故意』，於罪責層次(違法性認識)處理，可避免則減輕、不可避免則免責。", "law": "容許構成要件錯誤(誤想防衛)之學說。", "trap": "B負面構成要件要素說、C限制罪責理論、D限制法律效果罪責理論之描述，皆對。"}, {"c": "約定互毆／私行拘禁 §283、§302", "k": "要記：約定互毆雙方各有傷害故意，各論傷害罪，不成立§283聚眾鬥毆罪。", "law": "刑法§283(聚眾鬥毆)、§302、§23、§282。", "trap": "B關鐵門使乙無法離開＝§302私拘、C乙對攻擊者為正當防衛(非緊急避難)、D互毆且重傷承諾無效不得阻卻違法。"}, {"c": "違法性錯誤之可避免性 §16", "k": "要記：不知法律不免責，除非欠缺違法性認識且『無法避免』；經營數十年者難謂其不知須許可係無法避免。", "law": "刑法§16(違法性錯誤)。", "trap": "A保證人地位、C信賴原則、D以中學畢業免責，皆與本爭點無關或錯誤。"}, {"c": "遵守規則不成立過失致傷 §184-4", "k": "要記：甲綠燈合法行駛、乙闖紅燈撞甲→甲對乙之傷無過失，不成立過失致傷罪。", "law": "刑法過失、§185-4。", "trap": "B、C、D稱不成立肇逃之理由(已確認沒事/無過失/未重傷)均錯——§185-4不以駕駛人有過失為限。"}, {"c": "不成立犯罪之判斷／毀損無未遂", "k": "要記：小石頭丟火車車窗未生損害、無傾覆危險→不該當且毀損無未遂處罰。", "law": "刑法§184/§183、毀損無未遂處罰、§25。", "trap": "A伸手竊得玩具鈔(竊盜未遂)、B鋸檜木一半(竊盜未遂)、D未勃起撞擊欲插入(強制性交未遂)，皆成立未遂犯。"}, {"c": "重傷罪不罰預備／教唆從屬性 §278、§29", "k": "要記：重傷罪不罰預備；持刀埋伏尚未著手＝預備重傷不罰；教唆者於正犯未著手前不成立。", "law": "刑法§278(重傷罪，不罰預備)、§29(教唆從屬性)。", "trap": "B、C認成立重傷未遂(尚未著手)、D預備重傷不罰，皆錯。"}, {"c": "共同正犯之脫離 §28", "k": "要記：已提供犯罪貢獻(交付鑰匙、共謀)者，須『消除其貢獻之影響』才有效脫離；單純未到場不生脫離效果。", "law": "刑法§28(共同正犯)、§27Ⅱ。", "trap": "B乙丙侵入住居共同正犯、C乙另構成取財(殺後另起意)、D甲不適用§27Ⅱ共同正犯中止，皆對。"}, {"c": "精神(心理)幫助亦成立幫助犯 §30", "k": "要記：借槍『提振殺人勇氣』＝精神(心理)幫助，縱未實際使用該槍，仍成立幫助犯。", "law": "刑法§30(幫助犯)。", "trap": "B教唆(未引發犯意)、C/D認精神幫助不成立或欠物理關聯，皆錯。"}, {"c": "罰金之量刑 §57、§58", "k": "要記：罰金應先依§57量刑，再依§58審酌資力及犯罪所得；所得超過罰金最多額時，得於所得範圍內酌量加重。", "law": "刑法§57、§58、§41。", "trap": "A數罪均得易科者定執行刑逾6月仍得易科(釋字662)、B易服社會勞動執行後視為執行完畢、C死刑應審酌兩公約。"}, {"c": "義務沒收 vs 任意沒收 §38、§38-1", "k": "要記：違禁物、犯罪所得＝『義務(應)沒收』；供犯罪所用之物(屬犯人者)＝『任意(得)沒收』。", "law": "刑法§38(違禁物應沒收／供犯罪所用之物得沒收)、§38-1(犯罪所得應沒收)。", "trap": "A土製炸藥(違禁物)、C酬金、D賄款(犯罪所得)，皆義務沒收。"}, {"c": "褫奪公權 §37、§74Ⅴ", "k": "要記：緩刑效力不及於從刑、保安處分及沒收；褫奪公權為從刑，故不及於褫奪公權。", "law": "刑法§37(褫奪公權)、§74第5項。", "trap": "A不得單獨宣告(從刑)、C有期褫奪公權最長10年、D宣告死刑應併宣告褫奪公權終身。"}, {"c": "繼續犯與他罪之競合 §55", "k": "要記：持有槍枝(繼續犯)與『另行起意』之傷害係不同行為→數罪併罰，非想像競合。", "law": "刑法§55(想像競合)、繼續犯。", "trap": "A殺乙未遂＋過失傷丙(一行為)、B侵入住宅＋殺人、C同時偽造二支票，皆為一行為之想像競合。"}, {"c": "緩刑之負擔款項向公庫 §74Ⅱ", "k": "要記：緩刑命支付金錢者係『向公庫』(§74Ⅱ④)或向被害人賠償(第3款)；無『向公益基金會支付金額』之款。", "law": "刑法§74第2項、§93。", "trap": "A過失傷害前科不影響緩刑、C執行完畢逾5年仍得緩刑、D支付公庫之附條件緩刑得不付保護管束，皆對。"}, {"c": "洩漏國防以外秘密罪 §132", "k": "要記：本罪相對人(獲秘密之人)若非因職務業務知悉，不成立本罪，亦『不當然』與洩密者成立共同正犯(對向犯之一方未必處罰)。", "law": "刑法§132。", "trap": "A一有洩漏交付即成立、B過失洩漏亦成立(§132Ⅱ)、D非公務員非因職務業務知悉者洩漏不成立，皆對。"}, {"c": "準受賄罪 §123", "k": "要記：本罪僅處罰『受賄方』(於未為公務員時預以職務上行為期約收賄，嗣為公務員後履行者)；行賄之人不在本條處罰之列。", "law": "刑法§123(準受賄罪)。", "trap": "A準用含違背職務、C成為公務員後拒履行仍成立(非僅未遂)，皆錯。"}, {"c": "行賄罪／不正利益 §122Ⅲ", "k": "要記：賄賂含一切不正利益(性招待亦屬之)；行賄於行求/期約時即成立，不待對方收受。", "law": "刑法§122第3項(對違背職務行為行賄)、賄賂與不正利益。", "trap": "B乙拒絕仍成立行賄、C洩漏臨檢係違背職務、D甲為行賄非教唆受賄。"}, {"c": "侮辱公務員罪 §140", "k": "要記：保護國家公務尊嚴(國家法益)，同時辱罵數執勤員警＝單純一罪；不以『公然』為要件；對象須『正執行職務』之公務員。", "law": "刑法§140(侮辱依法執行職務之公務員)。", "trap": "B不以公然為要件、C只要公務員正執行職務即可、D辱罵已下班之員警不成立本罪。"}, {"c": "隱避犯人罪／湮滅證據 §164、§165", "k": "要記：安排犯人偷渡出境＝使犯人隱避(§164)。", "law": "刑法§164(藏匿/使犯人隱避)、§165(湮滅他人刑事證據)。", "trap": "A乙湮滅自己證據不罰、B丁親自掩埋屍體為正犯(非幫助犯)、C甲教唆湮滅與自己有關之證據不成立。"}, {"c": "誣告罪之故意與意圖 §169", "k": "要記：須『虛構事實』並有使他人受刑事或懲戒處分之意圖。", "law": "刑法§169(誣告罪)。", "trap": "A行政申訴非刑事/懲戒誣告、B未指具體事實不成立、D出於誤會無虛構故意不成立，皆對。"}, {"c": "竊取支票自己背書兌現 §201、§217", "k": "要記：在背書欄填『自己真名』背書＝真正背書(無權處分)，非偽造他人名義→不成立偽造有價證券、偽造署押。", "law": "刑法§201(偽造有價證券)、§210、§217、§339。", "trap": "A持票兌現＝詐欺取財、C不構成偽造署押、D不構成業務登載不實，皆對。"}, {"c": "使公務員登載不實罪 §214", "k": "要記：公務員以『私經濟地位』所簽契約＝私文書(非公文書)。", "law": "刑法§214、§10(公文書)。", "trap": "B公務員須對不實事項不知情(無實質審查)、C有實質審查權者不成立、D足生損害以有損害之虞為已足，皆對。"}, {"c": "偽造文書之名義人 §210、§220", "k": "要記：冒用『已死亡之人』名義製作文書，若足生損害於公眾或他人，仍成立偽造文書罪。", "law": "刑法§210、§220(準文書)。", "trap": "A文書影本得為客體、B虛擬人物名義不妨礙成立、D稅戳以文書論，皆對。"}, {"c": "強制性交之違反意願方法 §221、§222", "k": "要記：§221『違反意願之方法』採最廣義，指一切違反被害人意願之方法，不以類似強暴脅迫恐嚇催眠術之強制方法為限。", "law": "刑法§221、§222、最高法院99年第7次決議。", "trap": "B無責任能力人不計入二人以上、C兇器不以攜帶之初有行兇意圖為必要、D對5歲幼童仍依加重強制性交處斷。"}, {"c": "散布性影像／非竊錄 §315-2、§319-2", "k": "要記：經同意拍攝之影片『非竊錄』，散布之不該當§315-2(竊錄內容物)。", "law": "刑法§315-2(散布竊錄內容)、§319-2散布性影像、§235、§221、§310。", "trap": "A加重誹謗、C散布猥褻物品、D以散布威脅再性交(強制性交)，皆構成。"}, {"c": "公然之定義 §234", "k": "要記：『公然』＝不特定『或』多數人得共見共聞(不須同時具備不特定且多數)。", "law": "刑法§234(公然猥褻)、釋字145。", "trap": "B猥褻行為定義、C引誘行為定義、D詐術結婚之客觀處罰條件，皆對。"}, {"c": "違背義務遺棄罪之保證人 §294", "k": "要記：保護義務不以契約『有效』為必要，事實上承擔救護職務(救生員)即有義務；本罪為抽象危險犯，遺棄即既遂。", "law": "刑法§294(違背義務遺棄罪)。", "trap": "A係不作為(非積極遺棄)、C抽筋溺水者為無自救力人、D不以死亡為既遂要件。"}, {"c": "加重竊盜數加重事由論一罪 §321", "k": "要記：同一竊盜行為兼具數加重事由(攜帶兇器、侵入住宅)者，只論『一個』加重竊盜罪(加重事由是情狀，非數罪)。", "law": "刑法§321(加重竊盜)、§320。", "trap": "A移入實力支配為既遂、B現行犯逮捕阻卻違法、C攜帶兇器只須客觀有危險之兇器，皆對。"}, {"c": "加重強盜＋另起意傷害 §330、§277", "k": "要記：持槍(攜帶兇器)闖宅(侵入住宅)強盜＝§330加重強盜；取財後『另起意』打昏＝另一傷害故意，數罪併罰。", "law": "刑法§330(加重強盜)、§328、§277。", "trap": "A普通強盜(漏加重)、B準強盜(本案係直接強盜)、D恐嚇取財(當場強暴係強盜)。"}, {"c": "加重詐欺須三人以上共同 §339-4", "k": "要記：單純出賣帳戶者，與詐欺集團無『三人以上共同』之犯意聯絡，不構成加重詐欺(至多幫助詐欺/洗錢)。", "law": "刑法§339-4(加重詐欺：三人以上共同、冒用公務員、廣播電視網路等)。", "trap": "A三人共謀電話詐欺、C四人共同竄改效期販售、D冒用法院人員，皆構成加重詐欺。"}, {"c": "恐嚇取財無加重類型 §346、§328", "k": "要記：攜帶兇器之加重只在竊盜(§321)、搶奪(§326)、強盜(§330)；恐嚇取財『無』攜帶兇器加重之規定。", "law": "刑法§346(恐嚇取財)、§328(強盜)。", "trap": "A強盜須壓抑抗拒至不能抗拒、B恐嚇取財含現時惡害但未達不能抗拒、D恐嚇須人力可支配之惡害，皆對。"}, {"c": "毀損須減損物之效用 §354", "k": "要記：⚠️須減損物之『效用』；單純對圍牆噴漆未影響其效用者，實務認不該當毀損。", "law": "刑法§354(毀損，須毀棄、損壞或致令不堪用)。", "trap": "B狗糞污染豬肉(不堪食用)、C鬧鐘浸水不作響、D放鳥使飛走(喪失持有效用)，皆該當。(噴漆是否毀損有爭議，可對照詳解)"}, {"c": "GPS偵查／妨害書信秘密 §315-1、§315", "k": "要記：警察GPS偵查無法律授權→不得主張依法令行為阻卻違法，成立§315-1；開拆信件於『開拆時』即既遂，不以理解內容為必要。", "law": "刑法§315-1、§315、§133、最高法院106台上3788。", "trap": "B開拆即既遂(非未遂)、C丙非郵電人員不成立§133、D配偶竊錄仍成立§315-1。"}, {"c": "主刑加減之限制 §67、§68", "k": "要記：『拘役』加減時『僅加減最高度』，不加減最低度。", "law": "刑法§67(有期徒刑、罰金加減最高度及最低度同加減)、§68(拘役、罰金加減僅加減最高度)、§63、§65。", "trap": "A減輕標準、B無期減為20年以下15年以上、C滿80歲不得處無期，皆對。"}, {"c": "肇事逃逸不以有過失為限 §185-4", "k": "要記：駕駛人對事故縱『無過失』，離開現場仍構成本罪(僅依§185-4Ⅱ減輕或免除其刑)。", "law": "刑法§185-4(112修正)、釋字777。", "trap": "A不僅保護生命(兼及救護/釐清責任)、C非具體危險犯、D被害人當場死亡不影響本罪成立。"}, {"c": "偽造／行使之吸收方向", "k": "要記：『貨幣、有價證券』→偽造吸收行使(論偽造)；『文書(公/私)』→行使吸收偽造(論行使偽造)。", "law": "吸收關係。", "trap": "A偽造貨幣吸收行使、B偽造有價證券吸收行使、D行使私文書吸收偽造，皆對。"}, {"c": "傷害／加重結果之客觀預見可能 §277", "k": "要記：加重結果須客觀可預見；被害人騎車逃離後自摔遭輾＝異常因果，非行為人可預見→死亡不可歸責。", "law": "刑法§277、§277Ⅱ(加重結果犯)、§17、客觀歸責。", "trap": "A信賴原則不適用、C/D成立傷害致死/保證人地位均錯。"}, {"c": "包攝錯誤(涵攝錯誤) §16、§354", "k": "要記：知毀損他人財物違法，卻誤認『毒死動物不在毀損罪範圍』＝對法律涵攝之誤＝包攝錯誤(屬違法性錯誤)，不阻卻故意。", "law": "包攝錯誤、違法性錯誤§16、§354毀損。", "trap": "A動物為物仍成立毀損、B不知法律非必免除、C非構成要件錯誤(事實均認識)。"}, {"c": "正當防衛無業務特別義務之限制 §23", "k": "要記：『業務上有特別義務者不適用免責』之限制只在緊急避難(§24Ⅱ)；正當防衛無此限制。", "law": "刑法§23(正當防衛)、§24Ⅱ(緊急避難)。", "trap": "B防衛不須利益衡量、C對無責任能力人之侵害仍得防衛、D須防衛意思，皆對。"}, {"c": "無意識動作非行為／原因自由行為 §19", "k": "要記：依醫囑服藥後夢遊毆人＝無意識動作(非刑法上行為)，且非故意過失自陷→不適用原因自由行為。", "law": "刑法§19、原因自由行為(§19Ⅲ須故意或過失自陷)。", "trap": "A、B套用原因自由行為錯、C容許構成要件錯誤無關。"}, {"c": "強制性交之著手 §221、§25", "k": "要記：須已對被害人開始施強暴脅迫或為性交之相關侵害才算著手；僅褪己衣、戴套、『尚未撫摸』被害人＝預備，非著手。", "law": "刑法§221、§25(未遂之著手)。", "trap": "A拉扯褪褲撫摸陰部、B以陰莖摩擦陰部(不能未遂)、C灌醉褪衣撫摸全身，皆已著手成立未遂。"}, {"c": "中止未遂 §27", "k": "要記：出於己意停止並『積極防止結果發生』。", "law": "刑法§27(中止未遂，己意中止＋有效防果)。", "trap": "A因警察經過作罷(障礙未遂)、C已致重傷(既遂)、D因被害人反抗放棄(障礙未遂)。"}, {"c": "第三人沒收／繼續犯新舊法 §38-1", "k": "要記：犯罪所得移轉予『明知』之第三人，得對該非善意第三人宣告沒收。", "law": "刑法§38-1Ⅱ(第三人沒收)、繼續犯之新舊法、相續共同正犯。", "trap": "B繼續犯適用裁判時法無須新舊法比較、C先後參與成立相續共同正犯、D拘禁中另起意傷害應另論罪，皆對。"}, {"c": "想像競合之封鎖作用 §55", "k": "要記：上限取重罪之最高度(7年)；下限受『封鎖作用』，不得低於輕罪之最輕本刑(B罪2年)。", "law": "刑法§55(想像競合，從一重處斷但不得低於輕罪最輕本刑)。", "trap": "A、B、C未正確套用封鎖作用。"}, {"c": "偽證罪一案一罪 §168", "k": "要記：就『同一案件』之同一待證事實，縱於不同審級先後多次偽證，仍論一個偽證罪(接續犯)。", "law": "刑法§168(偽證罪)。", "trap": "A四罪、B兩罪、D想像競合，皆錯。"}, {"c": "緩刑應撤銷事由 §75", "k": "緩刑前犯強盜，緩刑期內受5年6月確定→應撤銷緩刑，無裁量餘地。", "law": "刑法§75第1項第1款(緩刑前因故意犯他罪，於緩刑期內受逾6月有期徒刑宣告確定→應撤銷，無裁量)。", "trap": "A緩刑期滿刑之宣告失效非累犯、C定執行刑逾2年不得緩刑、D命負擔者應付保護管束(未諭知違法)。"}, {"c": "受賄之職務行為(實質影響力說)", "k": "要記：民代之關說請託施壓，若實質運用職務或身分影響力使承辦人作為/不作為，且形式上具公務活動性質者，即屬『職務密切關連行為』。", "law": "貪污治罪條例§5受賄、職務上行為。", "trap": "A事後要求賄賂仍成立違背職務要求賄賂、B要求達到對方即既遂、D收賄後返還仍應沒收。"}, {"c": "妨害公務之加重類型 §135", "k": "要記：加重須『以兇器或以車輛對公務員施強暴』；單純駕車載人逃離、置物箱有工具但未持以施暴者，不該當加重。", "law": "刑法§135(110修正，加重事由：攜帶兇器、駕駛動力交通工具施強暴脅迫)。", "trap": "B以肉身阻擋非駕車施暴、C螺絲起子未持以施暴、D騎車載人逃離非以車施暴。"}, {"c": "投票受賄／候選人當選後成就 §143", "k": "要記：候選人於約定時雖非有投票權人，但『當選後』取得投票權，犯罪構成要件即成就。", "law": "刑法§143(投票受賄)。", "trap": "B無論當選與否皆不適格、C須當選在前、D要求免除其妻債務亦屬賄賂，皆錯。"}, {"c": "恐嚇取財 §346", "k": "要記：以加害(撕票寵物)之事通知，使被害人心生畏懼而交付財物＝恐嚇取財(非詐欺、非擄人勒贖、非強盜)。", "law": "刑法§346(恐嚇取財)。", "trap": "A詐欺、B強盜、C擄人勒贖，皆不該當(未實際擄物、非當場強暴)。"}, {"c": "湮滅證據罪限他人案件 §165、§169", "k": "要記：偽造證據『誣告他人使受刑事處分』＝誣告罪(§169)。", "law": "刑法§165(湮滅關係他人刑事案件之證據)、§169誣告。", "trap": "A湮滅自己犯罪證據不罰、B乙湮滅他人案件證據成立§165、D教唆他人湮滅自己證據不罰，皆對。"}, {"c": "偽證以依法具結為要件 §168、§186", "k": "要記：未滿16歲之證人不得令具結，縱誤命具結亦不生效力→不成立偽證罪。", "law": "刑法§168(偽證須依法具結)、§186(未滿16歲不得令具結)。", "trap": "A成立偽證減輕、B緊急避難、D乙成立偽證間接正犯(偽證為己手犯)，皆錯。"}, {"c": "醉態駕駛與逃逸之在場義務 §185-3、§185-4", "k": "要記：§185-4之『逃逸』指逃離事故現場而逸走，原則上行為人有在場(留置救護/處理)之義務。", "law": "刑法§185-3、§185-4。", "trap": "A 0.25mg為擬制標準不容反證、B致死傷不限過失、C不以無自救力為限。"}, {"c": "放火罪『燒燬』之認定 §173、§174", "k": "要記：建物之『重要構成部分(屋樑、屋脊、屋頂)』燒失才達『燒燬』。", "law": "刑法§173、§174(『燒燬』＝獨立燃燒並喪失主要效用/重要構成部分)。", "trap": "A僅木門桌椅鐵皮、C內部夾板桌椅(主結構僅略損)、D僅燻黑剝落，均未達燒燬。"}, {"c": "偽造署押 vs 偽造文書 §217、§210", "k": "要記：⚠️在『他人(機關)依法製作之文書』上偽簽他人姓名，若僅生署押之效果(無獨立之文書內容)→僅成立§217偽造署押。", "law": "刑法§217(偽造署押)、§210(偽造私文書)。", "trap": "A、B簽收欄偽簽生『收受』之文書效果、C申請書偽填申請人＝偽造私文書。(此區分較細，可對照詳解)"}, {"c": "乘機性交 vs 自己製造不能抗拒 §225、§221", "k": "要記：『自己下藥製造』被害人不能抗拒再性交＝§221強制性交(以藥物為違反意願方法)，非§225乘機。", "law": "刑法§225(乘機性交)、§221(強制性交)。", "trap": "B障礙者仍了解性交意義不成立乘機、C對既存狀態無認識不成立、D乘酒醉橫躺者成立乘機，皆對。"}, {"c": "重製性影像罪 §319-3", "k": "要記：未經被攝者同意重製其性影像＝§319-3重製性影像罪。", "law": "刑法§319-3(112新增，未經同意重製性影像)、§235。", "trap": "A自願拍攝紀念非『製造猥褻物品』、B交母帶給本人非散布、C應論§319-3(性影像新法優先§235)。"}, {"c": "侵害屍體罪 §247", "k": "要記：殺人後『以皮帶鞭屍洩憤』＝污辱屍體罪。", "law": "刑法§247(侵害屍體罪，保護對死者之虔敬/善良風俗)。", "trap": "A未對屍體處理不成立遺棄屍體、C投河時仍活著(殺人非遺棄屍體)、D本罪保護死者敬虔非被害人生命。"}, {"c": "供給賭博場所罪 §268", "k": "要記：供給賭博場所不限『公共場所』(住宅亦可)，但行為人須有『意圖營利』。", "law": "刑法§268(供給賭博場所/聚眾賭博)。", "trap": "B電話簽賭仍構成聚眾賭博、C邀同學家中打麻將(無營利)不成立、D無償提供場所而對提供本身無營利意圖者不成立，皆對。"}, {"c": "勸酒致死／被害人自我負責", "k": "要記：飲酒係被害人自主決定(自我負責)，勸酒者無保證人地位、結果不可歸責。", "law": "被害人自我負責、過失之客觀歸責、保證人地位。", "trap": "B加工自殺(非自殺)、C過失致死(自我負責不可歸責)、D不作為傷害致死(無保證人地位)，皆錯。"}, {"c": "聚眾鬥毆助勢罪須『聚眾』 §283", "k": "要記：甲乙『二人』單挑互毆非『聚眾』；旁人喊加油非傷害之幫助(互毆有承諾)。", "law": "刑法§283(聚眾鬥毆，須多數人鬥毆致場面混亂難辨致傷者)。", "trap": "B聚眾鬥毆助勢(非聚眾)、C傷害幫助犯(喊加油非幫助)、D二罪想像競合，皆錯。"}, {"c": "殺直系尊親屬／遺棄屍體 §272、§247", "k": "要記：養父依民法為直系血親尊親屬；移置屍體嫁禍＝遺棄屍體。", "law": "刑法§272(殺直系血親尊親屬，養父母亦屬)、§247(遺棄屍體)。", "trap": "A論普通殺人罪錯、B/D認移屍不成立遺棄屍體錯。"}, {"c": "妨害自由之競合 §302", "k": "要記：先強拉上車(§302既遂)後『另起意』強制性交＝兩個獨立犯意，應數罪，非僅論強制性交。", "law": "刑法§302(剝奪行動自由)、§221。", "trap": "B拉扯致輕傷為剝奪自由當然結果、C逾越現行犯逮捕必要仍成立§302、D略誘吸收剝奪自由，皆對。"}, {"c": "竊佔罪須排他占用 §320Ⅱ", "k": "要記：未排他占用(他人仍可通行)者，不成立竊佔。", "law": "刑法§320第2項(竊佔，須排除他人支配、建立自己支配)。", "trap": "A架鐵皮屋、C固定貨櫃作倉庫、D傾倒土石架圍籬設鐵門，皆為排他占用之竊佔。"}, {"c": "擄人勒贖結合犯須結合行為既遂 §348", "k": "要記：結合犯之結合行為(殺人)須『既遂』；殺人未遂者不成立結合犯，應數罪併罰。", "law": "刑法§348(擄人勒贖結合犯)、§347。", "trap": "A丙結合犯、C誤己為乙＝等價客體錯誤不影響故意、D取贖前釋放仍不適用§347Ⅴ減刑，皆對。"}, {"c": "加重重利與重傷之競合 §344-1、§278", "k": "要記：未實際取得重利＝重利未遂；催討中另行起意打成重傷＝重傷既遂，兩者數罪併罰。", "law": "刑法§344-1(加重重利)、§278(重傷)、§306(侵入住居)。", "trap": "A既遂(未取得重利)、C三罪想像競合、D含恐嚇取財，皆錯。"}, {"c": "妨害電腦使用罪 §358、§359", "k": "要記：輸入竊得之密碼入侵＝§358；取得私訊內容(電磁紀錄)＝§359。", "law": "刑法§358(無故入侵他人電腦)、§359(無故取得他人電磁紀錄)、§362。", "trap": "A僅§315-1不足、C§315書信秘密非電磁紀錄、D§362限『製作』專供犯罪之程式(甲用現成程式非製作)。"}, {"c": "濫權追訴處罰罪之實行行為 §125", "k": "要記：§125三種行為＝①濫用職權逮捕羈押 ②意圖取供而施強暴脅迫 ③明知有罪不使受追訴/明知無罪使受處罰。", "law": "刑法§125(三款)。", "trap": "B＝第2款、C＝第1款、D＝第3款，皆屬本罪行為。"}, {"c": "公務員之認定 §10Ⅱ", "k": "要記：大學教授接受『民間』委託或補助執行研究計畫之採購，非依法令從事公共事務→非刑法上公務員。", "law": "刑法§10第2項、最高法院103台上1254。", "trap": "B公營事業承辦監辦採購＝授權公務員、C委託公務員要件、D身分公務員，皆對。"}, {"c": "放火燒燬住宅未遂 §173Ⅲ", "k": "要記：放火既遂以建物『喪失效用』為準；僅燒木門、火即熄未延燒，住宅未喪失效用＝未遂。", "law": "刑法§173第3項(放火燒燬現供人使用住宅未遂)。", "trap": "A毀損建築物罪(被放火吸收)、B既遂(未達)、C預備(已著手非預備)。"}, {"c": "GPS竊錄＝非公開活動 §315-1", "k": "要記：車輛移動位置等同使用人之行動信息，整體行蹤有隱私期待＝『非公開之活動』，竊錄成立妨害秘密罪。", "law": "刑法§315-1、最高法院106台上3788。", "trap": "A GPS屬§315-1①工具、C竊錄行為、D非正當理由，皆對。"}, {"c": "傷害致重傷加重結果犯 §277Ⅱ", "k": "要記：被害人因逃避傷害而受之加重結果，與傷害行為有相當因果且客觀可預見→負加重結果之責；截肢＝毀敗一肢機能之重傷。", "law": "刑法§277第2項、§17(加重結果犯)、§10Ⅳ④(重傷)。", "trap": "A非自我負責、B截肢即重傷、D因果未中斷。"}, {"c": "過失犯／信賴原則之界限", "k": "要記：核對病人身分係主刀醫師『自身』之注意義務，不得單以信賴護理師免責(對自己應親自確認之事項無信賴原則適用)。", "law": "過失、信賴原則。", "trap": "A不得一律以醫學中心水準、B交通違規明顯有時間避免不得主張信賴、D過失注意義務與作為義務不同層次，皆對。"}, {"c": "被害人承諾之能力與範圍", "k": "要記：承諾能力依『個案認識判斷能力』而定，不以民法行為能力為準；承諾限『個人可處分法益』，不含生命；受詐欺之承諾無效。", "law": "被害人承諾(超法規阻卻違法)。", "trap": "B受詐欺之承諾無效(非得撤銷)、C不含社會法益、D生命法益不得承諾。"}, {"c": "依命令行為／教唆 §21、§29", "k": "要記：明知命令違法仍照辦者，依命令行為『不阻卻違法』；下令者成立教唆犯。", "law": "刑法§21(依命令行為)、§29(教唆)。", "trap": "A明知違法不阻卻違法、B明知違法難認無期待可能、C甲明知非無故意之工具故乙非間接正犯。"}, {"c": "違法性錯誤 §16", "k": "要記：對行為是否涉及不法有懷疑者，必要時負查詢義務；欠缺違法性認識而『無法避免』者免除其刑，『可避免』者得減輕。", "law": "刑法§16(違法性錯誤)。", "trap": "A§16指不知法律(非容許構成要件錯誤)、C可避免/不可避免之效果寫反、D誤想犯無§16適用。"}, {"c": "自首 §62", "k": "要記：自首只需『申告犯罪事實＋接受裁判』，不以承認過失或罪責為必要。", "law": "刑法§62(自首)。", "trap": "B想像競合未發覺之罪可自首、C申告後逃匿經通緝到案無自首、D委託他人代行自首之意仍有自首適用，皆對。"}, {"c": "利得沒收／相對總額原則 憲判18號", "k": "要記：利得沒收採相對總額原則，性質非刑罰，『不受罪刑法定原則拘束』；僅扣除合法成本(非所有成本)。", "law": "憲判字第18號、刑法§38-1(利得沒收)。", "trap": "C『先扣除所有成本』、D非善意第三人得主張信賴保護，均非該判決所採。"}, {"c": "偽造貨幣罪 §195", "k": "要記：偽造須『足以使一般人誤信為真』；技術拙劣到一望即知為假者，不該當偽造。", "law": "刑法§195(偽造貨幣)。", "trap": "A外國貨幣無強制流通力非通用貨幣、B須摹擬真幣(偽造不存在之通貨非偽造)、D意圖供行使限充作真幣流通，皆對。"}, {"c": "易科罰金 §41", "k": "要記：易科罰金以『新臺幣1千、2千或3千元』折算1日(法定金額)；依個人每日所得折算者是『易服勞役』。", "law": "刑法§41(易科罰金)、§42(易服勞役)。", "trap": "A完納期間、C侵占2月得易科、D詐欺6月得易科，皆對。"}, {"c": "立委影響力關說受賄／職務上行為", "k": "要記：⚠️實務(實質影響力說)認立委利用身分影響力之關說，仍屬與職務有關連之行為。", "law": "貪污治罪條例§5受賄、刑法§10Ⅱ。", "trap": "A立委為§10Ⅱ公務員、B性招待為不正利益、D性招待與關說有對價，皆對。(職務行為認定係林益世案爭點，可對照詳解)"}, {"c": "行賄／受賄既遂時點", "k": "要記：代他人行賄亦成立行賄罪；受賄於『收受』時即既遂，事後返還不影響。", "law": "貪污治罪條例§11行賄、§4枉法裁判、受賄。", "trap": "A甲交付賄款仍為行賄、B丙收受後返還已既遂、D承諾無罪未為枉法裁判不成立該罪。"}, {"c": "公務員圖利罪 貪污條例§6", "k": "要記：(4)主管監督事務圖利與(5)非主管監督事務圖利之『違背法令』範圍不同(後者限制較嚴)；圖利罪須『實際獲利』。", "law": "貪污治罪條例§6第1項第4、5款(圖利罪)。", "trap": "A依組織法規認定主管監督、B得成立共同正犯、D均以獲得利益為必要，皆對。"}, {"c": "圖利之利益範圍 §131", "k": "要記：圖利之不法利益含『積極增加』與『法律上應減少而未減少』之消極利益。", "law": "刑法§131(圖利)、§161Ⅱ、§135、§143。", "trap": "A§161Ⅱ為§135特別規定、B妨害公務須依法執行職務、C有投票權人含收賄後始獲投票權者，皆對。"}, {"c": "藏匿人犯／親屬減免 §164、§167", "k": "要記：犯人自行藏匿＝自我庇護不罰；近親(兄)藏匿犯人仍成立§164，但依§167減輕或免除其刑。", "law": "刑法§164(藏匿人犯)、§167(親屬間圖利犯人藏匿減免)。", "trap": "A、B、D對甲乙成立與否之組合錯誤。"}, {"c": "妨害公務罪 §135", "k": "要記：對『依法執行職務』之公務員施強暴脅迫＝妨害公務罪。", "law": "刑法§135第1項(妨害公務)。", "trap": "B§150妨害秩序(未危害公共秩序)、C§161脫逃(未在拘禁中)、D§283聚眾鬥毆(對丁係單方傷害)。"}, {"c": "公共危險罪之對應 §183、§184、§185", "k": "要記：在現有人所在之火車上引爆致脫軌＝§183傾覆破壞現有人所在交通工具罪，非§184。", "law": "刑法§183(傾覆破壞交通工具)、§184(損壞軌道壅塞)、§185、§175、§173。", "trap": "A飆車競速→§185、C放火燒機車波及他車→§175、D過失燒燬現供人使用住宅→§173Ⅱ，皆對。"}, {"c": "偽造 vs 登載不實 §210、§215", "k": "要記：以『自己名義(有製作權)』製作而內容不實＝登載不實(§215)，非偽造(偽造須冒用他人名義)。", "law": "刑法§210(偽造)、§215(業務登載不實)。", "trap": "A變更製作人為自己＝偽造、B冒名製作＝偽造、C有授權不成立偽造，皆對。"}, {"c": "利用權勢性交罪 §228", "k": "要記：⚠️利用師生監督關係，以加分為條件而與學生性交＝利用權勢性交罪。", "law": "刑法§228(利用權勢性交)、§227。", "trap": "A非強制(無強暴脅迫違反意願方法)、B非乘機、C與幼性交之競合取捨。(競合論述有爭議，可對照詳解)"}, {"c": "強制性交之違反意願方法 §221、§10Ⅴ", "k": "要記：以怪力亂神(小鬼纏身)恐嚇使人就範＝違反意願之方法→強制性交。", "law": "刑法§221(其他違反意願之方法)、§10第5項(性交定義)、§225。", "trap": "A麻醉昏迷＝乘機性交、C手指入口腔/D舌吻不在§10Ⅴ性交定義(口腔僅限性器進入)。"}, {"c": "公然猥褻 vs 散布猥褻物品 §234、§235", "k": "要記：公然猥褻是親自為猥褻『行為』；公然陳列或播放猥褻『影像』屬§235散布猥褻物品罪。", "law": "刑法§234(公然猥褻行為)、§235(散布陳列猥褻物品)。", "trap": "A須供人觀覽意圖、B賓館脫衣陪酒非公然、C意圖營利公然猥褻加重，皆對。"}, {"c": "略誘罪為繼續犯 §240、§241", "k": "要記：略誘罪為繼續犯，被誘人未回復自由前犯罪仍繼續中，於此期間參與看管者成立共同正犯。", "law": "刑法§241(略誘，繼續犯)、§240(和誘)。", "trap": "B母親使未滿7歲子女脫離父親親權可成罪、C略誘期間恐嚇被吸收、D和誘/略誘之區別，皆對。"}, {"c": "賭博罪含網路賭博 §266", "k": "要記：以網際網路賭博財物亦成立賭博罪(修法後已明文)。", "law": "刑法§266(108修正含電子通訊/網際網路賭博)、§268。", "trap": "A非公眾得出入處所賭博不成立§266、B年節小賭怡情(暫供娛樂之物)除外、D抽頭營利供賭場成立§268，皆對。"}, {"c": "凌虐不以長期持續為必要 §286", "k": "要記：§286凌虐行為不以長期性、持續性、多次性為必要(單一違反人道之對待亦可)。", "law": "刑法§286(凌虐)、§278、§283、§277Ⅱ。", "trap": "A重傷以治療終結為準(非初始)、B在場助勢不須與實行者有犯意聯絡、D殺人與傷害致死別在殺意有無(非部位)。"}, {"c": "恐嚇危安之加害內容 §305", "k": "要記：恐嚇須以『加害生命、身體、財產』之事為之；訴諸鬼神之詛咒(非行為人可掌控)不該當。", "law": "刑法§305(恐嚇危安)、§302、§134。", "trap": "A寄子彈郵包＝恐嚇、C持偽造公文騙拘票＝§134+§302、D取衣使無法離開澡堂＝§302，皆對。"}, {"c": "誹謗罪之查證義務 §310、釋字509", "k": "要記：查證義務之程度依『傳播範圍、影響』而不同；利用記者會傳播之查證義務『高於』茶餘飯後閒聊。", "law": "刑法§310(誹謗)、釋字509、§237。", "trap": "A相當理由確信為真不罰、B誹謗指摘具體事實/侮辱抽象謾罵、D告訴期間自知悉時起算逾6月，皆對。"}, {"c": "自己製造不能抗拒＝強制性交 §221、§225", "k": "要記：行為人『故意灌酒製造』被害人不能抗拒狀態再性交＝以違反意願方法之強制性交(§221)；乘機性交是利用『既存』之不能抗拒。", "law": "刑法§221(強制性交)、§225(乘機性交)。", "trap": "A未滿7歲一律§222、B7-14歲合意§227、D分工皆§222共同正犯，皆對。"}, {"c": "結夥三人限在場有責任能力者 §321①(4)", "k": "要記：結夥三人限『在場共同實行』且具責任能力之共同正犯；謀議而未到場者、無責任能力人不計入。", "law": "刑法§321第1項第4款(結夥三人以上加重竊盜)。", "trap": "B把風之乙(在場)計入、C入內之丙計入、D13歲之丁(無責任能力)不計入，皆對。"}, {"c": "強盜結合罪須基於強盜之機會 §332", "k": "要記：結合罪須於『強盜(或準強盜)之機會』另犯結合之罪；若係為性交而壓制，性交未果後『另起意』取財，欠缺強盜犯意之接續。", "law": "刑法§332(強盜結合罪)、§329(準強盜)。", "trap": "A竊盜當場殺人＝準強盜結合殺人、C強盜後放火、D強盜後重傷，皆成立§332。"}, {"c": "詐欺 vs 竊盜（有無處分意思）§339", "k": "要記：以詐術使被害人陷於錯誤而『自願為財產處分』＝詐欺；竊盜則無被害人之處分意思。", "law": "刑法§339(詐欺)、§320(竊盜)。", "trap": "A、B、C(竊盜/搶奪/強盜)皆因被害人有處分意思而不該當。"}, {"c": "贓物罪客體限犯罪所得他人財物 §349", "k": "要記：贓物＝『因財產犯罪所取得之他人之物』；行使自己債權所取得之款(本即應得)非贓物。", "law": "刑法§349(贓物罪)。", "trap": "A竊得腳踏車、B強盜金項鍊、D詐得花瓶，皆為贓物。"}, {"c": "教唆竊盜＋收受贓物為不罰後行為 §29、§349", "k": "要記：教唆犯收受『自己教唆所得』之贓物，屬不罰之後行為(已被教唆竊盜評價)，不另論收受贓物罪。", "law": "刑法§29(教唆)、§321、§349、不罰之後行為。", "trap": "C、D另論收受贓物(數罪/想像競合)、A僅論收受贓物，皆錯。"}, {"c": "因果歷程錯誤／概括故意", "k": "要記：因果歷程之偏離若非重要(在一般生活經驗可預見內)，不阻卻故意既遂。", "law": "刑法§13(故意)、概括故意(Weber)。", "trap": "A撞橋墩死、C同房間炸死丙丁(有未必故意)、D地雷炸死路人，均不應否定殺人故意。"}, {"c": "被害人承諾／推測承諾／重傷 §10Ⅳ", "k": "要記：已有『明示承諾』時，無『推測承諾』適用餘地(推測承諾用於無法取得明示同意時)。", "law": "刑法§10第4項(重傷)、被害人承諾、推測承諾。", "trap": "A承諾能力不以民法行為能力為準、B未成年對身體輕傷有處分權、D刺青非§10Ⅳ重傷。"}, {"c": "罪刑法定／類推禁止 §1、§2Ⅱ", "k": "要記：禁止類推適用，但『有利於行為人』者例外允許。", "law": "刑法§1(罪刑法定)、§2第2項(沒收適用裁判時法)。", "trap": "B有利之習慣法認定可參、C沒收適用『裁判時』法(非行為時)、D絕對不定期刑違反明確性不允許。"}, {"c": "肇事逃逸／義務衝突 §185-4", "k": "要記：明知肇事致人受傷而離去＝有逃逸『故意』與『行為』；但為履行更高義務(救重傷者)可主張義務衝突阻卻違法。", "law": "刑法§185-4(肇事逃逸)、義務衝突(超法規阻卻違法)。", "trap": "A不得正當防衛、B得主張義務衝突、D該當逃逸行為，皆對。"}, {"c": "責任能力 §19混合模式", "k": "要記：『生理原因(精神障礙)』由鑑定人判斷；但『辨識/控制能力之有無』屬法律評價，由『法官』判斷，非全交鑑定人。", "law": "刑法§19(混合生理心理模式)。", "trap": "A二要素、B行為時欠缺責任能力後痊癒不影響、C責任程度有輕重，皆對。"}, {"c": "毀損不罰未遂與過失 §354", "k": "要記：毀損罪『不罰未遂、不罰過失』。", "law": "刑法§354(毀損器物罪，無未遂、無過失處罰)。", "trap": "A障礙未遂、B不能未遂、C普通未遂，毀損罪皆無未遂處罰。"}, {"c": "聚眾妨害秩序罪 §150", "k": "要記：『聚集』不以隨時可增加為必要、亦不限不特定人；攜帶兇器得加重(Ⅱ)。", "law": "刑法§150(110年修正)。", "trap": "B攜帶兇器加重、C須實質危害秩序、D須妨害秩序故意，皆對。"}, {"c": "白手套／身分犯之共犯 §31", "k": "要記：無公務員身分之人，與有身分之公務員『共同』犯收賄罪，依§31Ⅰ仍成立公務員受賄罪(共同正犯)。", "law": "刑法§31第1項(身分犯之共犯)、§122受賄。", "trap": "A、B認不成立罪、C認成立背信罪，皆錯。"}, {"c": "數罪併罰定應執行刑 §51", "k": "要記：有期徒刑『最長期以上、合併以下、不逾30年』；罰金亦『最多額以上合併以下』；褫奪公權擇較長執行；沒收『各別宣告併執行』不併入。", "law": "刑法§51(定應執行刑)、§38沒收。", "trap": ""}, {"c": "自首與想像競合 §62", "k": "要記：想像競合之『一部』已被偵查機關發覺，其『他部』經行為人自動供出始得悉者，該他部仍屬『未發覺之犯罪』，得自首。", "law": "刑法§62(自首，限未發覺之罪)、§55想像競合。", "trap": "A、B否定自首、D『必減其刑』(自首為得減)皆錯。"}, {"c": "緩刑撤銷事由 §75、§75-1", "k": "要記：應撤銷＝緩刑期內『故意』犯他罪，於緩刑期內受『逾6月』有期徒刑宣告確定。", "law": "刑法§75(應撤銷)、§75-1(得撤銷)。", "trap": "A過失犯且緩刑前、C過失受拘役、D受無罪宣告，均非撤銷事由。"}, {"c": "醫師非公務員／侵占 §10Ⅱ、§335", "k": "要記：市立醫院醫師之『醫療行為』非依法令從事公共事務→非刑法上公務員，不成立受賄罪；乙侵吞代轉款＝侵占。", "law": "刑法§10第2項(公務員)、§335侵占。", "trap": ""}, {"c": "替代役男為公務員／要求賄賂 §122", "k": "要記：監所崗哨巡邏之替代役男＝執行公權力之公務員；公務員『要求』賄賂，於要求時即既遂，不待對方應允。", "law": "刑法§10Ⅱ(公務員)、§122(要求賄賂)。", "trap": "A否認公務員身分、C認未取得利益不成立、D成立包庇罪，皆錯。"}, {"c": "濫權追訴處罰罪之身分 §125", "k": "要記：本罪行為主體限『有追訴或處罰犯罪職務之公務員(檢察官、法官)』；司法警察不具本罪行為人適格。", "law": "刑法§125(濫權追訴處罰罪)。", "trap": "B、C仍認司警成立本罪、D詐術非本罪之強暴脅迫不正方法，皆錯。"}, {"c": "瀆職罪不再依§134加重", "k": "要記：§134加重有『但書』——犯罪本身已含公務員身分要素(純正瀆職罪如§213)者，不再依§134加重。", "law": "刑法§134但書、§213、§122、§135、§138。", "trap": "A§122優先§131、C§135須依法執行職務時、D§138掌管之物與所有權無涉，皆對。"}, {"c": "聚眾施強暴脅迫罪之犯意 §150", "k": "要記：聚眾犯意『不限聚集之初』——聚集後始生強暴脅迫之犯意者，亦成立本罪。", "law": "刑法§150(110修正)、最高法院111台上5048。", "trap": "B聚集含自動或被動、C須妨害秩序故意、D抽象危險犯與他罪競合或數罪，皆對。"}, {"c": "冒充公務員罪 §158", "k": "要記：冒充警察攔車盤查＝冒充公務員『行使職權』。", "law": "刑法§158(冒充公務員行使職權)、§150、§151、§159。", "trap": "A鐵鍊綁攤位討債非妨害公共秩序之§150、C玩遊戲裝扮非公然冒用服飾、D傳訊特定友人非恐嚇公眾。"}, {"c": "不能安全駕駛致死／競合 §185-3、§185-4", "k": "要記：酒駕(不能安全駕駛)『因而致人於死』＝§185-3Ⅱ加重結果犯(非與過失致死想像競合)；與肇事逃逸『數罪併罰』。", "law": "刑法§185-3第2項(不能安全駕駛致死)、§185-4(肇逃)、§51。", "trap": "C誤拆成想像競合。"}, {"c": "偽造文書／行使吸收 §210、§216", "k": "要記：偽造文書後復行使之，低度之偽造行為被高度之行使行為吸收，僅論『行使偽造文書罪』。", "law": "刑法§210、§212、§216(行使)。", "trap": "A統一發票偽造屬§210、B偽造私文書指無權製作(非內容虛偽)、D偽造畢業證書(§212)法定刑較輕。"}, {"c": "吸收關係之界限 §216、§169", "k": "要記：偽造、行使偽造私文書與『誣告』係侵害不同法益，不生吸收，不能全論誣告罪。", "law": "刑法吸收關係、§216行使、§169誣告。", "trap": "A偽造私文書被行使吸收、B偽造貨幣吸收行使、C偽造有價證券吸收行使，皆為實務承認之吸收。"}, {"c": "強制性交／同意之有效性 §221、§222", "k": "要記：以怪力亂神(遭天譴)脅迫使人就範＝違反意願之方法，被害人之同意非真摯有效。", "law": "刑法§221(強制性交『其他違反意願之方法』)、§222、§225。", "trap": "A熟睡觸摸＝乘機猥褻(§225)、C成立加重強制性交(§222)、D若構成加重強制性交則竊錄部分之處理，皆對。"}, {"c": "和誘略誘限未成年 §240、§241", "k": "要記：和誘、略誘罪之被誘人須為『未成年』；18歲已成年且係自願離家者，不成立。", "law": "刑法§240(和誘)、§241(略誘)、§298。", "trap": "A和誘、B略誘、C略誘婦女，均以未成年/違反意願為要件。"}, {"c": "侵害墳墓屍體罪 §247-§249", "k": "要記：發掘墳墓而盜取屍體，不論是否損壞屍體，均成立§249。", "law": "刑法§248(發掘墳墓)、§249(發掘墳墓結合盜取屍體等)。", "trap": "B盜墓財物本身即成立發掘墳墓罪、C無人清理仍成立§248、D夫妻合葬一墳為一發掘行為一罪。"}, {"c": "賭博罪 §266、§28", "k": "要記：在『供不特定人得出入之私人住宅』賭博＝公然賭博(§266)；對賭為對向犯，非共同正犯。", "law": "刑法§266(賭博)、§28(共同正犯)。", "trap": "A詐賭成立詐欺非賭博、B對向犯非共同正犯、D賭檯賭資不問屬於犯人與否沒收。"}, {"c": "打擊錯誤／親屬傷害之競合", "k": "要記：對A有傷害故意卻誤傷B＝對B為過失(打擊錯誤)；C係A之母(非甲之直系血親尊親屬)。", "law": "刑法§284(過失傷害)、§281、§282、§286。", "trap": "A掃飯菜未達凌虐、B非有效承諾傷害、C對C非『直系血親尊親屬』之施強暴。"}, {"c": "遺棄罪以無自救力人為對象 §293、§294", "k": "要記：遺棄罪以『無自救力之人』為對象；輕傷者尚能自救，非無自救力人。", "law": "刑法§293、§294(遺棄罪)、§185-4。", "trap": "A§293限積極作為、C黑垃圾袋蓋醉漢為積極遺棄、D扶養方法爭執拒不就養不該當，皆對。"}, {"c": "私行拘禁罪 §302、§304", "k": "要記：剝奪行動自由須持續一定時間；僅『瞬間』之拘束，至多成立強制罪。", "law": "刑法§302(私行拘禁)、§304(強制)。", "trap": "B鎖6歲兒童成立私拘、C不以陷於不能抗拒為必要、D另行傷害應與傷害競合(非僅論私拘)。"}, {"c": "妨害秘密罪／非公開活動 §315-1", "k": "要記：KTV包廂內有隱私期待＝『非公開之活動』，竊錄成立§315-1。", "law": "刑法§315-1(妨害秘密，竊錄非公開活動)。", "trap": "A GPS追蹤、B手機植入程式竊聽配偶、D刊登性侵照片不得以新聞自由阻卻，皆可成立。"}, {"c": "業務侵占 §336Ⅱ", "k": "要記：因『業務(受託代為存款)』而持有他人之物，易持有為所有(花光)＝業務侵占；事後返還不影響既遂。", "law": "刑法§336第2項(業務侵占)、§335。", "trap": "A普通侵占、C竊盜(係合法持有非竊取)、D無罪，皆錯。"}, {"c": "強盜殺人結合犯 §332", "k": "要記：以強暴強取財物(強盜)之機會，故意殺害被害人＝強盜殺人結合犯(§332Ⅰ)。", "law": "刑法§332第1項(強盜而故意殺人)、§328。", "trap": "A致死係過失致死(本題故意)、B搶奪(實為強盜)、D應論結合犯非數罪併罰。"}, {"c": "背信罪 §342", "k": "要記：構成要件＝『為他人處理事務』、違背任務之行為、故意、致生損害於本人財產。", "law": "刑法§342(背信)。", "trap": "A球員放水非為他人處理事務、C醫師錯誤治療為業務過失傷害、D受託投資疏忽虧損為過失(背信須故意)。"}, {"c": "毀損器物罪 §354", "k": "要記：潑難洗紅漆使名車外觀難回復＝減損其效用/致令不堪用。", "law": "刑法§354(毀損器物，毀棄、損壞或致令不堪用)。", "trap": "A強制罪、B強暴侮辱罪、D不成立犯罪，皆錯。"}, {"c": "累犯加重須檢察官主張舉證 釋字775、大法庭", "k": "要記：累犯之事實及加重，應由『檢察官主張並具體指出證明方法』，經調查辯論後始得加重——非法院依職權調查。", "law": "刑法§47、§57⑤、釋字775、最高法院110台上大字第5660號。", "trap": "B釋字775不應一律加重、C檢察官應主張舉證、D未主張時得列為§57⑤品行審酌，皆對。"}, {"c": "妨害電腦使用罪 §358、§359、§363", "k": "要記：§359無故刪除他人電磁紀錄，只要刪除致生損害即既遂，『不以無法回復為要件』。", "law": "刑法§358(入侵電腦)、§359(無故刪除電磁紀錄)、§363(告訴乃論)。", "trap": "A輸入帳密登入＝入侵電腦罪、B『無故』取得、D本章之罪告訴乃論，皆對。"}], "刑訴": [{"c": "土地管轄／船艦犯罪 §5", "k": "要記：在我國領域外之我國船艦內犯罪，由船艦本籍地、出發地或犯後停泊地之法院管轄；漁船船籍東港→屏東地院。", "law": "刑訴§5(土地管轄)。", "trap": ""}, {"c": "曾為證人應自行迴避 §17④、§18", "k": "要記：法官曾於該案為證人→應自行迴避；被告或檢察官均得聲請其迴避。", "law": "刑訴§17第4款(曾為該案證人應自行迴避)、§18(聲請迴避)。", "trap": "A『僅甲得聲請』、C『均不得聲請』、D『非被害人故無權』均錯。"}, {"c": "未滿18歲犯§227為告訴乃論 刑§229-1", "k": "要記：甲17歲犯§227與幼性交→依§229-1為告訴乃論；未經告訴，法院不得羈押(欠訴追條件)。", "law": "刑法§227、§229-1(未滿18歲犯§227須告訴乃論)、刑訴§101-1。", "trap": "A、B、C未注意§229-1之告訴乃論。"}, {"c": "惡意誘導放棄辯護權之自白 §158-2", "k": "要記：違反告知義務(緘默權/選任辯護人)取得之自白，出於惡意者絕對排除；非惡意且任意者例外得採。", "law": "刑訴§158-2第2項、§95。", "trap": "A『無強暴脅迫即可採』、B『審判外陳述一律不可採』均錯。"}, {"c": "得異議之詰問事由 §166-7、§167", "k": "要記：誘導、要求證人為意見或法律判斷→得異議；但證人就親自目擊之事實陳述，非傳聞。", "law": "刑訴§166-7、§167。", "trap": "A誘導、C要求法律判斷、D傳聞，均為一般得異議事由(本題不該當傳聞，故選B)。"}, {"c": "反對詰問權得放棄／具結能力 §186", "k": "要記：反對詰問權雖受憲法保障，仍得由被告放棄；未滿16歲不得令具結，但其證言非當然無證據能力。", "law": "刑訴§166、§180/§181、§186。", "trap": "A不得事先以恐受偽證追訴拒證、C14歲證言非無證據能力。"}, {"c": "勘驗中未具結之指訴 §158-3", "k": "要記：勘驗時告訴人之指訴、說明＝證言性質，依法應具結；未具結者無證據能力。", "law": "刑訴§158-3、§42、§205-2、§206。", "trap": "A機關鑑定書面有證據能力、B警察依§205-2得採尿、C鑑定報告法官不受拘束，皆對。"}, {"c": "無特定被害人之罪不得再議 §256", "k": "要記：再議權人是告訴人(被害人)；妨害投票正確罪保護國家選舉法益，無特定被害人→無人得告訴、再議。", "law": "刑訴§256(再議權人為告訴人)。", "trap": "A違法搜索、C誣告、D放火燒燬住宅皆有被害人，得再議。"}, {"c": "緩起訴後單獨聲請宣告沒收 §259-1", "k": "要記：緩起訴未經審判，法院不能在有罪判決一併宣告沒收；檢察官得就供犯罪所用之物單獨聲請法院宣告沒收。", "law": "刑訴§259-1、§253-2。", "trap": "A沒收非緩起訴負擔、B檢察官不得逕自沒收、C救濟途徑錯。"}, {"c": "對尊親屬不得自訴但對共犯得自訴 §321", "k": "要記：乙對父甲不得自訴；但基於被害人自訴權保障，對共同正犯之丙(非親屬)仍得自訴。", "law": "刑訴§321(對直系尊親屬不得自訴)、§319。", "trap": "B、C、D誤用自訴不可分而認對丙亦不得自訴。"}, {"c": "通緝書簽發與通緝犯逮捕 §84、§87", "k": "要記：偵查中通緝書由檢察長簽發；通緝犯得由檢察官、司法警察官及利害關係人逕行逮捕，一般路人不得。", "law": "刑訴§84、§87。", "trap": "B路人非利害關係人不得逮捕、C偵查中檢察長得簽發、D告訴人(利害關係人)得逮捕。"}, {"c": "附帶搜索不及於住處 §130", "k": "要記：拘提之附帶搜索限身體、隨身物、所用交通工具及立即可觸及之處所；庭院門口拘提，屋內非立即可觸及。", "law": "刑訴§130。", "trap": "A、D以嫌疑重大/反抗為由入內搜索，均逾越附帶搜索範圍。"}, {"c": "傳喚屬強制處分 §71、§75", "k": "要記：傳喚經合法傳喚無正當理由不到場，得命拘提。", "law": "刑訴§71、§75、§71-1。", "trap": "A傳票效力不及共犯乙、B檢察官亦得簽發傳票、D司警官得用通知書約談。"}, {"c": "拘票得作數通／域外執行 §77、§79、§81", "k": "要記：拘票得作數通分別交數人各別執行；司法警察必要時得於管轄區域外執行拘提。", "law": "刑訴§77、§79、§81。", "trap": "A得不經傳喚逕拘(§76)、B檢察官得自行簽發拘票、D得域外執行。"}, {"c": "羈押審查須訊問被告、自由證明 §101", "k": "要記：羈押前法官必須訊問被告；羈押審查之認定採自由證明即可。", "law": "刑訴§101、自由證明。", "trap": "A『不必訊問被告』、B『所有證據嚴格證明』、C『須兩造辯論』均錯。"}, {"c": "保全追徵得扣押其他財產 §133、刑§38-1", "k": "要記：為保全沒收/追徵之執行，得扣押被告其他財產(縱犯罪前購置之別墅)；登記第三人名下之犯罪所得亦得扣押、判決沒收。", "law": "刑訴§133、刑法§38-1。", "trap": "A、B、D誤認須與犯罪直接相關/第三人之物不得處理。"}, {"c": "監聽光碟之證據性質 §159", "k": "要記：監聽錄音光碟之對話內容＝物證/文書(數位證據)，言詞本身為犯罪行為→非傳聞；但不是『人證』(人證指證人到庭陳述)。", "law": "刑訴證據分類、§159。", "trap": "A含自白性質、B屬文書證據、D非傳聞，皆可。"}, {"c": "依通知到場者不得解送 §71-1、§92", "k": "要記：依警察通知書到場者，非經拘提或逮捕，得自由離去，警察不得違反其意願解送檢察官。", "law": "刑訴§71-1、§92。", "trap": "B以『非5年以上之罪』為由屬理由錯置；A、D認得解送錯。"}, {"c": "竊盜罪之直接被害人／告訴 §232", "k": "要記：⚠️本題官方答案B。花瓶所有權人為乙(直接被害人)；買受人丙於交付前僅債權受損，非竊盜直接被害人。", "law": "刑訴§232、刑法§324。", "trap": ""}, {"c": "變更法條限事實同一／追加起訴 §300、§265", "k": "要記：竊盜與故買贓物非同一事實→不得變更法條，甲應判無罪；對真正竊賊丁之追加起訴，本題實務認不合法→不受理。", "law": "刑訴§300、§265。", "trap": ""}, {"c": "曾經判決確定→免訴 §302①", "k": "要記：自訴傷害案判有罪，自訴人死亡無得上訴之人上訴→前案確定；後案傷害致死與前案同一事實→一事不再理，應諭知免訴。", "law": "刑訴§302第1款、§332。", "trap": "C認前案未確定錯。"}, {"c": "簡式審判之證據調查 §273-2", "k": "要記：簡式審判排除§159Ⅰ、§161-2、§161-3、§163-1、§164、§165之限制→被告自白得於其他證據調查完畢前調查。", "law": "刑訴§273-2。", "trap": "A、B為通常程序嚴格規定於簡式不適用；D交互詰問亦排除。"}, {"c": "上訴具體理由與死刑案件 §361", "k": "要記：⚠️通常案件僅記『量刑過重』不具體→不合法；但第一審判處死刑之案件，實務從寬，縱僅記量刑過重仍為合法上訴。", "law": "刑訴§361第2項。", "trap": "A通常案件量刑過重不具體、C未敘理由應命補正非逕判駁回。"}, {"c": "駁回調查證據聲請不得抗告 §404", "k": "要記：法院駁回調查證據之聲請＝判決前關於訴訟程序之裁定，不得抗告，當事人不服僅得於上訴時併予主張。", "law": "刑訴§404、§163-2。", "trap": "A得抗告、B聲明異議、C抗告或上訴皆錯。"}, {"c": "誤駁合法上訴之確定判決→非常上訴 §441", "k": "要記：上訴未逾期卻被二審誤認逾期以不合法駁回確定＝判決違背法令→須先以非常上訴撤銷該確定判決，始能就合法上訴審判。", "law": "刑訴§441、§379。", "trap": "A『逕審』、B『不得非常上訴』、C『再審』均錯。"}, {"c": "專業倫理與專門職業特性", "k": "要記：律師與當事人有特殊信賴關係，故負保守當事人秘密之義務。", "law": "法官/檢察官/律師之職業特性(效率、保密、客觀義務)。", "trap": "A『訴訟嚴重遲延也不可懲戒法官』錯；B『為委任人得詆毀中傷相對人』錯；D『檢察官不需考慮對被告有利證據』錯(違客觀義務)。"}, {"c": "法律人言論自由之限制", "k": "要記：法官對繫屬中案件不得公開評論，不限於自己承辦者，『他法官承辦』之案件亦同。", "law": "法官/檢察官/律師倫理規範(不得評論繫屬案件)。", "trap": "A判決後法院召開記者會說明、B律師為當事人發平衡言論、C檢察官經授權由發言人發布——均正確。"}, {"c": "法官投稿之分際", "k": "要記：法官投稿專欄不得對讀者『具體個案』提供如何起訴等具體法律建議。", "law": "法官倫理規範(不得對具體個案提供法律建議)。", "trap": "A介紹解釋法律+虛擬案例、B自擬提問介紹一般知識、C隱匿個資後評論確定判決——均不違反。"}, {"c": "法官私生活之謹慎義務", "k": "要記：法官私生活仍須謹言慎行；從事有損形象之行為(召妓)→違反。", "law": "法官倫理規範(謹言慎行、維護形象)。", "trap": "B『男歡女愛不涉品味』、C『有對價非濫用職位』——均不能正當化；D理由錯(問題在召妓非友人付帳)。"}, {"c": "法律倫理(未違背者)", "k": "要記：法官於程序中對法律爭議表示自己之法律見解(適度闡明/心證公開)→未違背。", "law": "法官倫理規範(適度闡明、不得規避職務、不得兼業、審判獨立)。", "trap": "B退休前取消所有期日改訂退休後(規避職務)；C下班後代親友撰訴狀收費(兼業)；D院長指示個案10日內終結(干預審判獨立)。"}, {"c": "檢察一體與職務指令", "k": "要記：檢察官與檢察長『法律意見不同』，檢察長不得以此為由送個案評鑑；指揮命令應以書面。", "law": "法院組織法(檢察一體、書面命令)、檢察官評鑑。", "trap": "A『口頭命令要求改變法律意見應接受』、C/D行使職務承繼/移轉權須以『書面』為之——均錯(口頭不可)。"}, {"c": "檢察官律師配偶之宿舍使用", "k": "要記：律師配偶得居住檢察官職務宿舍、同事假日來訪餐敘→屬正常生活，不違反。", "law": "檢察官倫理規範(得共同居住，但不得作律師業務用)。", "trap": "A『不得一起居住』、B『須機關同意才可居住』過嚴；C將宿舍與客戶商談案情(利用職務處所辦律師業務)。"}, {"c": "檢察官參選之限制", "k": "要記：檢察官欲參選立委，須於該屆立委任期屆滿『1年前』辭去檢察官職務。", "law": "公職人員選罷法、檢察官倫理規範(參選須先辭職)。", "trap": "A『任職期間可登記、當選後再辭』、B『可參選惟不可參加政黨活動』、C『初選獲提名再辭』——均不符規定。"}, {"c": "檢察官與新聞媒體", "k": "要記：檢察官得上媒體作一般法治宣導；對偵查中案件之說明須有公益必要並經檢察長授權。", "law": "檢察官倫理規範(偵查不公開、不得評論繫屬案件)。", "trap": "A『不可參加任何談話節目』過絕對；B評論非自己承辦之偵審中重大案件；D對媒體釋放假訊息——均違反。"}, {"c": "律師名片不得列兼任公職", "k": "要記：律師不得在名片上顯示其『兼任之公務機關職務』(如訴願委員)。", "law": "律師倫理規範(不得以兼任公務職務作宣傳)。", "trap": "A『有兼任就不違反』、B『有踐行迴避就不違反』、D『只能列學歷不能列任何經歷』——均錯。"}, {"c": "律師不得以勝訴率宣傳", "k": "要記：律師不得以訴訟案件之『勝訴率』作為推展業務之宣傳內容。", "law": "律師倫理規範(廣告不得以勝訴率宣傳)。", "trap": "A『數據正確就不違反』、B『律師根本不得用網站廣告』(過絕對)、C『列案號供查證就可』——均錯。"}, {"c": "律師接見羈押被告之物品傳遞", "k": "要記：律師接見羈押中被告，除與案情有關之書狀傳遞外，不得交付任何物品。", "law": "律師倫理規範、羈押法(僅得傳遞與案情有關書狀)。", "trap": "A『羈押被告有權閱覽私人文件』、B『未禁見禁通信就可交付』、C『與案情無關就可交付』——均錯。"}, {"c": "檢察官旋轉門之絕對迴避", "k": "要記：曾以檢察官蒞庭之案件，轉任律師後不得受任該案相同或實質相關事件之任一方(旋轉門)。", "law": "律師法、律師倫理規範(曾以前職參與之案件絕對迴避)。", "trap": "B『得B書面同意就可』、C『離職滿3年就可』、D『刑事民事不同程序可受任』——均錯(此為不得同意/時間排除之絕對迴避)。"}, {"c": "律師後酬之限制", "k": "要記：財產權案件(如專利侵權)得約定勝訴後酬；刑事與家事事件禁止後酬。", "law": "律師倫理規範(財產案件得約後酬；刑事/家事禁後酬；不得受讓訟爭標的)。", "trap": "B離婚贍養費(家事)約後酬、C詐欺刑事案件約後酬、D訴訟中約定由律師購買訟爭土地——均違反。"}, {"c": "二親等律師分受兩造之衝突", "k": "要記：二親等內血親之律師，不得分別受同一案件相對造之委任(利益衝突)。", "law": "律師倫理規範(一定親等內律師不得分受同一案件相對造)。", "trap": "A『能保持獨立性即不違反』、B『平常無往來不構成衝突』、D『不同事務所就無衝突』——均錯。"}, {"c": "法官自行迴避 §17", "k": "要記：『偵查中羈押審查』之法官，於該案起訴後辦理審判，不構成§17自行迴避事由。", "law": "刑訴§17(自行迴避)。", "trap": "A發回更審原法官可參與；C準備程序法官遷調再受理；D三審撤銷者再參與更審→應迴避。"}, {"c": "法院依職權調查 §163Ⅱ", "k": "要記：『法院為發見真實，得依職權調查證據』——對被告不利之證據，法院有裁量權，『得』(非應、非不得)依職權調查。", "law": "刑訴§163第2項本文。", "trap": "A『一律不得』、C『應』、D『未調查即違法』均過度。"}, {"c": "羈押審查辯護人閱卷 §33-1", "k": "要記：辯護人於偵查中羈押審查程序『得檢閱卷證並抄錄或攝影』；檢察官得向法院聲請限制辯護人獲知部分卷證。", "law": "刑訴§33-1。", "trap": "B『不得限制』、C『僅被告有』、D『不可以』均錯。"}, {"c": "羈押審查卷證獲知 §33-1", "k": "要記：卷證檢閱權給『辯護人』；§33-1未賦予『有辯護人之被告本人』親自檢閱卷證之權。", "law": "刑訴§33-1、§31-1。", "trap": "A、B指定辯護(§31-1)、C辯護人得檢閱抄錄攝影(§33-1)，皆對。"}, {"c": "附帶搜索 vs 緊急搜索住所 §130、§131", "k": "要記：合法逮捕得附帶搜索身體、隨身物、所用交通工具及立即可觸及處所；『搜索住所』須符§131緊急搜索要件。", "law": "刑訴§130(附帶搜索)、§131(緊急搜索)。", "trap": "A現行犯逮捕、B附帶搜索身體車輛、D限正在使用之車輛，皆對。"}, {"c": "檢視手機內容＝搜索須令狀 §122、§128", "k": "要記：撿獲手機得扣押該物；但開機檢視內部訊息、通聯=對內容之搜索，須報請檢察官向法院聲請許可。", "law": "刑訴§122、§128(搜索須法官令狀)。", "trap": "A逕自查看、C報局長同意、D報檢察官同意，均不足。"}, {"c": "逕行搜索住宅 §131Ⅰ", "k": "要記：為逮捕被告或現行犯，有事實足認其在內者，得不待搜索票逕行進入住居所搜索。", "law": "刑訴§131第1項。", "trap": "A『僅限拘提逮捕時』、C未補拘票之扣押物無須返還、D『僅限同意』，均錯。"}, {"c": "逕行搜索之急迫要件 §131Ⅰ", "k": "要記：客觀情形已可合理相信有人在內犯罪且情形急迫(如聞救命聲)→得逕行進入搜索，合法性來自急迫事由本身。", "law": "刑訴§131第1項。", "trap": "A、B誤認須搜索票/限24小時內滅證；C合法性非來自事後同意。"}, {"c": "限制出境出海 §93-2", "k": "要記：限制出境出海得依聲請或依職權撤銷或變更；無罪等判決視為撤銷。", "law": "刑訴§93-2～§93-6。", "trap": "A偵查中檢察官得逕行限制、B無罪視為撤銷、D具保事由得命限制出境，皆對。"}, {"c": "保全扣押得聲請撤銷 §133-2、§142", "k": "要記：保全沒收/追徵之扣押，受扣押人得聲請撤銷扣押。", "law": "刑訴§133、§133-2(保全扣押)、§142(撤銷扣押)。", "trap": "A為擔保追徵、B急迫得逕扣後3日內陳報、D司警官報請檢察官許可後聲請，皆對。"}, {"c": "規避身分之詐欺取供 §156Ⅰ", "k": "要記：明知甲為實質被告卻以『證人』身分訊問規避告知義務、取得不利供述=詐欺取供→依§156Ⅰ無證據能力(絕對排除，非§158-4權衡)。", "law": "刑訴§156第1項(不正方法取供絕對排除)。", "trap": "A、B誤走§158-4或認任意即可採。"}, {"c": "另案監聽未補陳報 通保法§18-1", "k": "要記：另案監聽原則排除、例外容許(重罪或關連性)。⚠️未於7日內補陳報者，實務認仍得依§158-4權衡，非一律不得審酌。", "law": "通訊保障及監察法§18-1、刑訴§158-4。", "trap": "A原則排除例外容許、B重罪或關連、D偽以本案聲請者絕對排除，皆對。"}, {"c": "動機證據與犯罪事實有關 §154", "k": "要記：證明殺人動機之遺書，與犯罪事實(犯意/動機)有關，具關連性→有證據能力。", "law": "刑訴§154、嚴格證明。", "trap": "B『無關』、C『品格證據』、D『被告提出才有』均錯。"}, {"c": "性侵被害人警詢 釋字789", "k": "要記：釋字789對被告防禦權應採有效補償措施、被害人警詢不得為有罪唯一證據；但並非『一律』隔離詰問。", "law": "釋字789、刑訴§159-1。", "trap": "B、C、D均為釋字789所採。"}, {"c": "證據方法之性質", "k": "要記：⚠️警察『現場勘察報告』含勘驗、判斷性質，非單純『書證』。", "law": "刑訴各證據方法(人證/物證/書證/勘驗/鑑定)。", "trap": "A鑑定為人證方法、C鑑定證人適用證人程序、D共同被告依人證調查，皆對。"}, {"c": "檢察官退案命補足 §231-1", "k": "要記：檢察官對司法警察移送之案件，認調查未完備(如未採尿)，得退回命其補足或逕行調查。", "law": "刑訴§231-1、§205-2(採尿)。", "trap": "B『已自白無須採尿』、其餘處置非最適。"}, {"c": "法律違憲失效之處理 §302④", "k": "要記：⚠️依最高法院刑事大法庭，所適用刑罰規定經大法官宣告違憲失效者，應依§302④諭知免訴。", "law": "刑訴§302第4款(犯罪後法律已廢止其刑罰→免訴)。", "trap": "C判無罪、D變更法條免刑方向錯。(A與B就是否先為新舊法比較係大法庭爭點，可對照詳解)"}, {"c": "受命法官得實施勘驗 §279", "k": "要記：受命法官於準備程序得實施勘驗；但停止羈押裁定、證據能力裁定屬合議庭，審判期日指定屬審判長。", "law": "刑訴§279(受命法官準備程序)、§212(勘驗)。", "trap": "A具保停止羈押裁定、C證據能力裁定、D指定審判期日，非受命法官單獨得為。"}, {"c": "被告不到庭不得審判 §281", "k": "要記：原則被告未到庭不得審判；殺人案不適用逕行判決之例外。", "law": "刑訴§281、§294Ⅲ、§379⑥。", "trap": "B未到庭逕判當然違背法令、C心神喪失顯應免刑得審、D疾病顯應無罪得審(§294Ⅲ)，皆對。"}, {"c": "簡式審判得獨任 §273-1", "k": "要記：簡式審判『得由獨任法官』審判，不適用傳聞法則、毋庸交互詰問。", "law": "刑訴§273-1、§273-2。", "trap": "A不適用傳聞、B誤裁簡式但實依通常程序審理不違法、C毋庸交互詰問，皆對。"}, {"c": "冒名應訊之判決 §452", "k": "要記：冒名者(甲)始為真正被告；對被冒名之乙，二審應依通常程序為第一審判決，諭知乙無罪。", "law": "被告之特定、刑訴§452。", "trap": "B、C、D處理方式錯。"}, {"c": "職權命第三人參與沒收 §455-12Ⅲ", "k": "要記：第三人財產可能被沒收而未經其聲請、檢察官亦未聲請者，法院得依職權裁定命其參與沒收程序並諭知沒收。", "law": "刑訴§455-12第3項。", "trap": "A、B、C誤認控訴原則限制法院不得為之。"}, {"c": "自白任意性以自由證明 §156Ⅲ", "k": "要記：自白任意性之有無＝訴訟法上事實，以自由證明為已足；且應『先於』其他事證調查。", "law": "刑訴§156第3項。", "trap": "B『不得於準備程序調查』、C『得於其他事證後緊接調查』均錯。"}, {"c": "想像競合一部上訴之審理範圍 §348", "k": "要記：想像競合中不另為無罪諭知部分，當事人未上訴(僅就有罪部分上訴、檢方未上訴該部分)→該部分已確定，第三審不得審理。", "law": "刑訴§348、§376。", "trap": ""}, {"c": "程序違法之確定判決→非常上訴 §441", "k": "要記：原確定判決不傳喚聲請之證人、未敘理由＝判決違背法令→請求檢察總長提非常上訴。", "law": "刑訴§441、§426。", "trap": "A再審應向原審法院、B停止執行非救濟本案、D聲明疑義係文義不明。"}, {"c": "法官網路行為之分際", "k": "要記：法官得評論『已確定判決』之法律見解；但不得評論繫屬中案件。", "law": "法官倫理規範(政治中立、保密、不得兼職營利)。", "trap": "A匿名部落格收費宣傳產品(兼職營利)；B網路公開支持政治人物(政治中立)；D敘述個案當事人姓名細節引為笑談(洩密、損尊嚴)。"}, {"c": "法官庭審行為之分際", "k": "要記：法官為維持法庭秩序，得禁止違規(如錄影)且不聽制止者旁聽。", "law": "法官倫理規範(不得預斷、審判獨立、不得威嚇證人；得維持秩序)。", "trap": "A預斷『請誰辯護都沒用』；B當庭打電話與他案法官討論事實認定(審判獨立)；C向證人說『說謊下地獄』(不當威嚇)。"}, {"c": "法官職務外行為之分際", "k": "要記：法官得為學生向『無利害關係』機構撰求職介紹信；但不得利用身分圖私利。", "law": "法官倫理規範(不得利用身分圖利或不當影響)。", "trap": "B向職務法庭具名擔保受懲戒法官品操、C要求優先安排子女至法院當志工、D購屋表明身分求折扣——均違反。"}, {"c": "法官倫理之具體規範", "k": "要記：法官『得』為家庭成員提供一般法律意見(非在其繫屬案件提供策略)。", "law": "法官倫理規範(自訴代理、兼職、募款、家庭成員法律意見)。", "trap": "A法官不得為自訴代理人、C兼教職須經機關同意、D不得為政治團體募款——均正確。"}, {"c": "法官避免不當行為之規範意旨", "k": "要記：職務『內外』一切行為，只要易被通情達理旁觀者認為不當即應避免，目的係維繫公眾對司法之信任。", "law": "法官倫理規範(避免不當或易被認為不當之行為)。", "trap": "A目的誤為『降低審判犯錯機率』；B/D限於『職務上』、職務外不在此限——均錯(應及於職務內外)。"}, {"c": "三者倫理關係", "k": "要記：法官、檢察官、辯護律師雖各司其職，仍應相互協力實現司法正義與人權保障。", "law": "法官/檢察官/律師倫理規範(各司其職、相互協同)。", "trap": "A檢察官非受『審判獨立』保障(那是法官)；B刑事審判得有協商程序；D『私下不宜交往或成為男女朋友』過嚴。"}, {"c": "檢察官與律師配偶之分際", "k": "要記：檢察官與其律師配偶『共同居住』於檢察官職務宿舍→不違反。", "law": "檢察官倫理規範(不得介入配偶律師業務/利用職務處所)。", "trap": "B在家幫配偶寫律師答辯狀(介入律師業務)；C請法警帶配偶在檢察官辦公室休息(利用職務便利)；D於職務宿舍與當事人商討案情(利用職務處所)。"}, {"c": "檢察官與律師同學之分際", "k": "要記：檢察官/法官不得出席候選人造勢晚會擔任推薦人或站台(政治中立)。", "law": "檢察官倫理規範(政治中立、迴避)。", "trap": "A共同出席學校親子日、B無密切交往無須自請迴避、D無相關案件可共辦同學會——均不違反。"}, {"c": "律師承辦無經驗案件", "k": "要記：律師承辦新類型案件不必主動告知無經驗，但接任後應努力精研以盡職。", "law": "律師倫理規範(誠實、盡力精研)。", "trap": "A『無論如何不得承辦無經驗業務』過絕對；B『誠實告知後仍違反』、C『無經驗受任即違反』——均錯。"}, {"c": "律師業務宣傳之界限", "k": "要記：律師不得於網頁/名片揭示其『兼任之公務職務』(如評鑑委員)作宣傳。", "law": "律師倫理規範(不得以兼任公務職務作宣傳)。", "trap": "A學歷、B專業領域、C兼課學校科目職稱——均得揭載。"}, {"c": "律師保密義務之範圍", "k": "要記：律師辦案所知悉之一切資訊秘密皆在保密範圍，非經當事人同意不得揭露。", "law": "律師倫理規範(保密義務涵蓋一切辦案所知)。", "trap": "A『與本案爭點無關就不在保密範圍』、C『除非特別交代否則可洩漏』、D『只有與名譽無關才可洩漏』——均錯。"}, {"c": "律師暗示能影響司法", "k": "要記：律師暗示自己能不當影響司法(與法官熟識)→縱未實際影響，即已違反。", "law": "律師倫理規範(不得暗示能不當影響司法)。", "trap": "A『沒答應一定去找』、B『實際沒去找未影響』——均不能免責；C『有同事關係即須迴避』過絕對(問題在暗示影響)。"}, {"c": "頂罪案件之費用收受", "k": "要記：涉及要他人『頂罪』者影響律師獨立判斷，律師不得收受該第三人代付之費用。", "law": "律師倫理規範(第三人付費不得影響獨立判斷；不得助長違法)。", "trap": "A『有人付費就好』、B『B同意就可』、D『可收費僅不可約後酬』——均忽略頂罪違法且影響獨立判斷。"}, {"c": "律師行為(不違反者)", "k": "要記：律師閱卷後得告知羈押中當事人卷證筆錄內容(正當辯護)。", "law": "律師倫理規範(不得保證結果、保密、不得不實宣傳；得正當辯護)。", "trap": "A保證必得親權(保證結果)；B離職後將前當事人B機密揭露給新事務所(洩密)；C不具專利知識卻宣稱專家招攬(不實宣傳)。"}, {"c": "共同受任律師之合作義務", "k": "要記：共同受任同一事件之數律師，應互相協調合作、共享辦案資料。", "law": "律師倫理規範(共同受任應協調合作)。", "trap": "A『乙應直接向當事人索取』、B『不同事務所就不需提供』、D『以熟識與否區分』——均不當。"}, {"c": "撤銷羈押須原因全部消滅 §107", "k": "要記：羈押有數原因(逃亡＋串供)，須『全部』消滅才撤銷；串供之虞消滅後，仍須認定有無逃亡之虞，再審酌。", "law": "刑訴§107(撤銷羈押)。", "trap": "A、D只看一個原因即主張撤銷；B理由不足。"}, {"c": "司法警察用通知書非傳票 §71-1", "k": "要記：司法警察(官)叫人到場用『通知書』，不能發『傳票』(傳票是檢察官/法院)。", "law": "刑訴§71-1(警察通知書)、§75、§101-1。", "trap": "A傳喚不到簽拘票、C逕命具保、D預防性羈押須先逮捕(逮捕前置)，皆合法。"}, {"c": "未告知緘默權→§158-4權衡", "k": "要記：違反緘默權告知取得之自白，依§158-4『權衡人權保障與公共利益』決定有無證據能力。", "law": "刑訴§95①(緘默權告知)、§158-4(權衡)。", "trap": "A絕對排除、B『非惡意＋任意則得』、C『任意即可』均非本題實務。"}, {"c": "具結能力／告訴人陳述補強 §186、§158-3", "k": "要記：未滿16歲不得令其具結；縱『誤命具結』，其證言『不因此無證據能力』(具結不生效但證述仍可採)。", "law": "刑訴§186(具結能力，未滿16歲不得令具結)、§158-3、§156Ⅱ。", "trap": "A告訴須補強、B法代轉述屬傳聞、C偵查筆錄未提示朗讀不得採，皆對。"}, {"c": "被害人告訴與獨立告訴各自獨立 §233", "k": "要記：被害人自己之告訴權與法定代理人之獨立告訴權『各自獨立』；被害人得自行撤回告訴，無須徵得獨立告訴權人同意。", "law": "刑訴§233(法定代理人獨立告訴)、§238。", "trap": "A丙仍得獨立告訴；B不須先撤回甲告訴；D方向錯。"}, {"c": "親屬相盜告訴乃論之撤回不及非親屬共犯 §239", "k": "要記：親屬相盜(§324Ⅱ告訴乃論)僅及『有親屬關係之乙』；對乙撤回告訴之效力『不及於』非親屬之丙→丙仍得起訴。", "law": "刑訴§239但書(告訴乃論基於身分者，撤回不及非該身分共犯)、§324。", "trap": "B告訴非證言不適用§158-3；C偵查中告訴代理人卷證獲知受限。"}, {"c": "在監被告之送達與上訴期間 §56、§349", "k": "要記：被告在監，向『監所長官』送達始合法(3/6)；上訴期間20日自次日起算，在監向監所送達無在途期間。", "law": "刑訴§56(在監所人之送達向監所長官為之)、§349(上訴期間20日)、§66在途。", "trap": "其餘起算日/在途計算錯。"}, {"c": "得不經傳喚逕行拘提仍須拘票 §75、§76", "k": "要記：被告無一定住居所、犯罪嫌疑重大→必要時『得不經傳喚』逕行拘提，但『仍須持拘票』。", "law": "刑訴§75、§76(無一定住居所等得不經傳喚逕行拘提)。", "trap": "A、B不持拘票錯；C仍須先傳喚錯。"}, {"c": "羈押由法院裁定／懷孕得停止羈押 §102、§108、§114", "k": "要記：羈押由『法院』裁定，檢察官只能聲請；懷孕5月以上等情形(§114③)聲請具保停止羈押，查屬實『應准』。", "law": "刑訴§102(羈押由法院裁定)、§108(延長羈押)、§114(駁回具保之例外)。", "trap": "A檢察官不能命羈押；B最重本刑3年以下非不得羈押；D審判中延長羈押每次不逾2月(非3月)。"}, {"c": "鑑定人無受選任義務 §197", "k": "要記：鑑定人義務＝到場、具結、公正誠實；但『無應受選任之義務』(得拒絕受選任，與證人之作證義務不同)。", "law": "刑訴§197(準用人證)、§199(鑑定人不得拘提)、§202(具結)。", "trap": "A到場、B具結、D公正誠實，皆為鑑定人義務。"}, {"c": "勘驗被告在場權 §150", "k": "要記：勘驗應於審判期日由法院行之，並保障當事人、辯護人在場；法官私下在辦公室勘驗、僅事後提示，違背法定程序，勘驗筆錄不得採為裁判依據。", "law": "刑訴§150(勘驗當事人/辯護人在場權)、§42、§164。", "trap": "A、B、C忽略在場權保障。"}, {"c": "逮捕現行犯得逕入住宅 §131Ⅰ", "k": "要記：追捕現行犯，有事實足認其確在他人住宅內者，警察得『逕行進入該住宅』搜索逮捕，不待搜索票。", "law": "刑訴§131第1項(逕行搜索/緊急搜索)。", "trap": "B不須檢察官許可；C得進入；D事後陳報法院之程序與此不同。"}, {"c": "受命法官準備程序得調查證據能力 §279", "k": "要記：準備程序有『篩選證據』功能，受命法官得就『證據能力之有無』進行證據調查(如傳喚證人說明鑑定可信性)。", "law": "刑訴§279(受命法官準備程序)、§273①。", "trap": "A、B誤認準備程序不得調查證據能力；C誇大為廣泛實質調查。"}, {"c": "簡易判決僅一次救濟 §455-1", "k": "要記：通常程序改簡易判決，不服向『管轄二審之地院合議庭』上訴，合議庭判決後『僅一次救濟』，不得再上訴第三審。", "law": "刑訴§455-1(簡易判決上訴管轄第二審地院合議庭)。", "trap": "A、B誤認得上訴三審；C誤認僅被告得上訴。"}, {"c": "辯護人上訴為代理、以被告名義 §346", "k": "要記：原審辯護人之上訴性質為『代理上訴』，應以『被告名義』提起，且不得與被告明示意思相反。", "law": "刑訴§346(原審辯護人得為被告利益上訴)。", "trap": "B、C、D以辯護人自己名義或稱『獨立上訴』均錯。"}, {"c": "同一案件撤銷發回維審級利益 §369、§303", "k": "要記：過失重傷害與過失致死＝同一案件(同一過失行為)；一審誤以告訴逾期諭知不受理，二審不宜自為實體判決(剝奪審級利益)，應撤銷發回原審。", "law": "刑訴§369Ⅰ但書、§303。", "trap": "A、B二審自為判決剝奪審級；C誤認非同一案件。"}, {"c": "得上訴三審之罪 §376", "k": "要記：行使偽造私文書本得上訴三審；竊盜原不得上訴三審，但一審認『不成立』、二審『初次改判有罪』→屬對被告不利之初次有罪認定，得上訴三審；詐欺一二審均認成立、無初次不利→不得單獨上訴三審。", "law": "刑訴§376(不得上訴三審之罪及但書)。", "trap": ""}, {"c": "冒名頂替之被告特定", "k": "要記：被告應為『真正到庭應訊之行為人(甲)』；甲冒乙之名，判決對乙係錯誤，乙非被告。", "law": "被告之特定(實際應訊受審判之人)、§455-1。", "trap": "A、B更正/重送不足以糾正主體錯誤；C對象錯(應對乙)。"}, {"c": "輔佐人之權限 §35", "k": "要記：輔佐人得陳述意見、聲請調查證據、辯論證據證明力、聲請撤銷羈押等；但『無詰問證人』之權(詰問屬當事人/辯護人/代理人)。", "law": "刑訴§35(輔佐人)、§166(詰問權主體)。", "trap": "B、C、D均屬輔佐人得為。"}, {"c": "附帶搜索限立即可觸及 §130", "k": "要記：附帶搜索及於身體、隨身物、所用交通工具、立即可觸及之處所；停在地下室之機車已『非立即可觸及』，逾越範圍。", "law": "刑訴§130(附帶搜索)。", "trap": "A只看『交通工具』忽略立即可觸及；C、D理由錯。"}, {"c": "身體檢查 §205-1、§205-2、§123", "k": "要記：檢查婦女身體，應命醫師或婦女行之。", "law": "刑訴§205-1、§205-2(身體檢查)、§123(檢查婦女身體)。", "trap": "A對象不限犯嫌；C對拒絕者不得『直接』採血(採血須鑑定許可書)。"}, {"c": "嚴格證明 vs 自由證明", "k": "要記：『犯罪事實』及『與犯罪事實有密切關連之科刑事實(動機、目的、所生危害、違反義務程度)』須『嚴格證明』；程序事項、沒收利得、限制出境事由、傳聞例外要件等用自由證明。", "law": "嚴格證明法則、§154、§155。", "trap": "B、C、D屬自由證明事項。"}, {"c": "開始再審後得停止刑罰執行 §435", "k": "要記：法院裁定開始再審後，『得裁定停止刑罰之執行』。", "law": "刑訴§435第2項、§430。", "trap": "A不能逕釋放；B再審非起訴不能撤回；C檢察官本於客觀義務得請求無罪。"}, {"c": "沒收附隨於不得上訴三審之本罪 §376", "k": "要記：背信屬§376不得上訴三審之罪；沒收附隨於本罪，本罪不得上訴三審→沒收部分亦不得單獨上訴三審。", "law": "刑訴§376(110修正，初次有罪得上訴三審但書)。", "trap": "B、C不得上訴三審；D一審無罪二審改判有罪(初次有罪)得上訴三審，皆對。"}, {"c": "第二審上訴審查與死亡上訴權 §361、§367、§345", "k": "要記：上訴逾期應以『裁定』駁回；未敘具體理由應以『判決』駁回；被告死亡，配偶之獨立上訴權隨訴訟主體消滅而不得再上訴。", "law": "刑訴§361(一審審查、未敘理由命補正/判決駁回)、§367、§345。", "trap": "A逾期應裁定駁回(非判決)；B未敘理由應判決駁回(非裁定)；C辯護人應以被告名義。"}, {"c": "法律人之職業特性", "k": "要記：法律座談會研究結論對法官『無拘束力』(法官依法獨立審判)。", "law": "法官/檢察官/律師之地位(獨立性、公共職務、公益代表)。", "trap": "A律師職務為公共職務、B律師有自由獨立性、D檢察官有公益代表人性質——均正確。"}, {"c": "法官不得揭露職務上非公開訊息", "k": "要記：法官不得對外揭露因職務機會所知悉之非公開訊息(縱為回應社會批評)。", "law": "法官倫理規範(不得揭露因職務知悉之非公開訊息)。", "trap": "A以『見解錯誤』為違反理由(見解非倫理問題)；C『言論自由促司法公信』；D『未記載判決書/獨立審判』——均不能正當化揭露。"}, {"c": "法官知悉律師違規之通報義務", "k": "要記：法官執行職務時知悉律師有違反律師倫理之行為→『應』通知其所屬律師公會。", "law": "法官倫理規範(知悉律師/檢察官違反倫理應通報)。", "trap": "A禮金各3千未達申報門檻且非當事人、B為配偶丁提供法律意見、D無案件繫屬時與律師友人打球——均不違反。"}, {"c": "法官受邀演講與報酬", "k": "要記：法官得收受演講費，但逾一定金額者應依司法院規定申報。", "law": "法官倫理規範(得演講、逾額應申報)。", "trap": "A『絕不得受邀演講』、B『不得受領任何報酬』、C『須與職務直接相關才合法』——均錯。"}, {"c": "法官職務監督之範圍", "k": "要記：法官會議對『對法官所為之職務監督處分』有建議權(法官自治)。", "law": "法官法(職務監督)、法官自治。", "trap": "A職務監督不及於『確保裁判正確/糾正裁判違誤』(屬審判核心)；C各級首長監督所屬，最高院長不監督高院/地院法官；D危及審判獨立應循職務法庭，非向保訓會。"}, {"c": "檢察官之社交分際", "k": "要記：未婚之檢察官與律師得自由交往、戀愛、結婚。", "law": "檢察官倫理規範(得正常社交，但不得介入個案/介紹委任)。", "trap": "A『應與律師同學斷絕往來』過嚴；B陪友拜訪律師事務所介紹委任、為友人撰意見→不當；C『下庭後三者倫理規範性質並無不同』錯(各有規範)。"}, {"c": "檢察一體與獨立行使職權", "k": "要記：檢察官對外獨立行使職權，但內部受『檢察一體』之拘束。", "law": "檢察一體、檢察官倫理規範。", "trap": "A『受部長個案指揮』錯(部長不得個案指揮)；B『不管任何人都不得干涉』忽略檢察一體；D『受法院指揮不得獨立行使』錯。"}, {"c": "檢察官懲戒與評鑑程序", "k": "要記：個案評鑑之請求/移送主體有限制，非任何受冒犯之律師都能逕行請求評鑑。", "law": "法官法/檢察官評鑑、懲戒。", "trap": "B認無評鑑事由仍得移職務監督權人命令注意、C懲戒種類含撤職免職申誡、D退休後仍得為減少退休金之懲戒——均正確。"}, {"c": "律師執行職務之違反態樣", "k": "要記：律師不得向當事人誇稱與承審法官交情深厚(暗示能影響司法)。", "law": "律師倫理規範(不得暗示能不當影響司法)。", "trap": "A代開記者會稱判決不當將上訴、C合理判斷本票偽造拒提出、D告知證人得拒絕證言之規定——均不違反。"}, {"c": "律師之真實義務", "k": "要記：律師不得教唆被告湮滅證據(縱推測偵查即將發動亦然)。", "law": "律師倫理規範(真實義務、不得湮滅證據/串證)。", "trap": "A『懷疑不實就應拒絕提出』過度(僅明知不實才拒)；B要求證人統一口徑照腳本作證；C動之以情要證人不出庭——均違反。"}, {"c": "律師倫理(未違反者)", "k": "要記：律師發覺當事人提出之證據明顯不實→應拒絕向法院提出。", "law": "律師倫理規範(真實義務、不得不當攻擊、不得擅自轉包)。", "trap": "A掌握司法貪污證據卻不揭露、B報章不附理由攻擊檢察官法官、C未得同意擅自轉包案件收介紹費——均違反。"}, {"c": "律師曾受諮詢之利益衝突", "k": "要記：律師曾為一方諮詢，不得再代理他方，除非告知原當事人並得其『書面同意』。", "law": "律師倫理規範(曾受一方諮詢之利益衝突)。", "trap": "A『未付費未委託即無衝突』、B『開庭未反對推定同意』、C『法官未反對即可』——均錯。"}, {"c": "律師對前/現任當事人之衝突", "k": "要記：對『前案已終結且無實質關聯』之原當事人得提新訴；但不得對『現任』當事人起訴。", "law": "律師倫理規範(對前案無實質關聯得為；不得對現任當事人不利；家事禁後酬)。", "trap": "B代理A向現任當事人B公司起訴、C家事(離婚)案件約後酬、D代理現case對造C告B公司——均違反。"}, {"c": "合署/合夥律師之利益衝突", "k": "要記：律師配偶任管委會主委、律師受管委會委任對違規住戶起訴→無利益衝突。", "law": "律師倫理規範(同事務所視為同一、曾任仲裁人之絕對迴避)。", "trap": "A同署所一受A告B另受B辯護、B合夥所就同一事件分受兩造、C曾任仲裁人又受A提撤銷仲裁之訴(縱同意亦不可)——均衝突。"}, {"c": "律師與事件相對人之分際", "k": "要記：律師於訴訟中提出對造不利之事證(縱令對造難堪)→屬正當攻防，不違反。", "law": "律師倫理規範(不得私見對造、不得擅自和解、正當舉證)。", "trap": "A私下聯絡已委任律師之對造B協商、B未經A授權且A反對仍逕與B和解、D明知B已不起訴確定仍發信告知B客戶其觸刑責——均違反。"}, {"c": "警察通知書 vs 傳票 §71-1", "k": "要記：警察叫人到場說明用『通知書』(無強制力)，不是『傳票』；傳票是檢察官/法院用。通知書不到，才報請檢察官核發拘票。", "law": "刑訴§71-1(警察通知書)、§71/§175(傳票)。", "trap": "A、B稱『傳票』錯；D稱可直接強制錯。"}, {"c": "GPS偵查違反強制處分法定原則", "k": "要記：GPS追蹤＝持續監看行蹤，屬干預隱私之『強制處分』，現行法無明文授權→違反『強制處分法定原則』。", "law": "強制處分法定原則(罪刑法定→強制處分法律保留)、最高法院106台上3788。", "trap": "A非搜索、B非勘驗、D非任意偵查(已干預隱私)。"}, {"c": "羈押日數折抵／羈押採自由證明", "k": "要記：自逮捕、拘禁起之日數，1日折抵有期徒刑1日(§37-2)；羈押審查採『自由證明』，不要求嚴格證明。", "law": "刑法§37-2(羈押日數折抵)、刑訴§101、自由證明。", "trap": "B羈押審查採自由證明(不要求證據能力與法定調查)；C尚須羈押『必要性』。"}, {"c": "搜索票聲請主體 §128-1", "k": "要記：偵查中『檢察官』得向法院聲請搜索票；『司法警察官』(含調查站主任)須『報請檢察官許可後』向法院聲請；政風人員無聲請權。", "law": "刑訴§128-1。", "trap": "A、B政風人員不能聲請；C調查站主任不能逕自聲請。"}, {"c": "現行犯應即解送 §92／告訴乃論", "k": "要記：逮捕現行犯應『即解送檢察官』；縱屬告訴乃論、縱告訴人撤回告訴，警方仍應解送，不能自行釋放函送(是否不起訴由檢察官定)。", "law": "刑訴§92(現行犯解送)、§238(撤回告訴)。", "trap": "A解送、B得命具保、D羈押訊問即時為之，皆對。"}, {"c": "自白排除／先前不正方法延續 §156", "k": "要記：先前警詢脅迫之效果可能延續到後續偵訊自白，不能說偵訊自白『完全不受影響』。", "law": "刑訴§156第1項(非任意性自白排除)、第3項(優先調查)、毒樹果實。", "trap": "A優先調查任意性、B檢方須證明任意性、D脅迫與自白有因果則排除，皆對。"}, {"c": "超法規補強法則之適用對象", "k": "要記：虛偽風險高、需補強者＝指證他人犯罪之『被害人、共犯、汙點/秘密證人、幼童』等；『被告之配偶』非典型須補強對象。", "law": "刑訴§156第2項(補強法則)、超法規補強(實務)。", "trap": "A被害人、C秘密證人、D目擊幼童，均須補強。"}, {"c": "另案監聽 通保法§18-1", "k": "要記：合法監聽中發現『另案』(非監察書所載罪)內容，須於『發現後7日內補行陳報法院、經法院審查認可』，才得作證據。", "law": "通訊保障及監察法§18-1第1項。", "trap": "A、B、C未掌握『7日補陳報＋法院認可』之要件。"}, {"c": "審判中強制辯護／共同辯護人利害相反 §31", "k": "要記：最輕本刑5年以上→審判中強制辯護；偵查中原則非強制辯護。甲乙利害相反→審判長不得指定『共同』辯護人。", "law": "刑訴§31(審判中強制辯護，最輕本刑3年以上)。", "trap": "A偵查中非強制辯護、B、D稱『任意辯護』皆錯。"}, {"c": "寄存送達生效 §62準用民訴§138", "k": "要記：寄存送達(寄存派出所＋黏貼通知)，本題受送達人於10日內『實際領取』→以『領取日』為送達生效日。", "law": "刑訴§62準用民訴§138(寄存送達)。", "trap": "A留置日尚未生效；C、D起算方式錯。"}, {"c": "變更起訴法條限事實同一 §300", "k": "要記：變更法條限於『起訴之犯罪事實同一』(基本社會事實同一)。", "law": "刑訴§300(變更法條)。", "trap": "A強盜→行賄、B強制猥褻→搶奪、D搶奪→贓物，事實均不同一，不得變更。"}, {"c": "一造缺席判決 §306", "k": "要記：法院認應科『拘役、罰金或諭知免刑、無罪』之案件，被告經合法傳喚無正當理由不到→得一造缺席判決。", "law": "刑訴§306(得不待被告陳述逕行判決)。", "trap": "A標準錯(非『5年以下』)；C公示送達合法傳喚有效；D『不得審判』錯。"}, {"c": "第三審得調查訴訟程序事項 §394", "k": "要記：鑑定人是否具鑑定資格＝訴訟程序事項→第三審得調查事實。", "law": "刑訴§394(第三審以二審認定事實為基礎，但訴訟程序及得依職權調查事項得調查)。", "trap": "A、B誤認一律不得；C誤認一律應依職權。"}, {"c": "回復原狀期間一律10日 §67", "k": "要記：非因過失遲誤上訴、抗告、再審等期間者，於『原因消滅後10日內』聲請回復原狀(一律10日)。", "law": "刑訴§67(回復原狀)。", "trap": "A上訴寫20日、C寫15日皆錯(都是10日)；D告訴期間不適用回復原狀。"}, {"c": "送達代收人／在途期間 §55、§66", "k": "要記：向送達代收人送達者，上訴期間自『代收人收受時』起算；在途期間按『被告住居所』與法院距離計算，應扣除。", "law": "刑訴§55(送達代收人)、§66(在途期間)。", "trap": "C、D以『實際轉交被告日』起算錯。"}, {"c": "另案扣押 §152", "k": "要記：依法搜索時，發現『另案應扣押之物』(偽造證件、來源不明提款卡)，得逕行扣押，不限搜索票記載範圍、不限同一案件。", "law": "刑訴§152(另案扣押)。", "trap": "A、C、D誤認非同一案件/非票載範圍不得扣。"}, {"c": "機關鑑定之證據能力 §198、§208", "k": "要記：須『檢察官或法官選任/囑託(含檢察長事前概括選任之機關)』之鑑定才有證據能力。①刑事警察局(檢察長概括選任)、③檢察官偵查中囑託機關→有；②調查人員自行囑託、④檢察官在『審判中』自行囑託(審判中鑑定權在法院)→無。", "law": "刑訴§198、§208(機關鑑定)、§163-1。", "trap": ""}, {"c": "偵查不公開之規範對象 §245Ⅲ", "k": "要記：偵查不公開拘束『檢察官、檢事官、司法警察(官)、辯護人、告訴代理人及其他執行職務之人』；『被告本人』就自己涉案部分不是規範對象。", "law": "刑訴§245第3項。", "trap": "A『任何人皆不得』太廣；C、D理由錯。"}, {"c": "撤回告訴後不得再自訴 §325、§238", "k": "要記：告訴乃論之罪可自訴也可告訴；但一旦『撤回告訴(或自訴)，即不得再行告訴或自訴』。", "law": "刑訴§319(自訴)、§238(撤回告訴)、§325(撤回自訴)。", "trap": "A傷害(告訴乃論)亦可自訴；B、D方向錯。"}, {"c": "職權再議／緩起訴範圍 §256、§253-1", "k": "要記：『不另為不起訴處分』非獨立處分，毋庸送職權再議；緩起訴限『死刑、無期或最輕本刑3年以上以外』之罪(重罪不得緩起訴)。", "law": "刑訴§256Ⅲ(職權再議)、§253-1(緩起訴範圍)、§178。", "trap": "C最輕本刑3年以上不得緩起訴；D檢察官不能逕裁罰鍰(屬法院§178)。"}, {"c": "協商不受理情形不得協商 §455-2、§455-4", "k": "要記：有應諭知不受理(如告訴乃論逾告訴期間)之情形→不得為協商判決；死刑/無期/最輕本刑3年以上之罪不得協商；協商判決原則不得上訴。", "law": "刑訴§455-2、§455-4(不得協商情形)、§455-10。", "trap": "A協商不得逸脫起訴事實；C協商判決不得以量刑過輕上訴；D重罪不得協商。"}, {"c": "無罪判決毋庸變更法條 §300、§301", "k": "要記：變更起訴法條僅於『有罪』判決且事實同一時為之；認定無罪者，毋庸變更法條，逕為無罪判決。", "law": "刑訴§300(變更法條限有罪)、§301(無罪判決)。", "trap": "B變更後再無罪屬多餘；C毋須曉諭追加；D非起訴程序違背。"}, {"c": "協商判決不得上訴第三審 §455-10、§455-11", "k": "要記：協商判決原則一審確定不得上訴；例外(§455-4各款違法)僅得上訴『第二審』，不得上訴第三審。", "law": "刑訴§455-10(協商判決原則不得上訴)、§455-11、§455-4。", "trap": "A原則確定、B二審有理由撤銷發回一審、D有較重裁判上一罪不得協商，皆對。"}, {"c": "物證調查方法 §164", "k": "要記：物證『同一性有爭議』時，應『提示原物』使當事人辨認，不能只用扣押筆錄、照片(書證)替代。", "law": "刑訴§164(證物應提示辨認；文書宣讀或告以要旨)。", "trap": "A、B同一性無爭議得僅提示筆錄照片；D有爭議應提示原物，皆對。"}, {"c": "一審調查瑕疵得於二審補正治癒", "k": "要記：『調查證據程序之瑕疵』(如未告知書證要旨)得因二審補行而治癒；但『審判組織違法』(應合議卻獨任)、『無管轄權』屬本質瑕疵，不能治癒。", "law": "刑訴§364(二審準用一審)、覆審制。", "trap": "B漏提物證亦可二審補正；C獨任判決不能治癒；D無管轄不能因追加補正。"}, {"c": "律師專業倫理與一般倫理之關係", "k": "要記：違反『專業』倫理可能經懲戒喪失執業資格；單純違反一般倫理而未違法則否。", "law": "律師法、律師倫理規範(專業倫理由懲戒程序認定)。", "trap": "A違反專業倫理須經特定機構程序(懲戒)認定；B律師仍須遵守一般倫理；D尊重其他律師也是專業倫理之內容。"}, {"c": "法官評議獨立與關說之通報", "k": "要記：法官知悉有人向承審法官關說請託→應通知相關職務監督權人。", "law": "法官倫理規範(評議獨立、知悉關說應通報)。", "trap": "A見解不同非迴避事由；B審判長不得要求他法官配合特定結論；D不得因見解不同拒寫判決書。"}, {"c": "評論繫屬中案件之限制", "k": "要記：承審法官對繫屬案件之評論受限，連『配屬之書記官』亦受限。", "law": "法官/檢察官倫理規範(不得評論繫屬案件)。", "trap": "A檢察官起訴後不得利用輿論要求重刑；B其他法官非『不受限制』；C在法官論壇預先說明心證求集思廣益亦違反。"}, {"c": "法官政治中立", "k": "要記：法官得單純『聆聽』政見；不得連署、公開支持、募款、徵求同事連署。", "law": "法官倫理規範(政治中立、不得助選募款)。", "trap": "B辦公室徵求同事連署罷免；C參與連署並公開支持；D為候選人募款——均違政治中立。"}, {"c": "法官不得不當勸諭和解", "k": "要記：法官不得以恫嚇(否則判更多)方式逼當事人和解。", "law": "法官倫理規範(不得以不當方式逼和解)。", "trap": "A『避免訟累』、B『單造上訴訴訟經濟』、C『兩造上訴心證公開』——以恫嚇方式逼和解均違反。"}, {"c": "檢察官職權行使與旋轉門", "k": "要記：檢察官依職權調查(送鑑定覆議)是正當職權；離職轉律師後一定期間不得在原任職地檢署執業。", "law": "檢察官倫理規範、律師法(旋轉門：離職後一定期間不得在原任職機關執業)。", "trap": "A受贈3萬禮券未申報；B辭檢後於原A地檢署執業(旋轉門)；D仍任檢時上節目評論繫屬案件——均違反。"}, {"c": "檢察官受指派演講之分際", "k": "要記：經機關指派、不涉所偵辦個案，檢察官得主講並領車馬費；涉個案應簽請改派。", "law": "檢察官倫理規範(不涉個案得受指派演講)。", "trap": "B不涉個案可主講、C可領車馬費、D涉個案應簽請改派——均正確。"}, {"c": "檢察官應交付個案評鑑之情形", "k": "要記：起訴與法院認定罪名不同(殺人未遂vs重傷害)屬『法律見解歧異』，非應評鑑事由。", "law": "法官法/檢察官評鑑(個案評鑑事由)。", "trap": "A留停參選立委(未依規辭職)、C兼母校董事要求學校配合、D酒後鬧事經報導損形象——均屬應評鑑之違失。"}, {"c": "律師對勝訴之誠實說明", "k": "要記：縱裁判學說都有利，仍應說明勝負因素很多、應謹慎。", "law": "律師倫理規範(不得保證勝訴、不得以勝訴率招攬)。", "trap": "A打包票保證百分百勝訴；B隱瞞有利見解以留客；D以自己勝訴率宣傳——均不當。"}, {"c": "律師不得使證人不出庭", "k": "要記：律師不得為幫助當事人而促使已受傳喚之證人不出庭作證。", "law": "律師倫理規範(不得妨礙證人作證)。", "trap": "A『忠實義務任何律師都該做』、B『切結同意就可』、D『聽從當事人指示』——均錯。"}, {"c": "律師揭發法官不當言行", "k": "要記：法官開庭有不當言行(辱罵律師)，律師揭發該情事→不違反。", "law": "律師倫理規範(得揭發法官違反行為規範之情事)。", "trap": "A『開庭內容不公開』(此係法官不當行為非案情)、C『須全案終結才能揭發』、D『只能秘密向院長/公會』——均過度限制。"}, {"c": "律師利益衝突(實質關聯)", "k": "要記：兩通姦賠償事件有實質關聯、利害及角色可能衝突→甲同時代理A及B違反。", "law": "律師倫理規範(實質關聯事件之利益衝突)。", "trap": "A『夫妻絕對不可共用律師』理由過絕對；C『取得B口頭同意即可』(實質衝突不得同意排除)；D『複委任受僱律師即可』——均錯。"}, {"c": "第三人代付律師費", "k": "要記：由第三人代付律師費，須不影響律師之獨立專業判斷。", "law": "律師倫理規範(第三人付費不得影響獨立判斷)。", "trap": "A『絕不能由第三人代付』過絕對；C『絕不可A直接付』；D『以是否開發票區分』——均錯。"}, {"c": "律師對顧問公司之保密義務", "k": "要記：律師因職務知悉當事人(公司)之機密計畫→負保密義務，不得洩露或自用。", "law": "律師倫理規範(保密義務)。", "trap": "A『同學情誼有義務告知』、B『基於良心應揭露』(此非防止犯罪)、D『乙委託買賣才可』——均違保密。"}, {"c": "受僱律師離職之交接義務", "k": "要記：受僱律師離職應主動告知當事人並將案件交接給原事務所，不得拉走當事人。", "law": "律師倫理規範(離職應交接、不得拉走當事人)。", "trap": "A『毋需再委任X、直接聯絡我』、C『已離職不關我事』(未交接)、D『造冊寄邀請函邀轉委任』——均違反。"}, {"c": "卷證獲知 §33、§271-1、§38準用", "k": "要記：辯護人得檢閱、抄錄、重製、攝影卷證(§33Ⅰ)；無辯護人之被告本人只能『預納費用請求付與影本』(§33Ⅱ)，不得自行檢閱原卷攝影。各種代理人(自訴/告訴/被告之代理人)準用辯護人之權。", "law": "刑訴§33(被告/辯護人)、§271-1(告訴代理人)、§38準用(自訴/代理人)。", "trap": "A被告『本人』不得逕行檢閱攝影；B被告代理人、C告訴代理人均『得』檢閱(說不得是錯)。"}, {"c": "強制辯護／指定辯護 §31、§31-1", "k": "要記：偵查中『詢問時應通知法扶指派律師』的只有『原住民、身心障礙致無法完全陳述』(§31Ⅴ)；低收入戶之強制辯護是『審判中』且須『聲請』，偵查中沒有。", "law": "刑訴§31(審判中強制辯護)、§31第5項(偵查中通知法扶)、§31-1(羈押審查強制辯護)。", "trap": "B原住民、C身心障礙偵查中應通知法扶(§31Ⅴ)；D聲請羈押屬強制辯護(§31-1)，皆對。"}, {"c": "司法警察通知書 §71-1", "k": "要記：通知書『無直接強制力』，到場與否自由、到場後得隨時離去；經合法通知無正當理由不到，才『報請檢察官核發拘票』，通知書本身不能像拘票記載『不到即拘提』。", "law": "刑訴§71-1(通知書)、§95(告知義務)。", "trap": "B急迫時電話/登門告知案由請到場合法；C無強制效果、得自由離去；D縱身心未受拘束仍應踐行§95告知，皆對。"}, {"c": "拘提要件 §79、§81、§88-1", "k": "要記：§88-1①逕行拘提是『因現行犯之供述』且共犯嫌疑重大、情況急迫；不是『線民供述』。", "law": "刑訴§79(拘票二聯)、§81(域外執行)、§88-1(逕行拘提)。", "trap": "A拘票二聯交被告/家屬、B非必要不得域外執行、D得限制執行期間，皆對。"}, {"c": "現行犯／準現行犯 §88", "k": "要記：現行犯＝犯罪實施中或實施後『即時發覺』；準現行犯＝被追呼為犯罪人，或持有兇器贓物顯可疑(§88Ⅲ)。教唆犯事後被指認，兩者都不該當。", "law": "刑訴§88。", "trap": "A教唆犯非現行犯；B被指認不符準現行犯；C告訴乃論之現行犯仍可逮捕(只是訴追要告訴)。"}, {"c": "偵查中羈押審查 §101、§31-1、§33-1", "k": "要記：羈押＝①犯罪嫌疑重大＋②羈押事由(逃亡/滅證/重罪)＋③羈押必要性，缺一不可，不能只憑罪嫌重大。", "law": "刑訴§101(羈押要件)、§31-1(羈押審查強制辯護)、§33-1(限制卷證獲知)。", "trap": "A只憑罪嫌重大即羈押→欠事由與必要性；C檢察官『得』到場非『應』；D羈押審查屬強制辯護，辯護人應在場。"}, {"c": "附帶搜索的範圍 §130", "k": "要記（背範圍）：逮捕拘提羈押時，得搜索『身體、隨身物件、所使用之交通工具、及立即可觸及之處所』。核心限制＝『現場性＋立即可觸及』。", "law": "刑訴§130(附帶搜索)。", "trap": "A、B只看到『交通工具』卻忽略『立即可觸及』；D理由錯(通緝犯逮捕亦得附帶搜索)。"}, {"c": "絕對排除 vs §158-4權衡", "k": "要記：違反『請求辯護人到場前不得詢問』『夜間詢問』等§95、§100-3者→§158-2『絕對排除』，不經權衡；其餘違背法定程序才用§158-4權衡。", "law": "刑訴§158-2(絕對排除)、§158-4(相對／權衡排除)。", "trap": "A違反拒絕證言告知、B身心未受拘束違反§95、D違法未通知到場勘驗，皆走§158-4權衡。"}, {"c": "傳聞法則：非供述內容用途 §159", "k": "要記：傳聞＝『審判外』陳述，且用來證明『陳述內容為真』。若是證人在『審判中』作證，或該言詞本身就是待證事實(言語行為，如脅迫的話)，則非傳聞。", "law": "刑訴§159(傳聞法則)。", "trap": "A、B、C都是用審判外陳述證明其內容真實，屬傳聞。"}, {"c": "自白任意性應依職權調查 §156Ⅲ、§163Ⅱ", "k": "要記：被告抗辯自白係刑求(任意性爭執)＝對被告利益有重大關係事項，法院『應依職權調查』，且不生失權效。", "law": "刑訴§156第3項、§163第2項但書。", "trap": "A自白任意性無失權效；C任意性非僅檢方舉證，法院應依職權調查；D不得延後到別的證據之後。"}, {"c": "先前不符陳述 §159-2／具結 §158-3", "k": "要記：§159-2要件＝① 與審判中陳述『不符』② 具『較可信之特別情況』③ 為『證明犯罪事實所必要』。警詢證人本不適用具結(§158-3只規範向法官/檢察官作證)。", "law": "刑訴§159-2(審判外不符陳述之傳聞例外)、§158-3(應具結而未具結)。", "trap": "A警詢證人不須具結；B乙為前未婚妻非配偶親屬、無拒絕證言權，不告知不影響。"}, {"c": "准許提起自訴(原交付審判) §258-1", "k": "要記：再議駁回後，告訴人得於『10日內、委任律師』、向『該管第一審法院』聲請『准許提起自訴』。", "law": "刑訴§258-1(112年修正：交付審判→准許提起自訴)。", "trap": "A不得直接提自訴(須經准許)；C仍有救濟管道；D不起訴非行政處分，不能訴願。"}, {"c": "限制辯護人接見通信 §34、§34-1", "k": "要記：限制/禁止辯護人與羈押被告接見通信，須向『法院』聲請核發『限制書』；偵查中急迫時檢察官得先為必要處分，並應於『24小時內』聲請法院補發。", "law": "刑訴§34、§34-1(限制書由法院核發)。", "trap": "A檢察官無逕行強制權；C不是『3日內』是24小時；D『一律不可』太絕對。"}, {"c": "撤回自訴限於告訴乃論 §325", "k": "要記：只有『告訴乃論之罪』，自訴人才得於第一審辯論終結前撤回自訴；非告訴乃論之罪不得撤回。", "law": "刑訴§325(自訴之撤回)。", "trap": "A、B誤認撤回合法；D處理方式錯。"}, {"c": "已開始偵查不得自訴 §323", "k": "要記：檢察官『簽准分案、命檢察事務官進行案情分析及擬定偵查策略』＝已『開始偵查』，此後被害人不得再提自訴(加工自殺非告訴乃論，無但書例外)。", "law": "刑訴§323第1項(同一案件經檢察官開始偵查者不得再自訴)。", "trap": "A丙為配偶得自訴(§319)，問題在已偵查；C理由不對；D已開始偵查(非尚未)。"}, {"c": "緩起訴負擔須被告同意 §253-2", "k": "要記：命被告履行第3款～第6款負擔(道歉、悔過書、支付公庫/公益款、損害賠償、義務勞務等)『應得被告之同意』(§253-2Ⅱ)。", "law": "刑訴§253-2(緩起訴處分之負擔)、§260(確定力)。", "trap": "B向被害人道歉須得『被告』同意(不是被害人)；C期滿未撤銷有限度確定力；D已處分不得自訴。"}, {"c": "國民法官評議特別多數 §83", "k": "要記（背）：有罪認定須達『三分之二以上』(9人中6票)，且該多數須『同時包含國民法官與法官』雙方意見。", "law": "國民法官法§83。", "trap": "B非一致決(是三分之二)；C、D未達門檻不能作有罪。"}, {"c": "被告不到庭得否逕行審判 §281、§294、§306", "k": "要記：原則被告不到庭不得審判；例外可逕行判決者＝心神喪失/疾病而顯應無罪免刑(§294Ⅲ)、應科拘役罰金或免刑無罪之合法傳喚不到(§306)、得由代理人到庭之輕罪(§36)。", "law": "刑訴§281(被告不到庭不得審判)、§294、§306、§273-1(簡式須有罪陳述)。", "trap": "A、C、D均屬法律明定得不待被告到庭逕行判決之例外。"}, {"c": "管轄錯誤判決不移送 §335、§304", "k": "要記：『自訴』案件諭知管轄錯誤，非經自訴人聲明『毋庸移送』管轄法院；只有『公訴』才併諭知移送。", "law": "刑訴§335(自訴管轄錯誤毋庸移送)、§304(公訴管轄錯誤移送)、§307(得不經言詞辯論)。", "trap": "A通姦除罪→免訴(§302②)；B無我國刑法適用→不受理；D形式判決得不經言詞辯論(§307)，皆對。"}, {"c": "受命法官準備程序權限 §279、§273", "k": "要記：受命法官只能做『爭點整理、證據能力意見之聽取、得為一定證據調查(如勘驗)』；但『證據能力有無之裁定』屬合議庭權限，受命法官不得逕為。", "law": "刑訴§279(受命法官準備程序)、§273(準備程序事項)。", "trap": "A詢問起訴範圍/變更法條、B勘驗自白光碟、D對到庭之人行準備程序，皆屬受命法官得為。"}, {"c": "預料證人不能到庭→審判期日前訊問 §276", "k": "要記：法院預料證人不能於審判期日到場者，得於『審判期日前』先行訊問，並『應通知當事人到場、行交互詰問』(保障詰問權)。", "law": "刑訴§276。", "trap": "A不應駁回；B不得不待當事人到場逕訊；C不得逕以偵查筆錄替代。"}, {"c": "上訴範圍可分 §348(110修正)", "k": "要記：修法後上訴得對一部為之；被告僅就『有罪部分』上訴、檢察官未上訴，上訴範圍『不及於』不另為無罪諭知部分(不再一律不可分)。", "law": "刑訴§348(110年修正，上訴範圍)。", "trap": "A第三審上訴受理由限制；C、D仍套舊『審判/上訴不可分』，修法後不採。"}, {"c": "第三審上訴未敘理由→逕送最高法院 §382、§395", "k": "要記：『第三審』上訴未敘理由，原審(二審)『毋庸命補正』，逕送最高法院，由第三審處理；只有『第二審』上訴未敘理由才命補正。", "law": "刑訴§382(第三審上訴須敘理由)、§395(第三審得判決駁回)；對照§361(第二審補正)。", "trap": "A、B誤套第二審之命補正程序；C二審不能逕以判決駁回第三審上訴。"}, {"c": "非常上訴對象＝確定的實體判決 §441", "k": "要記：非常上訴對象是『審判違背法令的確定判決』。第三審若以『上訴違背程式』程序駁回(未進入實體)，真正的實體確定判決是『第二審』。", "law": "刑訴§441(非常上訴)、§447、§444(不經言詞辯論)。", "trap": "A三審是程序判決非實體；C見解變更非當然違背法令；D非常上訴不經言詞辯論、無強制辯護。"}, {"c": "法律人共通專業倫理", "k": "要記：律師曾為租約雙方之見證人，嗣後受一方對他方起訴→須得他方同意(利益衝突)。", "law": "法官/檢察官/律師倫理規範(政治中立、偵查不公開、利益衝突、在職進修)。", "trap": "A法官政治中立、B檢察官經授權得就案情必要說明、D三者均負在職進修義務——均正確。"}, {"c": "法官審判獨立與不當聯繫", "k": "要記：法官當庭致電另一法官、逕依其心證作和解基礎→生審判獨立性疑慮，違反。", "law": "法官倫理規範(審判獨立、不得使當事人生疑慮)。", "trap": "A『配偶分別承辦即當然迴避』錯；C/D『用心良苦/便民』非阻卻違反之理由。"}, {"c": "法官兼課之分際", "k": "要記：法官不得對具體個案提供法律意見或訴訟策略，縱在授課場合亦然。", "law": "法官倫理規範(不得對個案提供法律意見/訴訟策略)。", "trap": "A學術上批評確定判決見解、B被學生標註身分(非主動)、D商請出版社優惠售教材——尚不違反。"}, {"c": "法官不得利用身分處理私事", "k": "要記：法官不得表明法官身分、利用辦公處所處理私人事務。", "law": "法官倫理規範(不得利用職務身分/辦公處所圖私利)。", "trap": "A『下班時間』、B『獲乙授權』、D『行使法定權利』——均不能正當化利用身分施壓。"}, {"c": "法院首長職務監督之界限", "k": "要記：職務監督限制止違法、糾正不當言行、督促迅速；不得干預審判核心。", "law": "法官法(職務監督)、審判獨立。", "trap": "A制止違法、B糾正不當言行、C督促迅速執行——均屬職務監督樣態。"}, {"c": "檢察官社交與利益迴避", "k": "要記：檢察官明知同桌者為自己承辦案件之被告，仍續用餐至結束→應主動避嫌。", "law": "檢察官倫理規範(避免與承辦案件關係人不當往來)。", "trap": "A致送開幕花籃、B包禮金3000元、C同任公共工程申訴委員——均屬正常往來/職務，不違反。"}, {"c": "檢察官外勤用餐之分際", "k": "要記：外勤逾用餐時間，檢察官應『自費』，不得接受轄區警方或相驗家屬招待。", "law": "檢察官倫理規範(不得接受利害關係人招待)。", "trap": "A接受轄區警招待、C請警招待同仁、D接受相驗家屬付費訂餐——均屬不當招待。"}, {"c": "檢察官懲戒之原則", "k": "要記：同一行為不受二次懲戒(一事不再理)；但懲戒與刑罰/行政罰得併存。", "law": "檢察官倫理規範、法官法(懲戒、評鑑)。", "trap": "B已受刑罰/行政罰仍得懲戒；C檢察官懲戒亦由懲戒法院職務法庭審理；D『不分輕重均付評鑑』過絕對(視情節)。"}, {"c": "卷證屬當事人之權利", "k": "要記：卷證屬當事人，當事人要求時律師應將卷宗內資料影印交付。", "law": "律師倫理規範(當事人對卷證之知悉/取得權)。", "trap": "A『須訴訟終結後』、B/D『對造狀紙、法院筆錄須他人同意』——均不當限制當事人取得卷證。"}, {"c": "律師利益衝突之認定", "k": "要記：前案終結後，受任『與前案無實質關聯』之新案件對抗原當事人→不違反。", "law": "律師倫理規範(現任/曾任當事人之利益衝突)。", "trap": "B就同一離婚協議見證後對A起訴、C曾為A出意見再代理B反對A、D允許同事務所受同一案件對造委任——均利益衝突。"}, {"c": "律師保密義務之例外(防止犯罪)", "k": "要記：為防止當事人犯罪致他人生命身體財產『重大損害』，律師得例外揭露其秘密。", "law": "律師倫理規範(保密義務及其例外)。", "trap": "B『絕對不可洩漏』過絕對；C『財產損害不算』錯；D『卸任才可』錯(依據是防止犯罪，非有無顧問身分)。"}, {"c": "曾任仲裁人之絕對迴避", "k": "要記：曾任某案仲裁人者，不得於撤銷該仲裁判斷之訴訟中任一造代理人——縱經兩造同意亦不得。", "law": "律師倫理規範(曾參與事件之絕對迴避)。", "trap": "A『熟悉案情可受任』、C『A聘任即認可衝突』——忽略此為不得同意排除之絕對迴避；D理由不正確。"}, {"c": "律師不得私見對造當事人", "k": "要記：律師明知對造已委任律師，不得私下會見對造當事人。", "law": "律師倫理規範(不得私見已委任律師之對造當事人；合夥人之監督)。", "trap": "A『有助勝訴即不違反』、B『受僱律師行為不影響』、D『甲不得通知公會』——均錯。"}, {"c": "受僱律師離職不得拉走當事人", "k": "要記：受僱律師離職時，不得促使原事務所當事人轉委任自己。", "law": "律師倫理規範(離職不得促使當事人轉委任自己)。", "trap": "B『各憑本事可促轉委任』、C『只有自己懂就可』、D『新事務所同意就可』——均不能正當化拉走當事人。"}, {"c": "相牽連案件 §7／追加起訴 §265", "k": "§7 四種相牽連（背）：①一人犯數罪 ②數人共犯一罪或數罪 ③數人同時同地各別犯罪 ④犯與本罪有關係之『藏匿人犯、湮滅證據、偽證、贓物』各罪。", "law": "刑訴§7（相牽連案件）、§265（追加起訴）", "trap": "A=一人犯數罪(§7①)、B=數人共犯一罪(§7②)、D=行賄收賄對向犯相牽連，皆對。"}, {"c": "法官自行迴避 §17⑧『曾參與前審』", "k": "要記：『前審』＝曾參與『被再審／非常上訴所審查的那個確定判決』的法官，於再審後重新審判時要迴避；更審(同級)、沒參與到原確定判決的，不迴避。", "law": "刑訴§17第8款（曾參與前審之裁判應自行迴避）、釋字178號。", "trap": "A更審非前審；B、C甲參與的審級都不是被救濟的那個確定判決，故不迴避。"}, {"c": "第三人參與沒收程序 §455-12以下", "k": "沒收特別程序較簡化、為附隨程序。", "law": "刑訴§455-12～§455-37（第三人沒收參與程序）。", "trap": "B簡易/協商也可沒收第三人財產；C審理中發現仍得追加聲請沒收(不是不得)；D參與人合法傳喚不到庭，得不待其到庭逕行判決(不是不得)。"}, {"c": "同意搜索 §131-1／證據排除 §158-4", "k": "同意搜索合法要件（背）：① 出於受搜索人『自願性』(不能被騙被逼) ② 搜索人員應將『同意之意旨記載於筆錄』。不需搜索票、不需事後陳報法院。", "law": "刑訴§131-1（同意搜索）、§158-4（權衡排除）。", "trap": "A沒律師陪同≠不合法；B不需向法院陳報；D搜索中得隨時撤回同意，撤回後不得續搜。"}, {"c": "通緝 §84～§87", "k": "要記：通緝書『偵查中由檢察長、審判中由法院院長』簽名核發(§85)；通緝經通知或公告後，檢察官、司法警察官得拘提或逕行逮捕(§87)。", "law": "刑訴§84-87。", "trap": "A非『向法院聲請』、要件須逃亡或藏匿；B非一律由法院、偵查中是檢察長；C通緝書應記載被訴事實等，不是不記載。"}, {"c": "被告在場權／勘驗 §150、§169、§305、§371", "k": "要記：勘驗應由『法院在審判期日』行之、被告有在場權；受命法官私下勘驗、僅事後提示筆錄，違反直接審理與在場權。", "law": "勘驗被告在場權§150、命被告退庭§169、§305、二審§371。", "trap": "A被告無故離庭得逕行判決(§305)；C二審被告不到庭得逕判(§371)；D證人因被告在場不能自由陳述，聽取意見後得命被告退庭(§169)，皆合法。"}, {"c": "逕行拘提 §88-1（四款要記）", "k": "四款（背）：①因現行犯之供述且有事實足認共犯嫌疑重大 ②在執行或在押中脫逃 ③犯罪嫌疑重大經盤查而逃逸（但所犯最重本刑1年以下/拘役/專科罰金者除外）④所犯死刑、無期或最輕本刑5年以上之罪，有事實足認有逃亡之虞。", "law": "刑訴§88-1第1項。", "trap": "B=①、C=④、D=另案通緝犯得逕行逮捕，皆得拘提。"}, {"c": "逮捕現行犯 §88／附帶搜索 §130", "k": "要記：任何人都可逮捕現行犯，但逮捕後應『即送交檢察官、司法警察官或司法警察』(§88第1項)，不是送交法院。", "law": "刑訴§88（現行犯逮捕）、§90（強制力）、§130（附帶搜索）。", "trap": "A強制力不得逾必要程度(§90)；C逮捕得附帶搜索身體(§130)；D應告知逮捕原因，皆對。"}, {"c": "夜間詢問 §100-3／辯護人到場 §158-2", "k": "要記：§100-3只限制『司法警察(官)詢問』不得於夜間為之(例外:明示同意、急迫等)；『檢察官訊問』不受夜間限制。請求辯護人到場者，到場前所為詢問之自白原則上不得為證據。", "law": "刑訴§100-3（夜間不得詢問，限司法警察）、§95＋§158-2（請求辯護人到場前訊問所得自白排除）。", "trap": "A、C檢察官夜間訊問不受限；B經甲同意之夜間詢問合法，皆可採。"}, {"c": "逮捕前置主義／偵查中聲請羈押 §93", "k": "要記：偵查中聲請羈押『以被告處於拘提或逮捕之狀態為前提』。對『傳喚到庭』非拘捕之被告，不能逕行聲請羈押，須先逮捕。", "law": "刑訴§93第2項（拘捕後24小時內聲請羈押）、逮捕前置主義。", "trap": "A逕予釋放、B諭知具保責付、D先逮捕告知後再聲請羈押，皆合法。"}, {"c": "偵訊錄音與筆錄不符 §100-1精神／§159-1", "k": "要記：偵訊應全程錄音；筆錄記載與錄音『不符之部分』，該不符部分不得作為證據。", "law": "刑訴§100-1（全程錄音、筆錄與錄音不符部分不得為證據）、證人偵訊§159-1第2項。", "trap": "A檢察官偵訊本應錄音(非不得)；C由檢察官製作不影響證據能力；D不必逐字記載(最高法院110台上2915)。"}, {"c": "誘導詰問 §166-1、§166-2", "k": "要記：主詰問『原則禁止』誘導，例外可（§166-1③各款：無爭執事項、喚起記憶、敵性證人、規避事項、先前不符陳述等）；反詰問『得』誘導。", "law": "刑訴§166-1（主詰問原則不得誘導、例外得）、§166-2（反詰問得誘導）。", "trap": "A、B屬主詰問得誘導之例外；C反詰問必要時得誘導，皆對。"}, {"c": "緊急拘提共犯 §88-1①", "k": "要記：因現行犯之供述、且有事實足認共犯嫌疑重大、情況急迫→司法警察得『先逕行拘提，再即報請檢察官簽發拘票』。", "law": "刑訴§88-1第1項第1款、第2項。", "trap": "A緊急不必先傳喚；C司法警察也能(非僅檢察官)；D緊急逕行拘提不必先有拘票。"}, {"c": "共犯自白補強 §156Ⅱ／傳聞 §159-2", "k": "要記：共犯不利於被告之陳述仍須『補強證據』，不得單憑共犯證述定罪；補強須是『該陳述以外』的獨立證據（通聯紀錄等非供述證據可當補強）。", "law": "刑訴§156第2項（自白／共犯陳述須補強）、§159-2（不一致先前陳述之傳聞例外）。", "trap": "A§159-2須具『較可信特別情況＋必要性』非當然有證據能力；B不能僅憑共犯證述認定(欠補強)；C戊轉述甲的話仍源自甲陳述，不能當補強。"}, {"c": "起訴審查／職權調查 §161、§163", "k": "要記：法院認檢察官證明方法顯不足→應先『以裁定定期通知補正』，逾期未補正才得駁回起訴，不能直接駁回。", "law": "刑訴§161第2項（起訴審查、定期通知補正）、§163（職權調查）、§163-2（駁回不必要證據）。", "trap": "B§161-2、C§163Ⅱ但書應依職權調查、D§163-2得駁回不必要證據，皆對。"}, {"c": "告訴主觀不可分 §239／非常上訴 §441", "k": "要記：撤回對乙之告訴→效力及於共犯甲→甲也欠缺告訴(訴追條件)，法院本應諭知不受理；竟判有罪確定＝『適用法令違誤』→用『非常上訴』救濟(不是再審)。", "law": "刑訴§239（對共犯一人撤回告訴，效力及於其他共犯）、§303⑤(不受理)、§441(非常上訴)。", "trap": "C用再審錯(再審救濟事實認定錯誤)；A、B方向錯。"}, {"c": "獨立告訴權 §233／告訴期間 §237", "k": "要記：配偶『獨立告訴權』不受被害人意思拘束、不能被被害人撤回；其告訴期間自『該告訴權人自己知悉犯人時』各別起算。", "law": "刑訴§233第1項（被害人之法定代理人或配偶得獨立告訴）、§237（6個月告訴期間，自知悉犯人起算）。", "trap": "A甲期間屆滿不影響丙(各別起算)；C甲不能撤回丙之告訴；D獨立告訴不受被害人明示意思相反之影響。"}, {"c": "告訴乃論數被害人各別／自訴 §319", "k": "要記：一行為侵害數被害人(乙、丙)，告訴/自訴『各別』、互不影響。乙撤回告訴使『傷乙』部分不起訴，與『傷丙』非同一案件，丙仍得於告訴期間內就傷丙『提自訴』。", "law": "刑訴§252⑤(撤回告訴不起訴)、§319(自訴)。", "trap": "其餘誤以為受乙部分不起訴拘束。"}, {"c": "國民法官法 vs 一般程序", "k": "要記：國民法官案件採『起訴狀一本主義』不併送卷證；一般程序起訴併送卷證(§264)。", "law": "國民法官法§43(起訴狀一本)、§47(準備程序)、§310(判決理由)。", "trap": "A起訴卷證、C證據提示主體、D判決書記載繁簡，皆正確區分。"}, {"c": "簡式審判程序 §273-1", "k": "要記：被告主張阻卻違法／阻卻罪責(如精神障礙無責任能力)＝『非有罪陳述』→不得行簡式審判程序。", "law": "刑訴§273-1（簡式審判以被告『就被訴事實為有罪之陳述』為前提）。", "trap": "A、B誤認可行簡式；C方向錯。"}, {"c": "國民法官選任 §26以下", "k": "要記：『不附理由拒卻權』每造『固定次數(各4人)』，不隨起訴罪名輕重增減；附理由拒卻無次數限制。", "law": "國民法官法選任程序（不附理由拒卻、附理由拒卻）。", "trap": "A選任不公開、C附理由拒卻無次數限制、D候選不足應重新選任，皆對。"}, {"c": "搜索票／第三人搜索 §122、§128", "k": "要記：對被告之身體物件處所『必要時得搜索』(§122Ⅰ)；對第三人，於『有相當理由可信』應扣押物或被告在其內時，亦得搜索(§122Ⅱ)——第三人之『身體』也包含在內。", "law": "刑訴§122（對被告及第三人之搜索要件）、§128/§128-1（搜索票聲請核發）。", "trap": "A書面聲請交司法警察執行、B對被告辦公室、C對第三人研究室，皆對。"}, {"c": "自訴強制律師代理 §37、§319Ⅱ", "k": "要記：自訴(含上訴審)『未委任律師代理』即程序不合法；經命補正逾期不補→第二審應撤銷原判決，改判『不受理』。", "law": "刑訴§37、§319第2項（自訴應委任律師為代理人，強制律師代理）。", "trap": "B§332(承受訴訟/檢察官擔當)與此無關；A、D誤認可實體判決。"}, {"c": "裁判上一罪不可分／再審管轄 §426、抗告 §403", "k": "要記：想像競合(裁判上一罪)是『一個訴訟客體、不可分』，竊盜與強制屬同一確定判決。再審向『為判決之原審法院(二審高院)』聲請；駁回再審之裁定得抗告，且不可分→兩罪部分均得抗告。", "law": "刑訴§426（再審向原審法院聲請）、§403（裁定抗告）。", "trap": "A應向高院非地院；B、C誤把一罪拆開處理。"}, {"c": "協商程序 §455-2", "k": "要記：協商『僅檢察官得聲請』(經被告同意)；聲請前『徵詢被害人意見』即可，『不以取得被害人同意為要件』；但協商內容若涉『向被害人道歉、支付賠償金』(第2項)，則『應得被害人同意』。", "law": "刑訴§455-2。", "trap": "A僅檢察官有聲請權、C協商範圍含科刑沒收緩刑、D道歉賠償須被害人同意(§455-2Ⅱ)，皆對。"}, {"c": "道德、法律與倫理之性質", "k": "要記：法律是『最低的道德標準』人人須遵守；道德內涵因人而異；倫理是社群基於特殊屬性形成之價值規範。", "law": "基礎概念：法律＝最低限度之道德；倫理＝特定群體之價值規範。", "trap": "A道德倫理不須形諸明文亦有拘束力；B見死不救僅道德倫理問題、無保證人地位不負刑責；C法官與律師合資設教育中心招生，涉法官兼業營利之倫理疑慮。"}, {"c": "檢察一體與職務移轉權", "k": "要記：檢察官受檢察長書面命令不同意時，得以書面敘明理由；檢察長得親自處理(承繼)或命他檢察官處理(移轉)。", "law": "法院組織法§63、§64(檢察一體、職務承繼與移轉權)。", "trap": "A檢察官仍有獨立辦案空間；C非如法官有完全獨立保障(受檢察一體拘束)；D法律意見不同非當然懲戒事由。"}, {"c": "法官法庭言行與禁止差別待遇", "k": "要記：法官當庭辱罵、歧視外國籍當事人→違反公正中立、禁差別待遇、法庭莊嚴。", "law": "法官倫理規範§5(公正中立)、§12(法庭莊嚴、不得辱罵)、禁差別待遇。", "trap": "A公正中立、B禁國籍差別待遇、C不得當庭辱罵——都是甲所違反的。"}, {"c": "法官參與集會結社之限制", "k": "要記：法官得參加一般社團，但不得從事政治性募款或為候選人助選。", "law": "法官倫理規範(政治中立、不得募款)。", "trap": "A結社並非『不受任何限制』；C得為大學校友會會員；D得為流浪動物協會會員(一般公益社團不禁止)。"}, {"c": "法官行為分際(獨立、不關說、兼課)", "k": "要記：法官經同意得在大學兼課(時數受限)、參與法律座談演講。", "law": "法官倫理規範(審判獨立、不得對個案提供意見、兼職限制)。", "trap": "A上政論節目就自己案件辯論→評論繫屬案件損形象；B以判決書撰寫要脅、踰評議分際；C私下打電話教被告攻防→喪失中立、對個案提供意見。"}, {"c": "律師離職通知客戶之分際", "k": "要記：離職律師得通知自己承辦案件之客戶並提供事務所接手律師資訊；不得促使轉委任自己。", "law": "律師倫理規範(離職不得不當招攬、應與事務所交接)。", "trap": "B通知全部客戶招攬；C促請客戶轉委託自己；D離職後未知會事務所逕自招攬——均屬不當招攬。"}, {"c": "法官不得當庭貶損律師尊嚴", "k": "要記：法官當庭貶損辯護律師之專業與尊嚴→言行不當，違反法官倫理。", "law": "法官倫理規範§12(不得對在庭之人辱罵、損其尊嚴)。", "trap": "A非善意提醒；B已損律師尊嚴；C問題不在『私下或公開』而在內容本身不當。"}, {"c": "檢察官與律師之金錢往來限制", "k": "要記：檢察官不應與律師有金錢借貸關係，以免損害司法公正形象。", "law": "檢察官倫理規範(避免損害司法公正形象、利益迴避)。", "trap": "A『未貪污就不違反』錯；B『不應為任何投資』過廣；D『好友借款無不當』忽略身分利益衝突。"}, {"c": "檢察官兼職限制", "k": "要記：檢察官不得兼任營利事業或私法人(私立大學董事會監察人)之職務。", "law": "檢察官倫理規範、公務員服務法(不得兼任營利事業/私法人職務)。", "trap": "A法扶分會審查委員(公益)、C高中法治宣講(無償公益)、D法務部移送懲戒案之代理人(職務行為)——均得為之。"}, {"c": "律師正當辯護與不當行為之界線", "k": "要記：於訴訟中指出對造證人有偽證前科、爭執證詞可信度→屬正當辯護攻防。", "law": "律師倫理規範(正當辯護 vs 恐嚇、未告知錄音、利用當事人)。", "trap": "B以『做毀滅性東西』恐嚇職員；C與對造私下錄音蒐證未告知；D利用當事人無助心理發生性行為——均嚴重違反。"}, {"c": "律師曾為遺囑見證人之利益衝突", "k": "要記：律師曾為遺囑見證人，該遺囑涉訟時不得任一造代理人，除非得訴訟中『所有當事人』同意。", "law": "律師倫理規範(利益衝突、曾參與事件之迴避)。", "trap": "A『可以但須據實作證』忽略利益衝突；B『最瞭解有助真實』非正當理由；D『依法即絕對不得』過絕對(得全體同意則可)。"}, {"c": "律師保密義務之持續性", "k": "要記：律師保密義務持續存在——只要秘密尚未公開，縱已卸任顧問、縱當事人死亡，仍負保密義務。", "law": "律師倫理規範(保密義務)。", "trap": "A『卸任即不負』、B『專利過期即解除』、C『一人死亡即不負』——均誤解保密義務之存續。"}, {"c": "法官與其親屬律師之迴避", "k": "要記：律師不得承辦其法官親屬『承審或任職法院』之案件；不在該法院則無此限。", "law": "律師法、法官倫理規範(避免在親屬承審/任職之法院執業致生不當聯想)。", "trap": "A被告委任曾審該案之父甲為二審辯護；C當事人委任甲於父曾任職之北院辯護；D乙代理自己曾協助法官處理之同一案件——均違反。"}, {"c": "律師禁止支付引介報酬", "k": "要記：律師不得對『引介案件』之人支付報酬(禁止勾介分酬)。", "law": "律師倫理規範(禁止以利益勾介案件、支付介紹費)。", "trap": "B『有業務合作就不違反』、C『雙方互付就不違反』、D『簽對等協定就不違反』——支付引介報酬本身即違反，無此例外。"}, {"c": "律師對案件結果之誠實說明義務", "k": "要記：律師對勝負只能依現行見解作『初步判斷』說明，不得保證必勝、不得以恐嚇敗訴招攬。", "law": "律師倫理規範(不得保證勝訴、誠實告知)。", "trap": "A擔保有利結果(保證勝訴)；C隱瞞法律意見以招攬；D恫嚇『不委任將敗訴』招攬——均違反。"}], "商事法": [{"c": "轉投資之限制 §13", "k": "公開發行公司為他公司有限責任股東，投資總額不得超過實收股本40%，但得以章程排除。", "law": "公司法§13、§15、§16。", "trap": "A公司不得為合夥之無限責任合夥人、C得章程允許保證、D資金貸與有限制，皆有誤。"}, {"c": "公司組織之變更 §106、§113", "k": "稱有限公司『須經股東表決權2/3以上同意』變更為股份有限→錯，須全體股東同意。", "law": "公司法§76-1、§106、§113、§126。", "trap": "A無限變有限、B兩合變股份、C閉鎖變非閉鎖，皆對。"}, {"c": "虛偽收足股款之刑責 §9", "k": "稱以申請文件表明收足『僅受行政罰鍰』→錯，§9公司負責人處5年以下有期徒刑等刑責。", "law": "公司法§7、§9、§131。", "trap": "A廢除最低資本額、B 30日內查核簽證、C得以財產抵繳股款，皆對。"}, {"c": "經理人之競業禁止 §32", "k": "不得為非同類業務事業之無限責任股東(競業禁止限同類業務)。", "law": "公司法§32。", "trap": "A不得兼任其他營利事業經理人、B不得自營同類業務、C不得為他人經營同類業務，皆為經理人義務。"}, {"c": "電子投票 §177-2", "k": "稱已電子投票之股東親自出席『亦不得就臨時動議行使表決權』→錯，就臨時動議仍得行使表決權。", "law": "公司法§177-2。", "trap": "A以代理人出席為準、C開會2日前得撤銷、D重複時以最先送達為準，皆對。"}, {"c": "有限公司董事自我交易與辭職 §108", "k": "甲出租辦公室給A公司，由乙代表A公司簽約；乙不得無故辭去董事職務。", "law": "公司法§108、§223、§192。", "trap": "A/B/D之代表人或辭職敘述有誤。"}, {"c": "簡易合併 §316-2", "k": "A持B 92%(逾90%)，簡易合併只須兩家董事會特別決議，無須股東會決議。", "law": "公司法§316-2。", "trap": "A資本額、C存續公司股東無收買請求權、D消滅公司不清算之敘述，皆有誤。"}, {"c": "私募轉換公司債 §248-1", "k": "非公開發行非閉鎖性公司私募轉換公司債，須經董事會特別決議並經股東會普通決議。", "law": "公司法§246、§248-1。", "trap": "A/B/C之決議程序有誤。"}, {"c": "特別股之設計 §157", "k": "就分派股息及紅利之定額或定率發行特別股，該定額或定率得為零。", "law": "公司法§157。", "trap": "A否決權不及於總經理任用、C複數表決權選董監時與普通股同、D無表決權特別股不得禁止出席，皆不適法。"}, {"c": "限制員工權利新股 §267", "k": "A(非公開發行)、B(公開發行)均可發行限制員工權利新股給甲(A之員工)；乙為B之董事長(非員工)不得發給。", "law": "公司法§267。", "trap": "A/B/C之發給對象有誤。"}, {"c": "臨時管理人 §208-1", "k": "稱監察人得『自行召集股東會以決議解任臨時管理人』→錯，臨時管理人由法院選任及解任。", "law": "公司法§208-1。", "trap": "A為公司負責人、B負忠實注意義務、C得聲請法院解任，皆對。"}, {"c": "監察人各自獨立行使 §221", "k": "稱重大監察事務有不同意見『應採多數決』→錯，監察人各自獨立行使監察權(非多數決)。", "law": "公司法§221、§222、§217。", "trap": "A各自單獨為之、C不得兼任董事經理人、D任期最長3年得連任，皆對。"}, {"c": "發起人應認股 §131", "k": "稱甲(發起人)無須認股出資→錯，發起設立發起人應認足第一次發行股份。", "law": "公司法§129、§131。", "trap": "A股份總數全數發行、B章程簽名或蓋章(簽名即可)、C以電烤箱財產抵繳，皆符合。"}, {"c": "私募有擔保公司債無上限 §248-1", "k": "私募有擔保普通公司債不受§247發行總額限制。", "law": "公司法§247、§248、§248-1。", "trap": "A/B/C之金額計算有誤。"}, {"c": "關係企業之股東代位 §369-4", "k": "稱『繼續六個月以上持有Y股份之股東』得代位→錯，§369-4須繼續一年持有。", "law": "公司法§369-4、§369-7。", "trap": "A適當補償否則賠償、B債權人Z得代位、C不得抵銷，皆對。"}, {"c": "保險利益之欠缺 §16、§17", "k": "乙(子)對甲(父)之房屋無保險利益，保險契約無效。", "law": "保險法§16、§17。", "trap": "A有效、B效力未定、D得撤銷，皆非。"}, {"c": "避免損害費用之比例償還 §33", "k": "甲得依投保比例(600/1000)請求償還所支出之避免損害必要費用。", "law": "保險法§33。", "trap": "A非受指示不得請求、B全額請求、C無效果不得請求，皆錯。"}, {"c": "怠於事故通知之效果 §63", "k": "要保人怠於通知者，保險人僅得請求損害賠償(不得解約或拒賠)。", "law": "保險法§58、§63。", "trap": "A解除契約、B不負理賠、D解約並請求賠償，皆錯。"}, {"c": "未來事項特約之效力 §69", "k": "稱特約以履行不可能或不合法為內容者『保險契約無效』→錯，§69未來事項在訂約地不合法而未履行者契約仍有效。", "law": "保險法§66-§69。", "trap": "B/C違反特約得於知悉後一個月內解約、D一切事項得以特約約定，皆對。"}, {"c": "據實說明之因果關係 §64", "k": "高血壓與車禍死亡之保險事故間無因果關係，A保險公司不得解除契約，仍應負給付之責。", "law": "保險法§64。", "trap": "A/B/D認得解除或拒賠，皆錯。"}, {"c": "保險標的之承保範圍", "k": "承保範圍含廠內客戶待修車輛，待修汽車5部應理賠；員工自有汽車3部不在承保範圍，無須理賠。", "law": "保險法、保險契約承保範圍。", "trap": "B/C/D之理賠範圍有誤。"}, {"c": "據實說明之2年除斥期間 §64", "k": "契約訂立2年後，保險人不得以隱匿為由解除契約(縱精神疾病復發)。", "law": "保險法§64Ⅲ。", "trap": "A/B/C認2年後或一年時仍得解除，皆錯。"}, {"c": "被保險人之同意權 §105", "k": "稱受益人之變更『得不經被保險人書面承認』→錯，§105受益人變更應經被保險人書面承認。", "law": "保險法§105。", "trap": "A契約及保險金額應書面同意、B受益人指定應書面同意、D變更應書面承認，皆對。"}, {"c": "年齡不實之效果 §122", "k": "真實年齡未超保險年齡限度者，保險人得請求補繳短繳保費或按比例調降保險金額。", "law": "保險法§122。", "trap": "A解除、B無效、D終止，皆非。"}, {"c": "安定基金之提撥比率 §143-1", "k": "安定基金提撥額度不得低於各保險業總保險費收入之千分之一。", "law": "保險法§143-1。", "trap": "A百分之一、C千分之二、D萬分之一，皆非。"}, {"c": "票據抗辯之切斷 §13", "k": "丁善意取得，戊(自善意前手受讓)仍取得票據權利，得向甲行使追索權，甲不得以對乙之抗辯對抗。", "law": "票據法§13、§14。", "trap": "A/B/D認戊不得追索，皆錯。"}, {"c": "公示催告與提供擔保支付 §19", "k": "乙聲請公示催告，於程序開始後得提供擔保，向甲請求票據金額之支付。", "law": "票據法§18、§19。", "trap": "A止付不能阻止善意取得、C無記名本票得公示催告、D交付轉讓不影響善意取得。"}, {"c": "欠缺發票日之票據無效 §11、§120", "k": "本票欠缺發票日(絕對必要記載事項)，甲、乙均得對丙主張票據無效。", "law": "票據法§11、§120。", "trap": "A視為見票即付(僅漏到期日才如此)、B空白授權票據、C依文義負責之敘述，皆錯。"}, {"c": "一部背書無效 §36", "k": "『20萬轉讓丙、80萬轉讓丁』為一部背書(將金額一部分轉讓)，乙之背書無效。", "law": "票據法§36。", "trap": "A匯票無效、B擔保付款責任、D附記有效，皆錯。"}, {"c": "票據保證未記載保證意旨 §59", "k": "B公司僅用印未記載保證意旨，不生保證之效力。", "law": "票據法§59。", "trap": "A視為承兌人保證、B視為發票人保證、D未載年月日無效，皆錯。"}, {"c": "參加付款之被參加付款人 §57", "k": "參加付款未記載被參加付款人，無參加承兌人或預備付款人時，視為為發票人甲參加付款。", "law": "票據法§57。", "trap": "B乙、C丙、D無被參加付款人，皆非。"}, {"c": "本票遵期提示與裁定執行 §123", "k": "到期日(12/1)後2日內(12/3)提示，遵期提示對發票人不喪失追索權，得依§123裁定強制執行。", "law": "票據法§69、§123、§124。", "trap": "A/B喪失追索權或付款請求權、D未遵期之敘述，皆錯。"}, {"c": "偽造簽名與真正背書人責任 §15", "k": "己為真正背書人，應負背書人之票據責任。", "law": "票據法§15。", "trap": "A乙(被偽造)不負發票人責任、B丁(被偽造)不負背書責任、D甲戊(偽造人)不負票據責任(負偽造刑責)。"}, {"c": "特別平行線支票 §139", "k": "平行線內記載D銀行(特別平行線)，僅能對D銀行支付，C銀行付款違反規定，應負損害賠償責任。", "law": "票據法§139。", "trap": "A位置錯誤、B不得記載特定銀行、D罰鍰之敘述，皆錯。"}, {"c": "保付支票之付款請求權時效 §138、§22", "k": "乙對A(保付付款人，責任同承兌人)之付款請求權時效為三年。", "law": "票據法§22、§138。", "trap": "A/B一年、D追索權三年，皆非。"}, {"c": "董事會召集通知 §204", "k": "例行性董事會召集通知應於7日前發出(7/24開會→最晚7/16發出)。", "law": "公司法§204。", "trap": "A 7/21、B 7/20、C 7/17，皆非。"}, {"c": "金融業強制設審計委員會 §14-4", "k": "稱『得擇一設置審計委員會或監察人』→錯，一定規模/金融業強制設審計委員會，不得擇一。", "law": "證券交易法§14-2、§14-4、§14-6。", "trap": "A常務董事中獨立董事比例、B獨立董事得聘專家、D應設薪資報酬委員會，皆對。"}, {"c": "持股轉讓限制之適用對象 §22-2", "k": "甲之成年兒子(成年子女非§22-2所列對象)。", "law": "證券交易法§22-2。", "trap": "A甲之妻(配偶)、C乙(法人代表董事)、D乙之妻(配偶)，皆受限。"}, {"c": "公開收購期間之限制 §43-1", "k": "公開收購期間A之從屬公司不得於櫃買市場買進B股份，但收購期間屆滿日後不受限制。", "law": "證券交易法§43-1。", "trap": "A/B/D之申報及停止收購敘述有誤。"}, {"c": "私募之特別決議 §43-6", "k": "私募須已發行股份總數過半數出席、出席表決權2/3以上同意，出席510萬×2/3＝340萬。", "law": "證券交易法§43-6。", "trap": "A 255萬、B 255萬零1、D 340萬零1，皆非。"}, {"c": "對外公開發行新股之認購 §267", "k": "對外公開發行之新股，原股東無優先認股權利，由董事會決議定之。", "law": "公司法§267。", "trap": "A 2萬4千、C 3萬、D 8萬股之計算，皆非。"}, {"c": "上市股票場外交易之限制 §150", "k": "A(上市)股票1萬股直接讓受逾1成交單位，違法；B(上櫃)股票不適用§150，合法。", "law": "證券交易法§150。", "trap": "A均合法、B反、D均違法，皆非。"}, {"c": "庫藏股之轉讓期間 §28-2", "k": "A公司本次買回之股份(激勵員工)，應於買回之日起五年內將其轉讓。", "law": "證券交易法§28-2。", "trap": "A最多買回股數、C得參與盈餘分配、D僅於櫃買市場買回之敘述，皆有誤。"}, {"c": "公開說明書不實之無過失責任 §32", "k": "A公司(發行人)應對丁之損害負無過失損害賠償責任。", "law": "證券交易法§32。", "trap": "B職員甲、C會計師乙、D承銷商丙，得舉證已盡相當注意而免責(非無過失責任)。"}, {"c": "短線交易歸入利益之計算 §157", "k": "依最高賣價與最低買價相配之計算法，甲應歸入A公司之利益為35萬元。", "law": "證券交易法§157。", "trap": ""}, {"c": "第三人異議之訴之當事人 強執法§15", "k": "稱丙出資興建並出售於乙『丙亦得提第三人異議之訴』→錯，丙已出售非權利人，不得提異議之訴。", "law": "強制執行法§15。", "trap": "A丙出資興建得提、C丁代位丙、D丁不得代位(丙已無權利)，皆對。"}, {"c": "確定判決為新執行名義 強執法§4", "k": "前案假執行經停止後，甲以確定之一審判決聲請後案執行，執行法院仍應實施後案執行。", "law": "強制執行法§4、§14、§18。", "trap": "A/B/C認應駁回或當然停止，皆錯。"}, {"c": "動產拍賣之底價 §70", "k": "稱動產如預定底價『應於拍賣公告載明』→錯，動產拍賣之底價不公告。", "law": "強制執行法§70。", "trap": "A無須鑑價、B無須預定底價、D未通知到場拍賣仍有效，皆對。"}, {"c": "薪資移轉命令與執行終結 §115", "k": "稱移轉命令生效後『執行程序即已終結』→錯，薪資債權將來繼續受償，執行程序未終結。", "law": "強制執行法§115、§115-1、§119。", "trap": "A支付命令未合法送達得異議、B扣押命令送達丙時生效、D丙得10日內聲明異議，皆對。"}, {"c": "查封前租賃不得點交 §99", "k": "A屋為第三人丙於查封前承租占用(查封前之租賃，拍定後不點交)。", "law": "強制執行法§99。", "trap": "A乙自住、C查封後承租、D乙之保全人員(占有輔助人)，皆得點交。"}, {"c": "收取命令與聲明異議 §119", "k": "丙收受扣押命令未於10日內異議，續發收取命令後，丙仍得於收受收取命令後10日內聲明異議，執行法院尚不得逕對丙財產強制執行。", "law": "強制執行法§119。", "trap": "A/C/D之異議效果敘述有誤。"}, {"c": "執行力客觀範圍及於建物 強執法§131", "k": "確定判決命返還土地，其執行力客觀範圍及於強制執行時乙在A地上有處分權之B建物，執行法院應依甲聲請拆除B建物、返還A地。", "law": "強制執行法§131。", "trap": "A駁回、B執行不能、D另取執行名義，皆錯。"}, {"c": "返還共有物之執行與再執行 強執法§28、§131", "k": "拆除B屋點交A地後乙復占有，甲得持原確定判決再聲請強制執行，但應另繳執行費。", "law": "強制執行法§27、§28、§131。", "trap": "A須協同丙、B按B屋價格、C再執行免繳費之敘述，皆錯。"}, {"c": "假扣押之追加執行 強執法§132", "k": "追加查封不受收受裁定後30日之限制，執行法院應准許甲之追加執行聲請。", "law": "強制執行法§132。", "trap": "B駁回、C裁量、D逾額駁回之敘述，皆錯。"}, {"c": "第三人異議之訴停止與後案 強執法§15、§33", "k": "前案經丙提第三人異議之訴停止執行，丁就A屋聲請後案執行，執行法院應不待前案恢復，依丁聲請繼續執行後案。", "law": "強制執行法§15、§33。", "trap": "A待前案恢復、C免繳執行費、D前案不得受分配之敘述，皆錯。"}, {"c": "公司名稱 §18", "k": "雖特取名稱近似，但已標明不同業務之文字(美麗美粧 vs 美麗食品)，可登記。", "law": "公司法§18。", "trap": "A相同、C相類似、D不同縣市之敘述，皆有誤。"}, {"c": "轉投資、貸款與保證 §13、§15、§16", "k": "A公司已不得再為他人保證(綜合轉投資、資金貸與及保證之限制)。", "law": "公司法§13、§15、§16。", "trap": "A/B 60%額度、D無上限之敘述有誤。⚠️本題可對照詳解。"}, {"c": "命令解散與裁定解散 §10、§11", "k": "①命令/裁定解散須清算後法人格消滅；②設立登記後6個月未營業未延展得命令解散。", "law": "公司法§10、§11、§18、§24。", "trap": "③裁定解散須股東聲請(非債權人)、④名稱判決確定後6個月內(非3個月)，皆錯。"}, {"c": "政府股東之代表人當選 §27", "k": "政府股東推派10名自然人代表參選董事(代表人當選)。", "law": "公司法§27。", "trap": "A/B/D混合自行參選與推派代表，不得併用(§27Ⅰ與Ⅱ擇一)。"}, {"c": "有限公司不設監察人 §108", "k": "監察人(有限公司由不執行業務股東監督，不設監察人)。", "law": "公司法§108、§109、§113。", "trap": "A董事、B經理人、C清算人，皆可能出現於有限公司。"}, {"c": "有限公司董事自我交易 §108、§223", "k": "A公司向董事長甲購地，甲有利益衝突，由其他董事乙代表A公司與甲訂約。", "law": "公司法§108、§223。", "trap": "A甲自己代表、B監察人(有限公司無監察人)、C推選股東之敘述，皆有誤。"}, {"c": "臨時動議減資之決議瑕疵 §189", "k": "減資(變更章程)不得以臨時動議提出，違反召集程序，該決議得撤銷。", "law": "公司法§172、§189。", "trap": "A決議不成立、C無效、D未違反之敘述，皆錯。"}, {"c": "少數董事自行召集董事會 §203、§208", "k": "少數董事自行召集之董事會，主席由出席董事(乙丙丁)互推。", "law": "公司法§203-1、§208。", "trap": "B非董事長無權召集、C/D召集程序之敘述有誤。"}, {"c": "股東提案權 §172-1", "k": "依官方見解，乙之持股期間未達相關要件，不得提案(解任董事之提案)。", "law": "公司法§172-1、§199、§200。", "trap": "B/C/D之敘述有誤。⚠️本題可對照§172-1與§200要件之詳解。"}, {"c": "股東自行召集股東臨時會 §173-1", "k": "丙(25%)、丁(30%)合計過半數且繼續3個月以上，得依§173-1隨時自行召集股東臨時會，無須請求董事會或主管機關許可。", "law": "公司法§173、§173-1。", "trap": "A/B/D之召集要件有誤。"}, {"c": "董事設質之表決權限制 §197-1", "k": "§197-1限制選任時持股(10,000)設質超過1/2(5,000)之部分(5,000股)不得行使，任期中買進之10,000股設質不受限，可行使15,000股。", "law": "公司法§197-1Ⅱ。", "trap": "A/B/C之計算有誤。"}, {"c": "表決權之迴避 §178", "k": "甲僅就議案三(購買甲之土地，自我交易)不得行使表決權；B公司就議案二(合併)得行使表決權。", "law": "公司法§178、企業併購法§18。", "trap": "A/B/C之迴避範圍有誤。"}, {"c": "常務董事由董事互選 §208", "k": "稱常務董事『由股東會選任』→錯，常務董事由董事互選。", "law": "公司法§208。", "trap": "B副董事長由常務董事會選任、C董事長請假由副董事長代理、D解任董事長仍為董事，皆對。"}, {"c": "增資與變更章程 §278", "k": "A公司得先變更章程提高資本額，再發行新股。", "law": "公司法§266、§277、§278。", "trap": "A須全數發行完畢始得變更、C先增資後補辦、D須一次募足之敘述，皆錯。"}, {"c": "關係企業之債權人代位 §369-4", "k": "甲(B公司之債權人)得以自己名義行使B公司權利，請求A公司對B公司為給付。", "law": "公司法§369-2、§369-4。", "trap": "A不以持股半數為限、B債權無金額限制、C拋棄不影響債權人代位。"}, {"c": "再保險契約之特約 §40", "k": "原保險與再保險雖各自獨立，但契約條款已另行約定，原被保險人例外得直接向再保險人請求保險金。", "law": "保險法§40、§39。", "trap": "A條款多餘、C/D條款無效之敘述，皆錯。"}, {"c": "危險增加之通知義務 §59-§62", "k": "危險增加若係為防護保險人之利益者，即使因要保人行為所致，亦無需通知保險人(§62)。", "law": "保險法§59、§61、§62。", "trap": "A繼續收費仍得終止、B 5日內通知、C須達終止程度始通知之敘述，皆錯。"}, {"c": "危險事故發生之通知義務 §58、§63", "k": "甲雖違反事故通知義務，A保險公司仍須理賠，但得對甲請求因遲延通知之損害賠償。", "law": "保險法§58、§63。", "trap": "A無須理賠、C/D得解除契約之敘述，皆錯。"}, {"c": "保險代位之事由 §53", "k": "保險人對第三人所得行使代位權之事由，不限於侵權行為損害賠償請求權(亦含契約)。", "law": "保險法§53。", "trap": "A/B/D之代位範圍及對象之敘述，皆有誤。"}, {"c": "詐欺之超額保險 §76", "k": "以不實行照詐欺投保超額保險(100萬車保300萬)，保險公司行使解除權後無須理賠。", "law": "保險法§76。", "trap": "A契約無效、C/D仍應理賠之敘述，皆錯。"}, {"c": "責任保險之時效起算 §65、§94", "k": "第三人C依§94直接請求，時效自被保險人對第三人應負賠償責任確定時(108/10判決確定)起算2年，尚未罹於時效。", "law": "保險法§65、§94。", "trap": "A/B/C之起算時點有誤。"}, {"c": "停效後之復效 §116", "k": "稱交付保費利息費用後『即刻』恢復效力→錯，停效後6個月內清償者，於翌日上午零時起恢復效力。", "law": "保險法§116。", "trap": "A不得請求可保證明、B至營業所交付、D不得拒絕復效，皆對。"}, {"c": "利害關係人放款之十足擔保 §146-3", "k": "保險業對利害關係人之放款應有十足擔保。", "law": "保險法§146-3。", "trap": "B擔保不限不動產、C得放款、D決議門檻之敘述，皆有誤。"}, {"c": "傷害保險之除外責任 §133", "k": "被保險人於契約訂約二年後故意自殺(自殺非意外傷害)。", "law": "保險法§109、§131、§133。", "trap": "A海洋弧菌、B手術醫生過失、C疫苗副作用，皆屬意外傷害，保險人應負責。"}, {"c": "再保費提高與情事變更 §59、§60", "k": "再保費提高，B公司欲請求增加保費，應依實際狀況判斷有無情事變更原則之適用。", "law": "保險法§59、§60、民法§227-2。", "trap": "A得逕調高保費、B 10日內通知、D僅得終止契約之敘述，皆有誤。"}, {"c": "支票利益償還請求權之時效 §22Ⅳ", "k": "乙得自支票票據權利時效完成後15年內向甲請求(利益償還請求權時效15年)。", "law": "票據法§22Ⅳ，最高法院見解。", "trap": "A/B/C之起算或期間有誤。"}, {"c": "支票背面簽名視為背書 §144", "k": "丙在支票背面簽名，應負票據背書人責任(支票無保證，背面簽名視為背書)。", "law": "票據法§31、§144(支票無保證制度)。", "trap": "B保證人責任、C二者皆負、D不負責，皆錯。"}, {"c": "票據變造之責任 §16", "k": "戊行使追索權，得向丙(變造並於變造後簽名/同意者，依變造文義負責)請求20萬元。", "law": "票據法§16。", "trap": "A發票人依原文義(10萬)、B/C之責任認定有誤。"}, {"c": "偽造背書與善意取得 §14", "k": "丁以相當對價善意取得票據，甲(發票人)發票行為有效，仍須負票據責任。", "law": "票據法§14、§15。", "trap": "A無須負責、C/D之敘述，皆錯。"}, {"c": "匯票付款提示期限 §69", "k": "到期日(102/6/5)或其後2日內提示，最遲6/7。", "law": "票據法§69。", "trap": "A 6/6、C 6/8、D 6/9，皆非最遲日。"}, {"c": "故意塗銷背書之免責 §38", "k": "丁故意塗銷乙之背書，乙(被塗銷)及丙(名次在乙後塗銷前背書者)免責，負責者為發票人甲及塗銷背書人丁。", "law": "票據法§38。", "trap": "A/B/D之責任範圍有誤。"}, {"c": "支票漏記發票地 §125Ⅳ", "k": "發票地未記載者，以發票人之營業所、住所或居所為發票地(甲住所臺北)。", "law": "票據法§125Ⅳ。", "trap": "B高雄、C臺南、D無效，皆非。"}, {"c": "保付支票之責任 §138", "k": "保付支票僅由付款人A負票據責任(保付後發票人背書人免責)。", "law": "票據法§138。", "trap": "B/C甲乙仍負責、D提示期限之敘述，皆錯。"}, {"c": "禁止背書轉讓之效力 §30", "k": "乙記載禁止背書轉讓僅對直接被背書人丙負責，對禁背後再受讓之丁不負責；丁得向發票人甲及背書人丙追索。", "law": "票據法§30。", "trap": "A/B含乙、D僅甲，皆錯。"}, {"c": "庫藏股維持公司信用 §28-2", "k": "可行，但應先經董事會特別決議，並於最近一次股東會報告。", "law": "證券交易法§28-2。", "trap": "B比例不超過3%、C須改目的、D連續交易之敘述，皆錯。"}, {"c": "審計委員會缺額之決議 §14-5", "k": "委任簽證會計師事項得先經審計委員會至少二名獨立董事同意，再經董事會決議。", "law": "證券交易法§14-5。", "trap": "A/B/D之決議方式有誤。"}, {"c": "獨立董事全體解任之補選 §14-2", "k": "甲乙丙(全體獨立董事)同時辭職，應自事實發生日起60日內召開股東臨時會補選。", "law": "證券交易法§14-2。", "trap": "A 30、B 50、D 90日，皆非。"}, {"c": "董事間之親屬關係 §26-3", "k": "稱A公司董事間『皆不得』具配偶或二親等內親屬關係→錯，應有超過半數不得具親屬關係(非全部)。", "law": "證券交易法§26-3。", "trap": "A法人代表不得分任董監、B監察人間至少一席不得具親屬、D親屬當選失效，皆對。"}, {"c": "委託書徵求 §25-1", "k": "自然人甲得僅受股東B一人之委託，代理B出席行使B全部之表決權。", "law": "證券交易法§25-1、委託書規則。", "trap": "A/B/C之委託書徵求要件有誤。"}, {"c": "控制股東公開收購之申報 §43-1", "k": "A已持有B逾50%再收購至90%，以公開收購為之不須向證券主管機關申報，即得為之。", "law": "證券交易法§43-1。", "trap": "A/C/D之申報及限制敘述有誤。⚠️可對照詳解。"}, {"c": "私募新股之決議 §43-6", "k": "私募新股須經股東會已發行股份總數過半數出席，出席股東表決權2/3以上同意。", "law": "證券交易法§43-6。", "trap": "B人數限制、C申報生效、D 2年內分次之敘述，皆錯。"}, {"c": "上市有價證券之買賣 §150", "k": "稱私人間直接讓受不超過1成交單位『前後兩次相隔不少於6個月』→錯，應為不少於3個月。", "law": "證券交易法§149、§150。", "trap": "A政府債券上市、B基於法律效力之例外、C政府債券買賣之例外，皆對。"}, {"c": "包銷 §71", "k": "承銷期間屆滿後賸餘證券由承銷商自行認購者，為包銷。", "law": "證券交易法§71、§72。", "trap": "B直銷、C代銷、D分銷，皆非。"}, {"c": "短線交易歸入權 §157", "k": "甲6個月內買賣獲利150萬，A公司應請求甲將利益歸於公司，無須股東會決議。", "law": "證券交易法§157。", "trap": "B罰鍰、C構成刑事犯罪、D非上市無責任之敘述，皆錯。"}, {"c": "管轄與囑託執行 強執法§7", "k": "甲向Y法院聲請(B房地在Y轄區)，Y法院就B房地查封拍賣，就A存款(X轄區)應囑託X法院扣押換價。", "law": "強制執行法§7。", "trap": "A/C/D之管轄及換價敘述有誤。"}, {"c": "未保存登記建物第三人取得 強執法§17", "k": "丙提出買賣契約及匯款證明主張已取得事實上處分權，執行法院諭知甲，經其同意後撤銷對A屋之查封。", "law": "強制執行法§17。", "trap": "A/C/D之處置方式有誤。"}, {"c": "動產拍賣無人應買 強執法§71", "k": "稱未拍定且不願承受『應撤銷該動產之拍賣』→錯，應撤銷查封並返還動產。", "law": "強制執行法§70、§71。", "trap": "A出價低於底價不拍定、B得作價承受、C撤銷查封，皆對。"}, {"c": "拍定後不點交之拘束力 強執法§99", "k": "A地以『拍定後不點交』為拍賣條件，丁於拍定後不得再為相反主張(要求點交)，執行法院應駁回其異議。", "law": "強制執行法§99。", "trap": "A/B/C之處置有誤。"}, {"c": "各類財產之執行程序 強執法§114", "k": "稱執行飛機(航空器)『準用動產執行程序』→錯，航空器準用不動產執行程序。", "law": "強制執行法§114、海商法、民用航空法。", "trap": "A實體股票(動產)、B有限公司出資(對第三人金錢債權)、D礦業權(不動產)，皆對。"}, {"c": "不動產之執行方法 強執法§75", "k": "命令讓與(係對第三人債權之執行方法，非不動產)。", "law": "強制執行法§75、§103、§116。", "trap": "A投標拍賣、C強制管理、D拍賣併強制管理，皆為不動產執行方法。"}, {"c": "探視子女之執行與第三人 強執法§128", "k": "丁(托育設施)拒絕配合執行者，執行法院應退出丁之設施，不得繼續執行(丁非執行名義效力所及)。", "law": "強制執行法§128。", "trap": "A逕對丁執行、B丁有配合義務、D應駁回之敘述，皆有誤。"}, {"c": "意思表示擬制與代替行為 強執法§127、§130", "k": "命乙登報道歉(可代替行為，須聲請強制執行代履行)。", "law": "強制執行法§127、§128、§130。", "trap": "A移轉登記、B訂立買賣契約、D協同過戶，皆依§130視為意思表示無須執行。"}, {"c": "終局執行中之假扣押 強執法§133", "k": "甲終局執行中丙對同一財產假扣押，應視丙之假扣押為參與分配，以其應受分配金額提存。", "law": "強制執行法§133。", "trap": "A不准許、B附條件、C同受分配之敘述，皆錯。"}, {"c": "保全執行不排除強制執行 強執法", "k": "甲假扣押查封A建物，丙持拆屋還地確定判決聲請執行，應予准許(保全執行之效力不排除法院之強制執行)。", "law": "強制執行法§51、§133。", "trap": "A/B不應准許、D權利不同之理由，皆有誤。"}, {"c": "揭穿公司面紗適用於有限公司 §99-1", "k": "揭穿公司面紗原則亦明文適用於有限公司(§99-1準用)，故有可能向甲、乙求償。", "law": "公司法§99-1、§154Ⅱ。", "trap": "A類推適用、B僅股份有限、D僅及董事股東之敘述，皆有誤。"}, {"c": "公司負責人之範圍 §8", "k": "稱公司債受託人在職務範圍內為公司負責人→錯，公司債受託人非公司負責人。", "law": "公司法§8。", "trap": "B臨時管理人、C檢查人、D有限公司董事，皆為公司負責人。"}, {"c": "法人股東改派代表人 §27", "k": "乙可承受B公司董事職位，但不包括董事長職位(董事長由董事互選)。", "law": "公司法§27。", "trap": "A承受董事長、B須股東會同意、D須B公司同意之敘述，皆有誤。"}, {"c": "經理人之委任解任 §29", "k": "稱章程得將董事會委任解任經理人之權限『改由股東會決議』→錯，經理人委任解任由董事會。", "law": "公司法§29、§31、§36。", "trap": "A職權限制不得對抗善意第三人、B出售全部財產逾權、C董事會得隨時解任，皆對。"}, {"c": "有限公司之減資 §106、§113", "k": "減資(變更章程)經股東表決權過半數同意(7人中甲乙丙丁4人過半)即得進行。", "law": "公司法§106、§113。", "trap": "A增資、B新股東加入須全體同意、D減資過半數即可戊不得否決。"}, {"c": "出資種類之勞務出資", "k": "稱有限公司股東得以勞務出資→錯，有限公司不得勞務出資。", "law": "公司法§43、§99-1、§115、§131、§356-3。", "trap": "A無限公司、C閉鎖性公司得勞務出資、D發起人不得勞務出資，皆對。"}, {"c": "閉鎖性公司發行新股 §356-12", "k": "稱閉鎖性公司發行新股『員工與原股東享有新股認購權』→錯，不適用§267認購權。", "law": "公司法§267、§356-3、§356-12、§356-14。", "trap": "B發起人得勞務出資、C變更為非閉鎖性須特別決議、D變更為閉鎖性須全體股東同意，皆對。"}, {"c": "公積發放現金 §241", "k": "稱『不論有無累積虧損皆可發放』→錯，以公積發放現金須先彌補累積虧損。", "law": "公司法§241。", "trap": "B股東會決議、C公開發行得授權董事會特別決議、D法定盈餘公積以超過實收資本25%部分為限，皆對。"}, {"c": "電子方式發送開會通知 §172", "k": "非公開發行公司發函全體股東徵詢意願後，對回函同意者，得以電子方式通知。", "law": "公司法§172。", "trap": "A董事會決議、B股東會決議、D不允許之敘述，皆有誤。"}, {"c": "法人股東一人設立公司 §2、§128-1", "k": "A公司(法人)仍得獨自以股東身分合法設立B公司(政府或法人股東一人組織之股份有限公司)。", "law": "公司法§2、§128、§128-1。", "trap": "B/C/D須另尋共同發起人之敘述，皆錯。"}, {"c": "董事會書面行使表決權 §205", "k": "章程明訂經全體董事同意者，董事就當次會議議案得以書面行使表決權。", "law": "公司法§205。", "trap": "A/C/D之要件門檻有誤。"}, {"c": "監察人之補選 §217-1", "k": "監察人二人中甲死亡乙仍在(非全體缺額)，毋須辦理補選。", "law": "公司法§217-1。", "trap": "A/B/C認須補選，皆錯。"}, {"c": "未受通知不受相互投資表決權限制 §369-10", "k": "B公司未通知A相互投資之事實，A亦不知，A得行使表決權且無上限限制。", "law": "公司法§369-10。", "trap": "A/B/C認不得行使或受1/3、1/2限制，皆錯。"}, {"c": "關係企業之推定 §369-3", "k": "①同一人持二公司各過半數推定控制從屬；④半數以上董事相同推定控制從屬。", "law": "公司法§369-2、§369-3。", "trap": "②持股未達要件、③相同董事未過半，皆不該當。"}, {"c": "重整裁定前之保全處分 §287", "k": "法院重整裁定前，得因利害關係人聲請，裁定限制公司履行債務及對公司行使債權。", "law": "公司法§282、§287、§293。", "trap": "A聲請須董事會特別決議(非股東會)、B持股10%(非3%)、D經營權移屬重整人(非監督人)。"}, {"c": "部分損失之契約存續 §82", "k": "部分損失，除要保人終止契約外，保險契約就殘餘部分仍有效。", "law": "保險法§82。", "trap": "A即終止、B僅保險人有終止權、D必要費用由保險人負擔之敘述，皆有誤。"}, {"c": "未滿15歲及受監護人之死亡給付 §107、§107-1", "k": "丙(受監護宣告)死亡給付限喪葬費用半額；丁(投保時14歲，事故時已滿15歲)死亡給付生效賠500萬元。", "law": "保險法§107、§107-1。", "trap": "A/C/D之賠付組合有誤。"}, {"c": "保險金信託 §138-2", "k": "稱父母監護人為被保險人時『信託受託人得依委託人指示為該保險契約之要保人』之敘述有誤。", "law": "保險法§138-2。", "trap": "A信託受益人之限制、B設信託專戶、C得放棄處分權，皆對。"}, {"c": "部分損失之終止權期間 §82", "k": "稱終止契約權於賠償給付後『二個月』不行使消滅→錯，§82為一個月。", "law": "保險法§82。", "trap": "A均有終止權、B終止應15日前通知、D餘額責任，皆對。"}, {"c": "人壽保險之過失致死仍負責", "k": "誤闖高速公路遭撞死(非自殺非故意)，A保險公司仍應負保險責任。", "law": "保險法§109、§101。", "trap": "A自殺、B違法致死、C危險增加之敘述，皆錯。"}, {"c": "善意複保險 §35-§38", "k": "A(1200萬)、B(600萬)合計1800萬未超過保險價額(2000萬)，非超額複保險且善意，A、B均應負責。", "law": "保險法§35-§38。", "trap": "B惡意複保險無效、C/D之敘述，皆錯。"}, {"c": "危險增加未通知與事故通知 §59、§63", "k": "變更民宿未依約通知，保險人得解除契約；未依法為火災事故通知，保險人得請求損害賠償。", "law": "保險法§59、§63。", "trap": "B/C/D之權利配置有誤。"}, {"c": "健康保險準用人壽保險 §130", "k": "健康保險之保險費得以訴訟方式請求支付。", "law": "保險法§130、§117。", "trap": "A不得代位、B死亡保險金額須被保險人書面同意、D年齡超限契約無效，皆有誤。"}, {"c": "停效復效之催告期間 §116", "k": "稱催告到達後屆『二十日』效力停止→錯，§116為三十日。", "law": "保險法§116、§119。", "trap": "A六個月內清償翌日復效、C六個月後申請復效之可保證明、D返還保單價值準備金，皆對。"}, {"c": "保險契約之諾成性 §43、§44", "k": "保險契約為諾成契約，不因甲未簽名或保單尚未簽發而影響效力，A公司應理賠。", "law": "保險法§43、§44。", "trap": "B/C/D認要物或要式，皆錯。"}, {"c": "偽造背書與真正簽名人責任 §15、§37", "k": "甲(發票人)、乙(背書人)、戊(真正背書)負責；丙之背書被偽造丙不負責，丁未以自己名義簽名不負票據責任。", "law": "票據法§15、§37。", "trap": "A漏戊、C/D之責任範圍有誤。"}, {"c": "對承兌人之時效 §22", "k": "甲對承兌人乙之票據權利，自到期日起3年罹於時效(逾4年)而消滅。", "law": "票據法§22。", "trap": "A對丙之追索權1年已消滅、C/D利益償還時效為15年(非3年/1年)。"}, {"c": "票據喪失之救濟 §18、§19", "k": "稱空白未補充之票據『不可止付通知但得聲請公示催告』→錯，空白票據不得止付亦不得公示催告。", "law": "票據法§18、§19。", "trap": "A止付後5日內提證明、B未聲請公示催告止付失效、C得提供擔保請求新票據，皆對。"}, {"c": "空白背書與背書連續之追索 §30、§37", "k": "真正簽名者為甲(發票人)、乙(空白背書)、戊(記名背書)；丙、丁僅交付未背書不負責。", "law": "票據法§30、§37、§85。", "trap": "A/B/D含丙或丁，皆非。"}, {"c": "付款人正面簽名視為承兌 §43", "k": "丙(付款人)簽名於票據正面視為承兌，丙應負承兌人責任。", "law": "票據法§43、§52。", "trap": "A甲責任未定、B僅得向乙、C丙無須負責之敘述，皆錯。"}, {"c": "參加付款之競合 §51", "k": "數人請求參加付款時，以能免除最多數債務者(為發票人A參加付款，可免除B C D E之債務)優先。", "law": "票據法§51、§56。", "trap": "B/C/D所免除之債務人較少，非優先。"}, {"c": "見票後定期付款本票之提示 §122、§45", "k": "見票之提示期限為發票日後6個月內，丙逾期(106/4/30)見票，對前手乙喪失追索權，但對發票人甲仍得行使票據權利。", "law": "票據法§45、§122、§124。", "trap": "A對甲喪失、B未逾期、C對甲乙均喪失，皆錯。"}, {"c": "金額文字與號碼不符 §7", "k": "依§7票據金額之文字與號碼不符時，以文字為準(伍萬元)。", "law": "票據法§7。", "trap": ""}, {"c": "代理簽名未載本人 §9", "k": "乙代理簽發僅簽自己之名(未載本人及代理意旨)，乙須自負發票人責任。", "law": "票據法§9、§10。", "trap": "A承認即免責、C連帶責任、D均不負責，皆錯。"}, {"c": "STO虛擬通貨之認定 證交法§6", "k": "發行人出具書面獲利保證。", "law": "證券交易法§6、Howey test。", "trap": "A出資共同事業、B獲利期待、C利潤取決於他人努力，皆為認定標準。"}, {"c": "現金發行新股之提撥 §28-1", "k": "稱主管機關認無須者『得不提撥對外公開發行』之敘述有誤(上櫃公司現金發行新股應提撥一定比率)。", "law": "證券交易法§28-1。", "trap": "B時價對外公開發行、C股東會得決議提撥10%、D員工承購價格相同，皆對。"}, {"c": "審計委員會之決議 §14-5", "k": "內部控制制度修正案應經審計委員會全體成員1/2以上同意。", "law": "證券交易法§14-5。", "trap": "B/C/D之決議門檻有誤。"}, {"c": "薪資報酬委員會之組成 §14-6", "k": "稱薪資報酬委員會『應由全體獨立董事擔任委員』→錯，成員不限獨立董事。", "law": "證券交易法§14-2、§14-6、設置辦法。", "trap": "A應設獨立董事、B應設薪資報酬委員會、D職掌含股票選擇權，皆對。"}, {"c": "公開收購之申報 §43-1", "k": "稱『必須向主管機關申報後始得公開收購』之敘述有誤(採申報並公告制)。", "law": "證券交易法§43-1。", "trap": "B收購期間不得場外買進、C不得任意停止、D未完成1年內不得再收購，皆對。"}, {"c": "普通公司債之私募 §43-6、§248", "k": "稱普通公司債私募『須股東會2/3以上同意』之敘述有誤(普通公司債私募得董事會決議)。", "law": "證券交易法§43-6、公司法§246、§248。", "trap": "B發行總額限淨值400%、C一年內分次辦理、D 15日內報請備查，皆對。"}, {"c": "公司制證券交易所 §124、§126", "k": "稱公司制證券交易所之組織『以股份有限公司或有限公司為限』→錯，限股份有限公司。", "law": "證券交易法§124、§126、§128。", "trap": "A證券商人員不得任經理人、C發行股票不得上市、D不得發行無記名股票，皆對。"}, {"c": "第三季財務報告之申報期限 §36", "k": "第三季財報應於每會計年度第三季終了後45日內公告並申報。", "law": "證券交易法§36。", "trap": "A 10日、B 15日、C 30日，皆非。"}, {"c": "內線交易犯罪所得之計算 §157-1", "k": "已賣5000股實現獲利5000×15=75,000；未賣5000股擬制所得5000×30=150,000，合計225,000元。", "law": "證券交易法§157-1，最高法院大法庭。", "trap": "A/B/D之計算有誤。"}, {"c": "實體事由不得由執行法院審查 強執法§14", "k": "執行法院不得逕以實體請求權不存在駁回，債務人應提異議之訴；臺中地院裁定不當，臺中高分院應廢棄發回。", "law": "強制執行法§14、§44。", "trap": "A/B/C之處理方式有誤。"}, {"c": "財產開示限終局執行債權 強執法§20", "k": "財產開示限執行名義命債務人清償而得終局執行之債權，假扣押債權未確定，應駁回甲之聲請。", "law": "強制執行法§20。", "trap": "A繳費、B查報義務、D不限終局執行之敘述，皆有誤。"}, {"c": "承租人之孳息收取權 強執法§51", "k": "丙(承租人)就A地上之鳳梨有收取權，得提第三人異議之訴排除就鳳梨之執行。", "law": "強制執行法§51、§115。", "trap": "A查封效力及於鳳梨、C/D租金債權之敘述，皆有誤。"}, {"c": "特別拍賣應買期滿視為撤回 強執法§95", "k": "110/11/5拍賣期日終結後無人應買且乙不承受，視為乙撤回對A地之執行。", "law": "強制執行法§95。", "trap": "A拍定後點交、B改由戊得標、D再執行之點交，皆有誤。"}, {"c": "參與分配之執行名義 強執法§34", "k": "乙(抵押權人)優先受償、丁(取得本票裁定)有執行名義得參與分配；戊僅有本票未取得執行名義，不得參與分配。", "law": "強制執行法§34。", "trap": "A/C/D之組合有誤。"}, {"c": "船舶執行之準用 強執法§114", "k": "20萬噸跨洲郵輪(海商法船舶)準用不動產執行；日月潭15噸觀光船(非海商法船舶)依動產執行。", "law": "強制執行法§114、海商法§1、§3。", "trap": "A/B/D之區分有誤。"}, {"c": "移轉登記判決之擬制 強執法§130", "k": "甲得單獨持確定判決向地政機關辦理A屋所有權移轉登記，不必對乙聲請強制執行。", "law": "強制執行法§130。", "trap": "A函地政機關、C乙得聲請停止執行、D對待給付之執行名義，皆有誤。"}, {"c": "分割共有物判決之執行 強執法§131", "k": "稱丙為被告『不得持判決聲請強制執行』→錯，分割共有物判決各共有人均得聲請執行。", "law": "強制執行法§131。", "trap": "B變賣分割繼續拍賣、C原物分割不待執行取得所有權、D得聲請點交，皆對。"}, {"c": "禁止移轉假處分與物權執行 強執法§140", "k": "稱丙基於地上權勝訴執行『法院應駁回甲之禁止移轉假處分執行』→錯，禁止移轉假處分不禁止他人基於物權之執行，法院不駁回甲。", "law": "強制執行法§132、§133、§140。", "trap": "A命起訴、B執行後送達、C逾30日不得執行，皆對。"}, {"c": "查封效力及於後案 強執法§33", "k": "丙之假扣押聲請為已實施執行行為(甲之查封)之效力所及，執行法院不須再查封A土地。", "law": "強制執行法§33、§133。", "trap": "A/B優先順序、C再為查封登記之敘述，皆錯。"}, {"c": "有限公司之歸入權 §108、§54", "k": "甲違反競業禁止，所得產生未逾1年者，股東得以表決權過半數決議行使歸入權。", "law": "公司法§108、§109、§54、§115。", "trap": "A質詢得單獨為之、B查閱得單獨為之、D解任董事之敘述，皆有誤。"}, {"c": "公司之物上保證限制 §16", "k": "A公司章程未有對外保證條款，以土地為B公司設定抵押(物上保證)不合法。", "law": "公司法§16。", "trap": "A/B/C認合法或理由有誤。"}, {"c": "變更為閉鎖性公司須全體同意 §356-14", "k": "稱股份有限公司變更為閉鎖性『2/3出席過半數同意』→錯，§356-14須經全體股東同意。", "law": "公司法§106、§126、§356-14。", "trap": "A有限變股份、B兩合變更、D閉鎖變一般，皆對。"}, {"c": "分公司之設立 §3", "k": "未先變更章程而設立分公司，仍有效(分公司設立非章程絕對必要記載事項)。", "law": "公司法§3、§101、§393。", "trap": "A無效、B效力未定、C無對抗效力，皆非。"}, {"c": "非公開發行股東會不得書面開會 §172", "k": "稱A(非公開發行)與B(閉鎖性)均得章程允許股東會書面開會→錯，非公開發行公司股東會不得書面開會。", "law": "公司法§157、§172、§356-8。", "trap": "A累積投票制、B複數表決權之適用、C限制轉讓特別股，皆對。"}, {"c": "請求監察人對董事起訴 §214", "k": "繼續6個月以上，持有已發行股份總數1%以上之股東。", "law": "公司法§214。", "trap": "B 3%、C/D繼續1年，皆非。"}, {"c": "關係企業之代位求償權 §369-4", "k": "稱甲(持無表決權股)得以自己名義行使C公司求償權→錯，§369-4須繼續1年持有已發行『有表決權』股份1%股東。", "law": "公司法§369-4。", "trap": "A連帶賠償、B受益限度連帶、C債權人得代位，皆對。"}, {"c": "合併之股份收買請求權 §317", "k": "乙為被吸收之C公司股東，得主張股份收買請求權。", "law": "公司法§316-2、§317。", "trap": "甲為B公司股東(B非合併當事公司A、C)，無收買請求權。"}, {"c": "臨時動議之限制 §172", "k": "轉投資總額超過實收股本40%之同意，得以臨時動議提出。", "law": "公司法§172、§185、§209、§240、§241。", "trap": "A競業許可、B變更章程、C盈餘轉增資，皆須載明召集事由不得臨時動議。"}, {"c": "重整之聲請人 §282", "k": "稱相當於已發行股份總數金額達『5%』之公司債權人得聲請重整→錯，§282為達10%。", "law": "公司法§282。", "trap": "A 2/3受僱員工得聲請、C重整後職權停止、D重整關係人會議審查，皆對。"}, {"c": "董事會書面決議之成數 §205", "k": "本次會議不合法，贊成採書面會議之董事人數不足法定成數。", "law": "公司法§205。", "trap": "A/C/D認合法或門檻有誤。"}, {"c": "裁判解任董事之訴 §200", "k": "稱股東會未通過解任『監察人得隨時提起解任之訴』→錯，裁判解任之訴由股東提起，且須股東會後30日內。", "law": "公司法§199、§200。", "trap": "A特別決議解任、B持股3%、C股東會後30日內提起，皆對。"}, {"c": "相互投資之表決權限制 §369-10", "k": "A於B股東會行使之表決權不得超過B已發行有表決權股份總數1/3(1500萬÷3＝500萬股)。", "law": "公司法§369-10。", "trap": "B 300、C 200、D 0，皆非。"}, {"c": "不足額保險之比例分攤 §77", "k": "不足額保險(1000萬／1500萬)，損失900萬比例賠600萬，減損費用720萬比例償480萬，共1080萬元。", "law": "保險法§33、§77。", "trap": "A/B/C之計算有誤。"}, {"c": "人身保險僅締約時須保險利益 §16", "k": "人身保險僅締約時具保險利益即可，乙出嫁不影響契約效力，甲得請求保險給付。", "law": "保險法§16、§17。", "trap": "A契約終止、C喪失受益人資格、D扶養範圍內給付，皆錯。"}, {"c": "保險代位及於契約損害賠償請求權 §53", "k": "甲對乙(保全公司)有損害賠償請求權(契約債務不履行之損害賠償亦得代位)。", "law": "保險法§53。", "trap": "B/C/D限縮於侵權或排除契約請求權，皆錯。"}, {"c": "保險業投資不動產 §146-2", "k": "稱投資不動產『以即時利用為限但不以立即有收益為必要』→錯，應以即時利用並有收益為限。", "law": "保險法§146-2。", "trap": "A投資總額限制、B自用不動產限業主權益、D應經鑑價評價，皆對。"}, {"c": "定值保險之代位範圍 §53", "k": "定值保險賠付100萬，但代位求償以被保險人對第三人之實際損害(90萬)為限。", "law": "保險法§50、§53、§73。", "trap": "A 10、C 100、D不得代位，皆非。"}, {"c": "據實說明義務之因果關係 §64", "k": "乙得證明甲之死亡(車禍)非基於所隱匿之體況(甲狀腺)，保險人仍應給付。", "law": "保險法§64。", "trap": "A/B/C認保險人得拒賠或解約，皆錯。"}, {"c": "責任保險之和解參與權 §93", "k": "參與權僅含和解參加權(不含同意權)，保險人參與和解，除有正當理由外，於保險金額範圍內應受和解拘束。", "law": "保險法§93。", "trap": "A/B/C認含同意權或免責，皆錯。"}, {"c": "未滿15歲被保險人之死亡給付 §107", "k": "契約有效，但除喪葬費用之給付外，其餘死亡給付之約定於乙滿15歲時始生效力。", "law": "保險法§107。", "trap": "A效力未定、B契約無效、C死亡險部分無效，皆非。"}, {"c": "變更受益人於書面通知時生效 §111", "k": "變更受益人於要保人以書面通知保險人時生效(批註非生效要件)，受益人已變更為A大學。", "law": "保險法§110、§111。", "trap": "B/C/D認受益人仍為乙，皆錯。"}, {"c": "再保險之獨立性 §40、§42", "k": "稱原保險得約定『再保險不履行時保險人得拒絕或延遲給付』→錯，§42保險人不得以再保險人不履行為由拒絕或延遲給付。", "law": "保險法§39-§42。", "trap": "A再保險為責任保險、B約定被保險人得向再保險人請求、C再保險人不得向要保人請求保費，皆對。"}, {"c": "利益償還請求權 §22Ⅳ", "k": "票據上權利因時效或手續欠缺而消滅時，執票人始得主張利益償還請求權。", "law": "票據法§22Ⅳ。", "trap": "A不限最後被背書人、B償還義務人限發票人承兌人(不含背書人保證人)、C以所受利益為限。"}, {"c": "委任取款背書 §40", "k": "戊為丁之委任取款受任人，代丁行使權利，不得向委任人丁主張票據責任。", "law": "票據法§40。", "trap": "A甲、B乙、C丙(丁之前手)，戊得對之主張。"}, {"c": "非故意塗銷背書不影響效力 §38", "k": "己擅自(非執票人故意)塗銷丙之背書，不影響票據效力，丙仍負背書責任。", "law": "票據法§37、§38。", "trap": "A/B/D漏列丙或誤列己，皆非。"}, {"c": "期前追索之對象 §85", "k": "丁請求承兌遭拒得期前追索發票人甲、背書人乙丙、保證人B。", "law": "票據法§35、§85、§61。", "trap": "預備付款人C僅參加付款(承兌拒絕之期前追索不及於C)。"}, {"c": "本票保證人不適用裁定執行 §123", "k": "甲得向乙丙追索，追索無效後，僅得對發票人乙聲請裁定強制執行乙財產(保證人丙不適用本票裁定)。", "law": "票據法§123、§61。", "trap": "A/B/C認得對丙裁定，皆錯。"}, {"c": "撤銷付款委託與提示期限 §130、§135", "k": "提示期限(15日)經過後甲之撤銷付款委託生效，丙4/18提示時付款銀行B不得付款。", "law": "票據法§130、§132、§135。", "trap": "A已逾提示期限、B/C追索權之敘述有誤。"}, {"c": "已轉讓之平行線支票不得撤銷 §139", "k": "該支票經背書轉讓，不得撤銷平行線。", "law": "票據法§139。", "trap": "B/C/D認得在平行線內簽章撤銷，皆錯。"}, {"c": "偽造背書與背書連續 §15、§37", "k": "依外觀背書連續，但乙得以背書被偽造為由對抗丁，不負票據責任。", "law": "票據法§15、§37。", "trap": "A得對乙追索、C/D背書不連續之敘述，皆錯。"}, {"c": "內線交易之擬制所得法 §157-1", "k": "甲未賣出，其犯罪所得採擬制所得法計算(以消息公開後10營業日平均收盤價計算)。", "law": "證券交易法§157-1，最高法院大法庭見解。", "trap": "A未賣出非無所得、B應扣除稅費、D扣除他因素之敘述，皆有誤。"}, {"c": "庫藏股轉讓員工之限制 §28-2", "k": "收買自己股份轉讓員工時，得限制員工一定期間內不得轉讓，但最長不得超過2年。", "law": "證券交易法§28-2。", "trap": "A決議門檻、B數量比例、C金額上限之敘述，皆有誤。"}, {"c": "私募有價證券 §43-6", "k": "稱私募得於股東會決議之日起『2年內』分次辦理→錯，應為1年內。", "law": "證券交易法§43-6。", "trap": "B員工原股東無優先認購權、C事後15日內報請備查、D轉售限制，皆對。"}, {"c": "發起人之發行人責任 §5", "k": "稱募集設立公司在設立登記前『發起人不負發行人責任』→錯，§5發起人負發行人責任。", "law": "證券交易法§5、§7。", "trap": "B外國公司、C證券交易所為股份有限、D證券商為股份有限，皆對。"}, {"c": "財報不實之免責 §20-1", "k": "董事長乙如能證明已盡相當注意且有正當理由合理確信內容無隱匿，免負賠償責任。", "law": "證券交易法§20-1。", "trap": "A負無過失/連帶責任、C會計師舉證免責、D職員責任之敘述，皆有誤。"}, {"c": "財報案不得以董事會代決 §14-5", "k": "經董事長經理人會計主管簽章之年度財務報告案(須審計委員會通過及獨立董事同意意見)。", "law": "證券交易法§14-5。", "trap": "B財務主管任命、C簽證會計師委任、D重大資產交易，得由全體董事2/3同意行之。"}, {"c": "證券商之業務 §15、§16", "k": "稱證券經紀商辦理『行紀、居間、代理、承銷』→錯，承銷為承銷商業務(經紀商不含承銷)。", "law": "證券交易法§15、§16。", "trap": "A承銷商、C自營商、D證券商三種，皆對。"}, {"c": "公開收購條件之變更 §43-5", "k": "延長公開收購期間。", "law": "證券交易法§43-5、公開收購辦法。", "trap": "A調降價格、B降低數量、D縮短期間，原則上不得變更。"}, {"c": "審計委員會之組成 §14-4", "k": "審計委員會成員中至少1人應具備會計或財務專長。", "law": "證券交易法§14-4、§14-5。", "trap": "A須全體獨立董事組成、C董事會得以2/3同意變更、D各自獨立行使之敘述，皆有誤。"}, {"c": "假扣押與徵收代替利益 強執法§51、§115", "k": "稱假扣押債權人以代替利益為終局執行時『毋須另行取得執行名義』→錯，終局執行須另有執行名義。", "law": "強制執行法§51、§115、§133。", "trap": "A效力及於代替利益、B補償金提存、C債權不受徵收影響，皆對。"}, {"c": "投標保證金支票背書不連續 強執法§12", "k": "丙之保證金支票背書不連續，開標後不能補正，投標為廢標，駁回其聲明異議。", "law": "強制執行法§12、拍賣辦法。", "trap": "A非以程序終結駁回、B/C得補正或逕認有效之敘述，皆錯。"}, {"c": "拍賣物滅失之撤銷 強執法§113、民法§373", "k": "A屋於核發權利移轉證書『前』已滅失，丙得請求撤銷拍賣。", "law": "強制執行法§69、§113、民法§373。", "trap": "A/B海砂屋無瑕疵擔保、D核發後滅失危險已移轉拍定人。"}, {"c": "取得執行名義費用不得優先 強執法§29", "k": "稱丙取得『支付命令之費用』得優先受償→錯，取得執行名義之費用非執行費，不得優先受償。", "law": "強制執行法§28、§29。", "trap": "A抵押債權列入分配、B/D執行費得優先受償，皆對。"}, {"c": "可代替行為之執行 強執法§127、§128", "k": "稱拆除路障不履行『逕予管收』→錯，拆除路障為可代替行為得代履行(非管收)。", "law": "強制執行法§127、§128、§129。", "trap": "A/B怠金管收(針對容忍義務)、C得聲請拆除路障，皆對。"}, {"c": "假處分裁定廢棄須聲請撤銷 強執法§132", "k": "稱假處分裁定廢棄『不待債務人聲請即應撤銷』→錯，須債務人聲請撤銷。", "law": "強制執行法§132、§140。", "trap": "A送達同時或送達前執行、B 30日內聲請執行、D禁止行為之裁定應送達債務人，皆對。"}, {"c": "參與分配之時點 強執法§32", "k": "稱丁於拍定後始聲明參與分配『仍得受分配』→錯，應於標的物拍賣終結前聲明。", "law": "強制執行法§32、§34。", "trap": "A假扣押債權提存、C丙得逕行換價、D不妨礙終局執行，皆對。"}, {"c": "意思表示之擬制 強執法§130", "k": "判決確定時，視為甲已為移轉A地所有權登記之意思表示，無開始強制執行之必要。", "law": "強制執行法§130。", "trap": "A/C/D提存或給付證明時，非擬制時點。"}, {"c": "查封效力及於合併執行之後案 強執法§133", "k": "甲聲請假扣押執行之查封效力及於丙，甲撤回後臺北地院不得將查封登記除去。", "law": "強制執行法§133、§136。", "trap": "A/C/D認須另為查封或得詢問同意，皆錯。"}, {"c": "薪資債權之扣押效力 強執法§115-1", "k": "稱乙離職後扣押命令『一律失其效力』之敘述有誤。", "law": "強制執行法§115、§115-1。", "trap": "B效力限執行債權額範圍、C及於調薪增加部分、D丙得與乙合意終止僱傭，皆對。"}, {"c": "申報內部人 §22-1", "k": "董監經理人之配偶、未成年子女及為其持有股票者。", "law": "公司法§22-1。", "trap": "A董監經理人、C持股逾10%股東、D出資逾資本總額10%股東，皆為須申報之內部人。"}, {"c": "公司登記之撤銷 §9", "k": "負責人犯偽造文書罪辦理增資登記經判決有罪確定後，利害關係人得申請撤銷其增資登記。", "law": "公司法§7、§9。", "trap": "A資本額查核之時點、B補正後不撤銷、D變更登記資本額仍須查核，皆有誤。"}, {"c": "法人董事之設質 §27、§197-1", "k": "稱公開發行公司X將Y持股全數『設質』即喪失董事資格→錯，設質非轉讓(設質逾1/2停止表決權，非喪失資格)。", "law": "公司法§27、§197、§197-1。", "trap": "A得隨時改派、B改派補足任期、C持股全數轉讓喪失資格，皆對。"}, {"c": "有限公司之合併 §113", "k": "稱有限公司合併『須經全體股東同意』→錯，§113現行為股東表決權過半數之同意。", "law": "公司法§72、§73、§75、§113。", "trap": "B存續合併之存續公司須為股份有限、C通知債權人指定30日異議、D漏未通知不得對抗債權人，皆對。"}, {"c": "有限公司股東權限 §102、§111", "k": "會計年度終了之會計表冊承認，應經股東表決權過半數之同意。", "law": "公司法§102、§111、§110。", "trap": "A每股東一表決權(得章程按出資比例)、B出資移轉須其他股東過半同意、C同意增資不負承購義務。"}, {"c": "有限公司董事報酬 §108、§49", "k": "有限公司董事非有特約，不得向公司請求報酬。", "law": "公司法§108、§49、§115。", "trap": "A/B董事長選任須過半數同意、D競業之說明對象，皆有誤。"}, {"c": "公司虧損之處理 §211", "k": "稱虧損達實收資本額『三分之二』時董事會應報告股東會→錯，§211達實收資本額1/2時報告。", "law": "公司法§168-1、§211、§270、§282。", "trap": "A減資議案30日前交監察人查核、C資產不足抵債應聲請破產、D連續二年虧損不得公開發行，皆對。"}, {"c": "相互投資之表決權 §369-10", "k": "C公司持有A公司1%股份(相互投資未達1/3)，有表決權。", "law": "公司法§167、§179、§369-10。", "trap": "A/B收買股份之限制、D表決權有無之敘述，皆有誤。"}, {"c": "股東代表訴訟 §214", "k": "股東提代表訴訟時，法院得依聲請為原告選任律師為訴訟代理人。", "law": "公司法§214。", "trap": "A繼續6個月持股1%(非3%)、B向監察人請求(非董事會)、C裁判費超過60萬部分免收(非100萬)。"}, {"c": "員工酬勞之分派 §235-1", "k": "稱比率須為固定比例『不得為一定區間』→錯，得訂一定區間(如1-3%)。", "law": "公司法§235-1。", "trap": "A扣除累積虧損後計算、C董事會特別決議報告股東會、D董事長兼員工得受分派，皆對。"}, {"c": "閉鎖性股份有限公司 §356-1", "k": "稱閉鎖性公司『不得分次發行股份』→錯，得分次發行。", "law": "公司法§356-1、§356-4、§356-5。", "trap": "A股東不超過50人且非公開發行、C得經群眾募資平臺募資、D股份轉讓限制應載明章程，皆對。"}, {"c": "非公開發行公司之董事選舉 §192、§198", "k": "稱董事選舉『必須採候選人提名制』→錯，候選人提名制非強制(得章程訂定)。", "law": "公司法§192、§192-1、§198、§201。", "trap": "A得不設董事會、B採累積投票制、D缺額1/3於30日內補選，皆對。"}, {"c": "制止請求權 §194、§218-2", "k": "監察人B、股東C二人均能立即行使制止請求權，無優先次序之要求。", "law": "公司法§194、§218-2。", "trap": "A/B/C對行使要件及次序之敘述，皆有誤。"}, {"c": "控制從屬關係 §369-2", "k": "X持A 35%加從屬Y持25%共60%，X與A為控制從屬關係(增資前後均是)。", "law": "公司法§267、§369-2。", "trap": "A發行新股之決議、B出資方式、C限制轉讓2年之敘述，皆有誤。"}, {"c": "關係企業限於公司間 §369-1", "k": "關係企業限於公司間，B有限公司與C股份有限公司為公司(D商號、E有限合夥非公司)。", "law": "公司法§369-1。", "trap": "B 3、C 4、D 5，皆非。"}, {"c": "人壽保險之質借 §120", "k": "稱保險費付足『二年』以上方得質借→錯，§120付足保險費達一年以上即得質借。", "law": "保險法§116、§120、§122、§111。", "trap": "A催告屆30日停效、B年齡超限契約無效退費、C得變更受益人，皆對。"}, {"c": "代理人訂立保險契約 §46", "k": "稱代理人訂立『適用民法即可無庸載明代訂意旨』→錯，§46應載明代訂之意旨。", "law": "保險法§46、§47、§48、§49。", "trap": "A人身保險不得指示式無記名式、C合夥共有人訂立載明意旨、D一部自負額不得另保，皆對。"}, {"c": "傷害保險職業變更與危險無關 §59", "k": "未通知職業變更，但損害之發生(旅遊遇旅館失火)與危險增加無關，保險人仍應全額賠償。", "law": "保險法§59、§60、§131。", "trap": "A自動解除、B行使解除權、C僅請求損害賠償，皆錯。"}, {"c": "人身保險不得代位 §53、§103", "k": "A公司(火災保險=財產險)得代位求償；B公司(意外險=人身險)不得代位。", "law": "保險法§53、§103。", "trap": "A/B/D對代位之敘述有誤。"}, {"c": "保險契約為不要式不要物 §43", "k": "保險契約為不要式不要物契約，保險人核保時雙方意思已合致，契約成立生效，保險人應依約給付。", "law": "保險法§43、§44。", "trap": "A/B/C認契約未成立或要物，皆錯。"}, {"c": "違反特約條款之解除 §68", "k": "甲違反特約條款(航行不得超出臺北港)，乙如於知悉後一個月內解除契約，即無須理賠。", "law": "保險法§66-§69。", "trap": "A非即刻失效、C/D特約顯失公平之敘述有誤。"}, {"c": "責任保險直接請求權以契約有效為前提 §94", "k": "保險契約已解除(未繳費且違反特約)，保險人不負理賠責任，第三人之直接請求權亦無所附麗。", "law": "保險法§94。", "trap": "B/C/D認保險人仍應理賠，皆錯。"}, {"c": "同業公會之自律規範 §165-3", "k": "稱訂定自律規範『請專家審核後即可』→錯，應報主管機關核定。", "law": "保險法§165-3。", "trap": "B紛爭協調、C受託辦理事項、D得要求會員提供資料，皆對。"}, {"c": "保險輔助人之兼營限制 §163", "k": "稱兼有三資格者『得同時申領，代理人經紀人擇一』之敘述有誤(三者間有兼營限制)。", "law": "保險法§163。", "trap": "A經紀人善管注意忠實義務、C銀行擇一兼營、D經紀人領照要件，皆對。"}, {"c": "追索權時效 §22", "k": "執票人對前手之追索權，自到期日(10/1)起算1年，至次年9/30止，丁遲至次年10/2追索，乙有時效抗辯。", "law": "票據法§22Ⅱ。", "trap": "B/C時效末日、D未遵期提示之敘述，皆有誤。"}, {"c": "票據文義性 §5", "k": "票載金額為16萬元，甲應依票據文義支付16萬元(對善意執票人丙不得以原因關係抗辯)。", "law": "票據法§5、§11。", "trap": "A非無效、B/C得僅付10萬之敘述，皆錯。"}, {"c": "偽造背書與真正簽名人之責任 §15、§37", "k": "丁偽造丙之背書，丙不負責；戊為真正背書人，己得向戊行使追索權。", "law": "票據法§10、§15、§37。", "trap": "A甲(偽造乙簽名)、B乙(被偽造)、C丁(偽造人未以自己名義簽名)，皆非追索對象。"}, {"c": "期前追索之事由 §85", "k": "甲(發票人)死亡，非期前追索事由。", "law": "票據法§85。", "trap": "A丙拒絕承兌、C丙受破產宣告、D丙行蹤不明，皆得期前追索。"}, {"c": "未承兌付款人不負責與附條件背書 §36、§52", "k": "A公司未在票上承兌不負票據責任；乙之背書附條件視為無記載，乙負背書責任。丙得向甲(發票人)、乙(背書人)追索。", "law": "票據法§36、§52、§29。", "trap": "A/B/C含A公司，皆非。"}, {"c": "本票裁定限對發票人 §123", "k": "本票裁定強制執行限對發票人，乙(發票人)已死亡不得對繼承人丁裁定，丙為背書人不得裁定，僅甲。", "law": "票據法§123。", "trap": "B/C/D含丙或丁，皆非。"}, {"c": "本票不準用預備付款人 §124", "k": "本票背書人記載預備付款人(本票不準用預備付款人之規定)。", "law": "票據法§26、§35、§124。", "trap": "A委任取款背書、B塗銷背書、D禁止轉讓記載，皆為票據法所許。"}, {"c": "支票漏記發票日無效 §125", "k": "支票漏未記載發票日(絕對必要記載事項)，該支票無效。", "law": "票據法§11、§125。", "trap": "A實際發票日、B提示日、C視為見票即付，皆非。"}, {"c": "撤銷付款委託 §135", "k": "發票人於提示期限內，不得撤銷付款之委託。", "law": "票據法§135。", "trap": "A 3年、B/C發行滿1年之敘述，皆非。"}, {"c": "支票之提示與追索 §130、§132", "k": "發票地付款地均新北市(同一直轄市)，發票日後7日不提示，對發票人以外之前手喪失追索權。", "law": "票據法§128、§130、§131、§132。", "trap": "A票載發票日前不得付款、B支票無承兌人、D支票無到期日。"}, {"c": "審計委員會之召集 §14-5", "k": "稱審計委員會召集應於『三日前』通知→錯，準用董事會應於七日前通知(緊急情事除外)。", "law": "證券交易法§14-4、§14-5。", "trap": "A設審計委員會不設監察人、B經理人列席表決離席、D無法召開以全體董事2/3同意，皆對。"}, {"c": "薪資報酬委員會 §14-6", "k": "稱薪資報酬委員會『至少每年召開四次』→錯，至少每年召開2次。", "law": "證券交易法§14-6、設置辦法。", "trap": "A人數不少於三人、B得委任專業人員費用由公司負擔、C優於建議之公告申報，皆對。"}, {"c": "內部人持股變動申報 §25", "k": "持股逾10%股東持股變動於次月5日前向公司申報，公司於每月15日前彙總向主管機關申報。", "law": "證券交易法§25。", "trap": "A/B/D之日期，皆非。"}, {"c": "買回股份之金額上限 §28-2", "k": "買回總金額不得逾保留盈餘加已實現之資本公積(1億+2億)，法定盈餘公積不計入。", "law": "證券交易法§28-2。", "trap": "B 6億、C 7億、D 8億，皆非。"}, {"c": "無擔保轉換公司債之額度", "k": "無擔保轉換公司債原則不得逾全部資產減全部負債餘額之200%。", "law": "證券交易法§22、發行人募集與發行有價證券處理準則。", "trap": "A 50%、B 100%、D 400%，皆非。"}, {"c": "持股轉讓之限制 §22-2", "k": "稱『申報之日起3日後』向特定人轉讓→錯，§22-2應於申報之日起3日內向特定人轉讓。", "law": "證券交易法§22-2。", "trap": "A申報生效後向非特定人、C 3日內向特定人、D適用配偶未成年子女，皆對。"}, {"c": "公開招募之定義 §22Ⅲ", "k": "有價證券持有人為出售其持有股票而對非特定人招募之行為。", "law": "證券交易法§22Ⅲ、處理準則。", "trap": "A發起人募集設立、B發行前募集、D對特定人招募，皆非公開招募。"}, {"c": "證交法之發行人 §5", "k": "募集發行新股之C股份有限公司為發行人。", "law": "證券交易法§5。", "trap": "A總經理、B發起設立之發起人、D董事長，皆非發行人。"}, {"c": "獨立董事 §14-2", "k": "稱甲轉讓超過選任時持股1/2『獨立董事當然解任』→錯，獨立董事不適用持股轉讓當然解任之規定。", "law": "證券交易法§14-2、§14-4。", "trap": "A人數不少於三人、C均解任60日內補選、D審計委員會無法召開以全體董事2/3同意，皆對。"}, {"c": "短線交易歸入權之時效 §157", "k": "稱歸入權自獲得利益之日起『1年』間不行使而消滅→錯，§157Ⅳ為自獲得利益之日起2年。", "law": "證券交易法§157。", "trap": "B股東請求權、C董事連帶責任、D無刑事責任，皆對。"}, {"c": "聲明異議之限制 強執法§12", "k": "拍定收足價金核發權利移轉證書後，共有人丁以未獲通知優先承買聲明異議(該部分執行已終結)。", "law": "強制執行法§12、§102。", "trap": "A拍賣公告點交記載、B公告時間不足、D分配表送達時間不足，皆得聲明異議。"}, {"c": "執行名義之種類 強執法§4", "k": "公證人就違約金債務載明逕受強制執行之公證書，得為執行名義。", "law": "強制執行法§4、§4-1、公證法§13。", "trap": "A撤銷暴利行為判決(形成判決)、B假執行判決經廢棄、D外國判決須經許可執行，皆不得逕為執行名義。"}, {"c": "債權憑證與支付命令執行 強執法§27", "k": "債權經執行未獲足額清償，得依§27聲請核發債權憑證。", "law": "強制執行法§14、§18、§27。", "trap": "B時效抗辯於聲請前已拒絕之異議之訴、C停止執行須供擔保、D須檢附確定證明書，皆有誤。"}, {"c": "抵押權之併案受償 強執法§34", "k": "稱丙得拒絕參與分配『主張拍定後不得塗銷抵押權』→錯，§34抵押權人不論債權是否屆期均應併案受償，拍定後塗銷。", "law": "強制執行法§34、§98。", "trap": "A應通知丙參與分配、C拍定後聲明仍列入分配、D未聲明仍列入分配，皆對。"}, {"c": "拍賣之物之瑕疵擔保 強執法§69、§113", "k": "拍定人就拍賣物皆無物之瑕疵擔保請求權。", "law": "強制執行法§69、§113。", "trap": "B動產底價非必載、C動產不限投標、D動產未必預定底價。"}, {"c": "移轉命令之撤銷 強執法§115、§117", "k": "執行法院逕發移轉命令(未顧及丁參與分配)，應依職權撤銷該移轉命令。", "law": "強制執行法§32、§115、§117。", "trap": "A非無從救濟、B聲明異議撤銷、C不當得利之訴，皆非正確處置。"}, {"c": "交付代替物之執行 強執法§127", "k": "交付上市股票(代替物)，執行法院命乙履行，不履行得估算代履行費用裁定命乙支付，以此為執行名義拍賣B土地。", "law": "強制執行法§123、§127。", "trap": "A/B/D之執行方法有誤。"}, {"c": "遷讓房屋之執行 強執法§99、§124", "k": "強制乙遷離後乙當夜折返，甲毋須另取得執行名義，繳費聲請再為執行。", "law": "強制執行法§99、§124、§100。", "trap": "A得勸導自行遷讓、C得命同居之配偶丙遷離、D應協助弱勢尋覓安身處所。"}, {"c": "假扣押之追加查封 強執法§132", "k": "甲追加查封B地，雖逾收受假扣押裁定及第一次查封30日，仍屬合法(30日期間限開始執行)。", "law": "強制執行法§132。", "trap": "A/B/C認須於30日內或另取裁定，皆錯。"}, {"c": "拍定後之假扣押執行 強執法", "k": "拍定發移轉證書後丙於價金分配前聲請假扣押，執行法院應將甲受償餘額分配給丙並予提存。", "law": "強制執行法§133、§134。", "trap": "A駁回、B另具狀、C依比例分配，皆非。"}, {"c": "特別股之種類 §157", "k": "對經理人任免具否決權之特別股(逾越§157得發行範圍)。", "law": "公司法§157。", "trap": "A複數表決權、B當選一席董事、D附轉讓限制之特別股，非公開發行公司得發行。"}, {"c": "有限公司之增資 §106", "k": "丙贊成增資但不負按比例出資之義務(增資不強制原股東出資)。", "law": "公司法§106。", "trap": "A贊成者無出資義務、C/D不得自行邀第三人成為新股東(須全體股東同意)。"}, {"c": "出資方式 §43、§99-1", "k": "稱有限公司『得以勞務出資』→錯，僅無限公司股東得以勞務出資。", "law": "公司法§43、§99-1、§131、§156。", "trap": "B股份有限須2人以上發起、C有限公司一人得設立、D股份有限得以技術出資，皆對。"}, {"c": "關係企業之債權劣後 §369-7", "k": "稱A對B之貨款債權在B破產時『受償次序與一般債權人同』→錯，§369-7控制公司之債權應次於其他債權人受償(劣後)。", "law": "公司法§369-4、§369-7。", "trap": "A連帶賠償、B不得主張抵銷、D股東得代位請求，皆對。"}, {"c": "有限公司之清算與決議 §113", "k": "有限公司之清算，準用無限公司相關規定。", "law": "公司法§113、§71以下。", "trap": "B變更章程、C解散、D合併，均應經全體股東同意(非表決權多數)。"}, {"c": "公開發行新股之限制 §270", "k": "稱資產不足抵償債務者『仍得公開發行』→錯，§270資產不足抵償債務不得公開發行新股。", "law": "公司法§267、§268、§269、§270。", "trap": "A保留員工承購、C以現金為股款、D連續虧損不得發行優先特別股，皆對。"}, {"c": "重整人之選派 §290", "k": "B銀行雖為法人組織，法院仍得選派B銀行為重整人。", "law": "公司法§290。", "trap": "A得選董事為重整人、C/D對候選名單及重整監督人之敘述有誤。"}, {"c": "閉鎖性股份有限公司 §2、§356-1", "k": "稱公司種類增加為5種→錯，§2公司仍為4種(閉鎖性是股份有限公司之一種)。", "law": "公司法§2、§356-1以下。", "trap": "B必為非公開發行、C得經股權群眾募資平臺募資、D股東人數上限主管機關得增加，皆對。"}, {"c": "特別盈餘公積 §112、§237", "k": "有限公司得以章程訂定或經股東表決權2/3以上同意，另提特別盈餘公積。", "law": "公司法§112、§237。", "trap": "A/B/D對法定盈餘公積、表冊承認及員工酬勞之敘述有誤。"}, {"c": "變更章程之事項 §159、§277", "k": "縮減甲種特別股股東之股息與紅利(變更特別股權利)，須變更章程並經特別股股東會決議。", "law": "公司法§159、§277。", "trap": "A減資再增資(發行總數內)、C停止公開發行、D解散決議，不須變更章程。"}, {"c": "每季盈餘分派 §228-1", "k": "第一季終了分派盈餘，若發放現金股利，僅須經董事會決議通過。", "law": "公司法§228-1。", "trap": "A須章程規定、B累積虧損應先彌補、C發放股票股利須股東會決議。"}, {"c": "有限公司之董事代表權 §108", "k": "有限公司章程未設置董事長者，各董事均得代表公司。", "law": "公司法§108、§109。", "trap": "A設董事長之決議門檻、C/D監察權行使之敘述，皆有誤。"}, {"c": "合併議案之表決迴避", "k": "A公司(控制股東)及甲(法人代表董事)於合併議案皆無須迴避(企業併購之表決排除利害關係迴避)。", "law": "公司法§178、企業併購法§18Ⅵ。", "trap": "A/B/C認應迴避，皆錯。"}, {"c": "保險業之業務範圍 保險法§138", "k": "稱銀行得『擇一兼營保險代理人或經紀人或公證人』之敘述有誤。", "law": "保險法§138、§163。", "trap": "A財產保險業不得兼營人身保險(傷害健康除外)、C經紀人之執照、D代理人擇一申領，皆對。"}, {"c": "危險減少之保費核定 §59、§26", "k": "營業改純住宅使用(危險減少)，甲得請求X公司重新核定保險費。", "law": "保險法§26、§59、§60。", "trap": "A/B通知義務、C終止契約之敘述，皆有誤。"}, {"c": "承租人之保險利益 §14、§20", "k": "甲為附條件買賣之承租人，對汽車具保險利益。", "law": "保險法§14、§20。", "trap": "A非所有權人無保險利益、C取得所有權時方具利益、D之敘述，皆錯。"}, {"c": "訂約時之保險利益 §16、§17", "k": "契約訂立時甲為乙之配偶(有保險利益)，離婚後保險契約仍有效，甲得請求保險給付。", "law": "保險法§16、§17。", "trap": "A契約失效、B喪失受益人資格、D僅退還保費，皆錯。"}, {"c": "資本顯著不足之報酬限制 §143-6", "k": "降低後之報酬不得超過列入資本顯著不足等級前12個月平均報酬之70%。", "law": "保險法§143-4、§143-6。", "trap": "B 75%、C 80%、D 90%，皆非。"}, {"c": "人壽保險之停效復效 §116", "k": "申請恢復效力之期限，自停效日起不得低於2年，並不得遲於保險期間之屆滿日。", "law": "保險法§116。", "trap": "A催告屆30日停效(非20日)、B/C通知及復效之敘述有誤。"}, {"c": "傷害保險受益人故意 §121、§134", "k": "稱乙故意傷害甲者『A公司不負保險金給付之責』→錯，乙喪失受益權，但保險人對被保險人甲仍負責。", "law": "保險法§121、§133、§134。", "trap": "A意外失能死亡給付、B故意自殺犯罪不給付、C受益權之撤銷，皆對。"}, {"c": "保險契約之成立 §43、§44", "k": "A公司以簡訊告知核保通過，保險契約即成立(諾成)，除另以保費交付為要件外，A公司不得拒絕。", "law": "保險法§43、§44、民法§153。", "trap": "B/C/D認契約未成立或無須給付，皆錯。"}, {"c": "危險增加之比例責任 §59", "k": "職業變更涉危險增加但未通知，保險人A公司應依約負比例責任。", "law": "保險法§57、§59、§60。", "trap": "A/B解除契約、C全額負責，皆有誤。"}, {"c": "本票付款提示期限 §69、§124", "k": "定日付款本票，付款之提示應於到期日(3/18)或其後2日內，至遲3/20。", "law": "票據法§69、§124。", "trap": "A/B/D非提示期限末日。"}, {"c": "支票提示期間經過之付款 §136", "k": "稱『銀行不得僅支付1/5，必須先墊付全額』→錯，銀行得就存款餘額付款，不負墊付義務。", "law": "票據法§136。", "trap": "A得付款、B得不付款、C發票人得撤銷付款委託，皆對。"}, {"c": "支票提示期限 §130", "k": "發票地(苗栗)與付款地(高雄)不在同一省市縣者，發票日後15日內提示。", "law": "票據法§130。", "trap": "A 7日、B 14日、D 2個月，皆非。"}, {"c": "空白背書人之責任 §31、§39", "k": "乙在支票背面背書(空白背書)，應負背書責任。", "law": "票據法§31、§39、§144。", "trap": "A背書不連續、B回頭背書、D擔保契約，皆非免責或負責之正確理由。"}, {"c": "空白授權票據之善意取得 §11、§14", "k": "丙善意取得已具備應記載事項之票據，甲不得主張該票原欠缺應記載事項而拒絕付款。", "law": "票據法§11Ⅱ、§14。", "trap": "A票據無效、C/D對善意第三人之保護敘述有誤。"}, {"c": "本票裁定強制執行限對發票人 §123", "k": "稱向乙(背書人)追索『得直接聲請法院裁定強制執行』→錯，§123本票裁定強制執行限對發票人。", "law": "票據法§85、§123。", "trap": "A對發票人得聲請裁定、B發票人背書人連帶、D得直接向發票人追索，皆對。"}, {"c": "本票漏記到期日與利益償還 §22、§120", "k": "本票漏記到期日視為見票即付，丁怠於提示致追索權時效消滅，僅得向甲主張利益償還請求權。", "law": "票據法§22Ⅳ、§120Ⅱ。", "trap": "A票據非無效、B/C對票據責任之敘述有誤。"}, {"c": "背書附條件視為無記載 §36", "k": "背書附條件者，所附條件視為無記載，乙無條件負背書責任。", "law": "票據法§36。", "trap": "A背書無效、B匯票無效、C加註有效，皆非。"}, {"c": "付款延期 §70", "k": "付款人請求延期付款，須得執票人同意，但以提示後3日為限。", "law": "票據法§70。", "trap": "A無期限、B 2日、D 4日，皆非。"}, {"c": "延期召開股東常會 §170、§36", "k": "公開發行未上市櫃公司延期召開股東常會，僅須報請經濟部核准。", "law": "公司法§170、證券交易法§36。", "trap": "B金管會、C不得延期、D須二者核准，皆非。"}, {"c": "買回股份之董事會決議 §28-2", "k": "庫藏股決議須董事會2/3以上出席(7席須5席)、出席過半數同意，4席出席不符。", "law": "證券交易法§28-2。", "trap": "A配合附認股權公司債、B買回比率1.5%、D自集中市場買回，皆符合。"}, {"c": "常務董事中之獨立董事 §14-2", "k": "常務董事中獨立董事不得少於1人，且不得少於常務董事席次1/5。", "law": "證券交易法§14-2。", "trap": "A 1/3、B/D之人數比例，皆非。"}, {"c": "公開收購之解約 §43-5", "k": "公開收購人未於說明書記載之支付時間完成支付者，應賣人得不經催告逕行解約。", "law": "證券交易法§43-5、公開收購辦法。", "trap": "A非隨時任意解約、C/D縮短期間或調降價格之敘述有誤。"}, {"c": "集中保管之設質交付 §43", "k": "稱集中保管有價證券之設質交付『適用民法§908』→錯，以帳簿劃撥為之，不適用§908背書交付。", "law": "證券交易法§43。", "trap": "A帳簿劃撥交割、C無實體發行、D以集保事業名義登載股東名簿，皆對。"}, {"c": "重大消息之公開時點 §157-1", "k": "系爭重大消息於4/4下午輸入公開資訊觀測站時公開(主管機關規定之公開方式)。", "law": "證券交易法§157-1、重大消息範圍辦法。", "trap": "A/B/C媒體報導或記者會，非規定之公開方式。"}, {"c": "公證書為執行名義 強執法§4、公證法§13", "k": "積欠租金已載明逕受強制執行者，甲得以公證書為執行名義。", "law": "強制執行法§4、公證法§13。", "trap": "A租賃物返還亦得執行、B押租金返還未載明不得、D損害賠償未載明不得。"}, {"c": "變價分割之執行費 強執法§28-2", "k": "乙以變價分割確定判決聲請執行，以土地價額2/3(乙之應有部分)核定執行費。", "law": "強制執行法§28-2。", "trap": "A全部價額、C 1/3、D暫繳之敘述，皆非。"}, {"c": "債務人異議之訴 強執法§14", "k": "稱以抵銷為由異議之訴駁回確定後『得再以債權不成立為由提異議之訴』→錯，同一執行名義之債權不存在事由應一次主張(失權)。", "law": "強制執行法§14、§14-1。", "trap": "A支付命令未合法送達失效得異議、B/C得提異議之訴，皆對。"}, {"c": "移轉登記之擬制意思表示 強執法§130", "k": "移轉登記判決確定，視為乙已為意思表示，甲得逕向地政機關辦理，無須強制執行；甲未撤回執行聲請時應裁定駁回。", "law": "強制執行法§130。", "trap": "B/C/D命發執行命令或函請辦理，皆非。"}, {"c": "動產不動產合併拍賣 強執法§75", "k": "將不動產及其上動產合併拍賣時，適用關於不動產之拍賣規定。", "law": "強制執行法§75。", "trap": "A動產不得強制管理、B動產非必拍賣、C動產底價非必載。"}, {"c": "超額查封與繼續拍賣 強執法§50-1", "k": "查封A車鑑估100萬(債權100萬+丙抵押120萬)，甲得聲明於賣得價金不超過120萬及執行費時願負擔費用，請求繼續拍賣。", "law": "強制執行法§50-1、§51。", "trap": "A須詢問債權人、C抵押權不阻查封、D丙不得提第三人異議之訴。"}, {"c": "禁止處分假處分與終局執行 強執法§51", "k": "禁止處分之假處分僅禁止債務人任意處分，不禁止強制執行所為之處分，執行法院應准許丙之終局執行。", "law": "強制執行法§51、§140。", "trap": "B駁回、C不許換價、D命提供擔保撤銷，皆非。"}, {"c": "假扣押之執行 強執法§132、§134", "k": "對於假扣押之執行，不得藉聲請假處分而使其停止執行。", "law": "強制執行法§132、§134、§139。", "trap": "A裁定不待確定即可執行、B處分相對無效(非絕對)、D得發扣押命令。"}, {"c": "定暫時狀態處分之執行 強執法§140", "k": "稱處分經抗告廢棄確定『執行法院應依乙聲請命甲返還通行利益』→錯，通行利益無從返還(損害另循途徑)。", "law": "強制執行法§129、§140。", "trap": "A應送達於乙、B逾30日後妨礙仍得執行、C得聲請拆除圍牆，皆對。"}, {"c": "參與分配之要件 強執法§34", "k": "戊提出抵押權設定契約書、他項權利證明書及借據者(雖非執行名義)，仍得聲明參與分配(優先受償權)。", "law": "強制執行法§32、§34。", "trap": "A未屆期不視同已屆期、B假處分不得參與分配、D工資債權須有執行名義之敘述，皆有誤。"}]};
